    fun isFieldExist(db: SQLiteDatabase, tableName: String, fieldName: String?): Boolean {
        var isExist = false
        var res: Cursor? = null
        try {
            res = db.rawQuery("Select * from $tableName limit 1", null)
            val colIndex = res.getColumnIndex(fieldName)
            if (colIndex != -1) {
                isExist = true
            }
        } catch (e: java.lang.Exception) {
        } finally {
            try {
                res?.close()
            } catch (e1: java.lang.Exception) {
            }
        }
        return isExist
    }

    //INSERT SALESMAN HEADER ONLY SINGLE
    fun insertSalesman(mSalesman: UserData) {
        val db = this.writableDatabase
        if (checkUserExist(mSalesman.data!!.userInfo.id.toString())) {
            updateSalesman(mSalesman)
        } else {
            val contentValue = ContentValues()
            contentValue.put(KEY_SALESMAN_ID, mSalesman.data!!.userInfo.id)
            contentValue.put(KEY_SALESMAN_FIRST_NAME, mSalesman.data!!.userInfo.firstname)
            contentValue.put(KEY_SALESMAN_LAST_NAME, mSalesman.data!!.userInfo.lastname)
            contentValue.put(KEY_SALESMAN_TYPE_ID, mSalesman.data!!.userInfo.salesmanInfo.type.id)
            contentValue.put(KEY_SALESMAN_TYPE, mSalesman.data!!.userInfo.salesmanInfo.type.name)
            contentValue.put(KEY_SALESMAN_ROLE_ID, mSalesman.data!!.userInfo.salesmanInfo.role.id)
            contentValue.put(KEY_SALESMAN_ROLE, mSalesman.data!!.userInfo.salesmanInfo.role.name)
            contentValue.put(KEY_ACCESS_TOKEN, mSalesman.data!!.accessToken)
            contentValue.put(KEY_ORGANIZATION, mSalesman.data!!.userInfo.organisationId)
            //contentValue.put(KEY_ROUTE_ID, mSalesman.data!!.userInfo.salesmanInfo.route.id)
            contentValue.put(KEY_SALESMAN_USERNAME, mSalesman.data!!.userInfo.email)
            db.insert(TABLE_SALESMAN, null, contentValue)
        }
    }

