    fun insertJourneyPlan(mData: JourneyPlanData.JourneyPlan) {

        val db = this.writableDatabase

        if (mData.planType == "1") {

            for (mDay in mData.journeyPlanDays!!) {

                for (mCus in mDay!!.journeyPlanCustomers!!) {
                    val contentValue = ContentValues()
                    var weekNumber = "week${Utils.getWeekNumberOfMonth()}"
                    if (weekNumber == "week6") {
                        weekNumber = "week4"
                    }
                    contentValue.put(KEY_JOURNEY_ID, mData.id)
                    contentValue.put(KEY_DAY_NAME, mDay.dayName)
                    contentValue.put(KEY_WEEK_ID, weekNumber)
                    contentValue.put(KEY_ENFORCE_FLAG, mData.is_enforce)
                    contentValue.put(KEY_CUSTOMER_ID, mCus!!.customerId)
                    contentValue.put(KEY_CUS_SEQUENCE, mCus!!.dayCustomerSequence)
                    contentValue.put(KEY_START_TIME, mCus!!.dayStartTime.toString())
                    contentValue.put(KEY_END_TIME, mCus!!.dayEndTime.toString())

                    db.insert(TABLE_JOURNEY_PLAN_DETAIL, null, contentValue)
                }
            }
        } else {

            for (mWeek in mData.journeyPlanWeeks!!) {

                for (mDay in mWeek!!.journeyPlanDays!!) {

                    for (mCus in mDay!!.journeyPlanCustomers!!) {
                        val contentValue = ContentValues()
                        contentValue.put(KEY_JOURNEY_ID, mData.id)
                        contentValue.put(KEY_DAY_NAME, mDay.dayName)
                        contentValue.put(KEY_WEEK_ID, mWeek.weekNumber)
                        contentValue.put(KEY_ENFORCE_FLAG, mData.is_enforce)
                        contentValue.put(KEY_CUSTOMER_ID, mCus!!.customerId)
                        contentValue.put(KEY_CUS_SEQUENCE, mCus!!.dayCustomerSequence)
                        contentValue.put(KEY_START_TIME, mCus!!.dayStartTime.toString())
                        contentValue.put(KEY_END_TIME, mCus!!.dayEndTime.toString())

                        db.insert(TABLE_JOURNEY_PLAN_DETAIL, null, contentValue)
                    }
                }
            }
        }
    }

