    fun insertBrand(arrData: List<NodeBrand.NodeData>) {

        val db = this.writableDatabase
        for (mData in arrData) {

            if (!checkBrandExist(mData.id)) {
                val contentValue1 = ContentValues()
                contentValue1.put(KEY_ITEM_BRAND_ID, mData.id)
                contentValue1.put(KEY_ITEM_BRAND_NAME, mData.brand_name)
                db.insert(TABLE_ITEM_BRAND, null, contentValue1)
            }

            if (mData.subNode.isNotEmpty()) {
                for (mSubData in mData.subNode) {
                    if (!checkSubBrandExist(mSubData.id)) {
                        val contentValue1 = ContentValues()
                        contentValue1.put(KEY_ITEM_BRAND_ID, mData.id)
                        contentValue1.put(KEY_ITEM_SUB_BRAND_ID, mSubData.id)
                        contentValue1.put(KEY_ITEM_BRAND_NAME, mSubData.brand_name)
                        db.insert(TABLE_ITEM_SUB_BRAND, null, contentValue1)
                    }
                }
            }
        }
    }

