    fun insertItem(mItemData: List<ItemData.Data>) {
        val db = this.writableDatabase

        for (mData in mItemData) {
            if (!checkItemExist(mData.id.toString())) {
                val contentValue = ContentValues()
                contentValue.put(KEY_ITEM_ID, mData.id.toString())
                contentValue.put(KEY_ITEM_CODE, mData.itemCode)
                contentValue.put(KEY_ITEM_NAME, mData.itemName)
                contentValue.put(KEY_ITEM_MAJOR_CATEGORY, mData.majorCategory)
                contentValue.put(KEY_ITEM_BRAND, mData.brandId)
                contentValue.put(KEY_ITEM_GROUP, mData.groupId)
                contentValue.put(KEY_ITEM_BARCODE, mData.barcode)
                contentValue.put(KEY_ITEM_LOWER_UNIT, mData.lowerUnitId)
                contentValue.put(LOB_ID, mData.lobId)
                contentValue.put(KEY_ITEM_TAX_APPLY, mData.isTaxApply)
                contentValue.put(KEY_IS_ITEM_EXCISE_APPLY, mData.is_item_excise)
                if (mData.item_excise != null) {
                    contentValue.put(KEY_ITEM_EXCISE, mData.item_excise)
                } else {
                    contentValue.put(KEY_ITEM_EXCISE, "0")
                }

                if (mData.item_excise_uom_id != null) {
                    contentValue.put(KEY_ITEM_EXCISE_UOM, mData.item_excise_uom_id)
                } else {
                    contentValue.put(KEY_ITEM_EXCISE_UOM, "")
                }

                if (mData.vatPercentage != null)
                    contentValue.put(KEY_ITEM_VAT_PERC, mData.vatPercentage)

                if (mData.supervisor_category != null) {
                    contentValue.put(KEY_ITEM_SP_CAT_ID, mData.supervisor_category!!.id.toString())
                    contentValue.put(KEY_ITEM_SP_CAT_NAME, mData.supervisor_category!!.name)
                } else {
                    contentValue.put(KEY_ITEM_SP_CAT_ID, "")
                    contentValue.put(KEY_ITEM_SP_CAT_NAME, "")
                }

                db.insert(TABLE_ITEM, null, contentValue)

                mData.category

//                if (mData.lowerUOM != null)
//                //insert ItemLower Unit
//                    insertItemUOM(
//                        mData.lowerUnitId,
//                        mData.lowerUOM!!.name,
//                        mData.lowerUnitUPC,
//                        mData.lowerUnitPrice,
//                        mData.id.toString()
//                    )

                for (mUOM in mData.itemUOM) {
                    if (mData.itemUOM != null)
                    //insert Item UOM Unit
                        if (mUOM.uom != null)
                            insertItemUOM(
                                mUOM.uom!!.id.toString(),
                                mUOM.uom!!.name,
                                mUOM.uomUPC,
                                mUOM.uomPrice,
                                mUOM.itemId,
                                mUOM.uomType,
                                mUOM.saleEnable,
                                mUOM.returnEnable
                            )
                }


                if (mData.group != null)
                    insertItemGroup(mData)

                insertBrandCategory(mData)
            }
        }

    }

    private fun insertBrandCategory(mItemData: ItemData.Data) {
        val db = this.writableDatabase

        var isParentCategory = false
        try {
            if (mItemData.category!!.id.toString() != null) {
                if (checkIsCategory(mItemData.category!!.id.toString())) {
                    isParentCategory = true
                }
            }


            if (isParentCategory) {
                if (!checkBrandCategoryExist(
                        mItemData.category!!.id.toString(),
                        mItemData.brand!!.id.toString()
                    )
                ) {

                    val contentValue = ContentValues()
                    contentValue.put(KEY_ITEM_CATEGORY_ID, mItemData.category!!.id.toString())
                    contentValue.put(KEY_ITEM_BRAND_ID, mItemData.brand!!.id.toString())
                    contentValue.put(KEY_CATEGORY_NAME, mItemData.category!!.name)
                    contentValue.put(KEY_IS_SUB_CATEGORY, "0")
                    contentValue.put(
                        KEY_ITEM_SUB_CATEGORY_ID,
                        mItemData.category!!.id.toString()
                    )

                    db.insert(TABLE_ITEM_BRAND_CATEGORY, null, contentValue)
                }
            } else {

                var parentId = getParentCategoryId(mItemData.category!!.id.toString())
                var parentDetail = getParentCategoryDetail(parentId)

                if (!checkBrandCategoryExist(
                        parentDetail.get("categoryId").toString(),
                        mItemData.brand!!.id.toString()
                    )
                ) {

                    val contentValue = ContentValues()
                    contentValue.put(
                        KEY_ITEM_CATEGORY_ID,
                        parentDetail.get("categoryId").toString()
                    )
                    contentValue.put(KEY_ITEM_BRAND_ID, mItemData.brand!!.id.toString())
                    contentValue.put(KEY_CATEGORY_NAME, parentDetail.get("name").toString())
                    contentValue.put(KEY_IS_SUB_CATEGORY, "0")
                    contentValue.put(
                        KEY_ITEM_SUB_CATEGORY_ID,
                        parentDetail.get("categoryId").toString()
                    )
                    db.insert(TABLE_ITEM_BRAND_CATEGORY, null, contentValue)
                }

                if (!checkBrandCategoryExist(
                        mItemData.category!!.id.toString(),
                        mItemData.brand!!.id.toString()
                    )
                ) {

                    val contentValue = ContentValues()
                    contentValue.put(KEY_ITEM_CATEGORY_ID, mItemData.category!!.id.toString())
                    contentValue.put(KEY_ITEM_BRAND_ID, mItemData.brand!!.id.toString())
                    contentValue.put(KEY_CATEGORY_NAME, mItemData.category!!.name)
                    contentValue.put(
                        KEY_ITEM_SUB_CATEGORY_ID,
                        parentDetail.get("categoryId").toString()
                    )
                    contentValue.put(KEY_IS_SUB_CATEGORY, "1")
                    db.insert(TABLE_ITEM_BRAND_CATEGORY, null, contentValue)
                }
            }
        } catch (e: Exception) {
            e.toString()
        }


    }

    fun getParentCategoryId(mId: String): String {
        var mList = ""

        val db = this.readableDatabase

        try {
            var cursor = db.rawQuery(
                ("SELECT * FROM " +
                        TABLE_ITEM_SUB_CATEGORY + " WHERE " +
                        KEY_ITEM_SUB_CATEGORY_ID + "=?"), arrayOf<String>(mId)
            )

            if (cursor.moveToFirst()) {
                mList = cursor.getString(cursor.getColumnIndex(KEY_ITEM_CATEGORY_ID))
            }
            cursor.close()
        } catch (e: Exception) {
            e.printStackTrace()
        }

        return mList
    }

    private fun checkBrandCategoryExist(idd: String, brandId: String): Boolean {
        val db = this.writableDatabase
        var userExist = false
        val c = db.query(
            TABLE_ITEM_BRAND_CATEGORY,
            null,
            "$KEY_ITEM_CATEGORY_ID = ? AND $KEY_ITEM_BRAND_ID = ?",
            arrayOf<String>(idd, brandId),
            null,
            null,
            null
        )
            ?: return userExist
        while (c.moveToNext()) {
            userExist = true
        }
        c.close()
        return userExist
    }

