            contentValue.put(KEY_DUE_ON, mData.due_on)
            contentValue.put(KEY_TRN_NO, mData.trn_no)
            contentValue.put(
                KEY_OPEN_INVOICE, if (mData.no_of_invoice != null) {
                    mData.no_of_invoice.toString()
                } else "0"
            )

