                KEY_SALES_GEO_ENABLE, if (mData.sales_geo_checkin != null) {
                    mData.sales_geo_checkin.toString()
                } else "0"
            )

            contentValue.put(
                KEY_RETURN_GEO_ENABLE, if (mData.return_geo_checkin != null) {
                    mData.return_geo_checkin.toString()
                } else "0"
            )
            contentValue.put(
                KEY_COLL_GEO_ENABLE, if (mData.collection_geo_checkin != null) {
                    mData.collection_geo_checkin.toString()
                } else "0"
            )
            contentValue.put(
                KEY_CAPTURE_LOC_ENABLE, if (mData.capture_location_enable != null) {
                    mData.capture_location_enable.toString()
                } else "0"
            )
            contentValue.put(
                KEY_GEO_ENABLE, if (mData.geo_checking != null) {
                    mData.geo_checking.toString()
                } else "0"
            )

            if (mData.parent_customer != null) {
                contentValue.put(KEY_PARENT_CODE, mData.parent_customer!!.customer_code)
                contentValue.put(KEY_PARENT_NAME, mData.parent_customer!!.firstname)
            } else {
                contentValue.put(KEY_PARENT_CODE, "")
                contentValue.put(KEY_PARENT_NAME, "")
            }


            if (mData.accountRelease != null) {
                insertCustomerApproveDays(
                    mData.userDetail.id.toString(),
                    mData.accountRelease!!.no_of_days_approved!!,
                    mData.accountRelease!!.end_date
                )
            }

            if (mData.approveCreditLimit != null) {

                var mOverdue = "0"
                if (mData.approveCreditLimit!!.total_outstanding != null) {
                    if (mData.approveCreditLimit!!.total_outstanding.isNotEmpty()) {
                        mOverdue = mData.approveCreditLimit!!.total_outstanding
                    }
                }
                insertCustomerApprove(
                    mData.userDetail.id.toString(),
                    mData.approveCreditLimit!!.approved_amount!!.toString(),
                    mData.approveCreditLimit!!.no_of_days_approved!!.toString(),
                    mData.approveCreditLimit!!.end_date,
                    mOverdue
                )
            }


            if (mData.customer_block_types != null) {
                if (mData.customer_block_types!!.isEmpty()) {
                    contentValue.put(IS_SALE_BLOCK, "0")
                    contentValue.put(IS_ORDER_BLOCK, "0")
                    contentValue.put(IS_RETURN_BLOCK, "0")
                    // contentValue.put(IS_OVERDUE, "0")
                } else {
                    contentValue.put(IS_SALE_BLOCK, "0")
                    contentValue.put(IS_ORDER_BLOCK, "0")
                    contentValue.put(IS_RETURN_BLOCK, "0")
                    // contentValue.put(IS_OVERDUE, "0")
                    for (mBlockTy in mData.customer_block_types!!) {
                        if (mBlockTy.type == "Return") {
                            contentValue.put(IS_RETURN_BLOCK, "0")
                        } else if (mBlockTy.type == "Order") {
                            contentValue.put(IS_ORDER_BLOCK, "0")
                        } else if (mBlockTy.type == "Sales") {
                            contentValue.put(IS_SALE_BLOCK, "0")
                        } else if (mBlockTy.type == "Credit Limit") {
                            // contentValue.put(IS_OVERDUE, "0")
                        }
                    }
                }
            } else {
                contentValue.put(IS_SALE_BLOCK, "0")
                contentValue.put(IS_ORDER_BLOCK, "0")
                contentValue.put(IS_RETURN_BLOCK, "0")
                //contentValue.put(IS_OVERDUE, "0")
                contentValue.put(IS_UNBLOCK_REQ, "0")
            }

            if (!checkCustomerExist(mData.userDetail.id.toString())) {
                contentValue.put(IS_OVERDUE, "0")
                db.insert(TABLE_CUSTOMER, null, contentValue)
                if (mData.isLob == 1) {
                    insertCustomerLob(
                        mData.customerlob!!,
                        mData.userDetail.id,
                        "insert",
                        mLobId
                    )
                }
            } else {

                if (!checkOverDueCount(mData.userDetail.id.toString())) {
                    if (!checkOverDueLimitCount(mData.userDetail.id.toString())) {
                        contentValue.put(IS_OVERDUE, "0")
                    }
                }
                db.update(
                    TABLE_CUSTOMER,
                    contentValue,
                    "$KEY_CUSTOMER_ID = ?",
                    arrayOf<String>(mData.userDetail.id.toString())
                )

                if (mData.isLob == 1) {
                    insertCustomerLob(
                        mData.customerlob!!,
                        mData.userDetail.id,
                        "update",
                        mLobId
                    )
                }
            }
        }

    }

