    fun insertCustomerLob(
        mData: List<CustomerData.DataCustomer.Customerlob>,
        custId: Int,
        mType: String,
        mLobId: String
    ) {
        val db = this.writableDatabase

        for (mData in mData) {

            val contentValue = ContentValues()
            contentValue.put(KEY_CUST_ID, mData.id.toString())
            contentValue.put(KEY_CUSTOMER_ID, custId)
            contentValue.put(CUSTOMER_TYPE_ID, mData.customer_type_id)
            contentValue.put(CUSTOMER_INFO_ID, mData.customer_info_id)
            contentValue.put(CUSTOMER_GROUP_ID, mData.customer_group_id)
            contentValue.put(CUSTOMER_CATEGORY_ID, mData.customer_category_id)
            contentValue.put(KEY_ROUTE_ID, mData.route_id)
            contentValue.put(KEY_REGION_ID, mData.region_id)
            contentValue.put(
                KEY_REGION_NAME, if (mData.region != null) {
                    mData.region!!.name
                } else ""
            )
            contentValue.put(KEY_CHANNEL_ID, mData.channel_id)
            contentValue.put(LOB_ID, mData.lob_id)
            contentValue.put(KEY_AMOUNT, mData.amount)
            contentValue.put(BALANCE, mData.balance)
            contentValue.put(KEY_OPEN_INVOICE, "0")
            contentValue.put(
                KEY_CHANNEL_NAME, if (mData.channel != null) {
                    mData.channel!!.name
                } else ""
            )
            contentValue.put(
                LOB_NAME, if (mData.lob != null) {
                    mData.lob!!.name
                } else ""
            )
            contentValue.put(KEY_SALES_ORG_ID, mData.sales_organisation_id)
            if (mData.sales_organisation != null) {
                contentValue.put(KEY_SALES_ORG_NAME, mData.sales_organisation!!.name)
            } else {
                contentValue.put(KEY_SALES_ORG_NAME, "")
            }

            contentValue.put(
                KEY_CREDIT_LIMIT, if (mData.credit_limit != null) {
                    mData.credit_limit
                } else "0"
            )
            contentValue.put(KEY_CREDIT_DAYS, mData.credit_days)
            contentValue.put(KEY_PAYMENT_TERM_ID, mData.payment_term_id)
            contentValue.put(KEY_DUE_ON, mData.due_on)

            if (mLobId == mData.lob_id.toString()) {
                if (mData.customer_block_types!!.isNotEmpty()) {
                    for (mLobC in mData.customer_block_types!!) {
                        if (mLobC.type == "Credit Limit") {

                            var isOver = ""
                            if (mLobC.is_block == "1") {
                                isOver = "1"
                            } else {
                                isOver = "0"
                            }

                            val contentValues = ContentValues()
                            contentValues.put(IS_OVERDUE, isOver)
                            db.update(
                                TABLE_CUSTOMER, contentValues,
                                "$KEY_CUSTOMER_ID =?", arrayOf<String>(custId.toString())
                            )
                        }
                    }
                }
            }

            if (!checkCUstomerLobExist(custId.toString(), mData.lob_id.toString())) {
                db.insert(TABLE_CUSTOMER_LOB, null, contentValue)
            } else {
                db.update(
                    TABLE_CUSTOMER_LOB,
                    contentValue,
                    "$KEY_CUSTOMER_ID = ? AND  $LOB_ID = ?",
                    arrayOf<String>(custId.toString(), mData.lob_id.toString())
                )
            }
        }

    }

