    //Insert PDP
    fun insertPriceNewPDP(arrData: List<PDPPricingData.PricePPData>) {
        val db = this.writableDatabase
        try {
            for (mData in arrData) {
                if (mData.plandata.isNotEmpty()) {
                    for (mPlan in mData.plandata) {
                        for (mItem in mPlan.planItem) {
                            val contentValue = ContentValues()
                            contentValue.put(KEY_ITEM_ID, getItemId(mItem.item_code))
                            contentValue.put(KEY_UOM_ID, mItem.item_uom_id.toString())
                            if (mItem.price != null) {
                                contentValue.put(KEY_PRICE, mItem.price.toString())
                            } else {
                                contentValue.put(KEY_PRICE, "0")
                            }
                            contentValue.put(
                                KEY_PLAN_ID,
                                mPlan.price_disco_promo_plans_id.toString()
                            )
                            contentValue.put(
                                KEY_PLAN_NAME,
                                mPlan.price_disco_promo_plans_name.toString()
                            )
                            contentValue.put(KEY_COMBINATION_KEY_VALUE, mPlan.combination_key_value)
                            contentValue.put(KEY_COMBINATION_KEY, mPlan.combination_plan_key_id)
                            contentValue.put(
                                KEY_CUSTOMER_ID,
                                getCustomerId(mData.customer_code)
                            )

                            if (mPlan.price_disco_promo_plans_name == "ReSalable SP1" ||
                                mPlan.price_disco_promo_plans_name == "ReSalable SP2" ||
                                mPlan.price_disco_promo_plans_name == "ReSalable SP3"
                            ) {
                                contentValue.put(KEY_PLAN_RESALABLE, "1")
                            } else {
                                contentValue.put(KEY_PLAN_RESALABLE, "0")
                            }
                            db.insert(TABLE_PDP_PRICE_TABLE, null, contentValue)
                        }
                    }
                }
            }
        } catch (e: java.lang.Exception) {

        }

    }

    //Insert PDP
    fun insertPDP(arrData: List<PDPData.PriceData>) {
        val db = this.writableDatabase

        for (mData in arrData) {
            if (!checkPDPPriceItemExist(mData.id.toString())) {

                var keyValue = mData.combination_key_value
                var keyId = ""
                var mSplit = keyValue.split("/")
                for (mString in mSplit) {
                    if (mString == "Country") {
                        keyId = keyId + "1"
                    } else if (mString == "Region") {
                        keyId = keyId + "2"
                    } else if (mString == "Area") {
                        keyId = keyId + "3"
                    } else if (mString == "Route") {
                        keyId = keyId + "4"
                    } else if (mString == "Sales Organisation") {
                        keyId = keyId + "5"
                    } else if (mString == "Channel") {
                        keyId = keyId + "6"
                    } else if (mString == "Customer Category") {
                        keyId = keyId + "7"
                    } else if (mString == "Customer") {
                        keyId = keyId + "8"
                    } else if (mString == "Major Category") {
                        keyId = keyId + "9"
                    } else if (mString == "Item Group") {
                        keyId = keyId + "10"
                    } else if (mString == "Material") {
                        keyId = keyId + "11"
                    }
                }

                if (keyId == "11") {
                    if (mData.pdpItem.isNotEmpty()) {
                        for (mItem in mData.pdpItem) {
                            val contentValue = ContentValues()
                            contentValue.put(KEY_ITEM_ID, mItem.item_id.toString())
                            contentValue.put(KEY_UOM_ID, mItem.item_uom_id.toString())
                            if (mItem.price != null) {
                                contentValue.put(KEY_PRICE, mItem.price.toString())
                            } else {
                                contentValue.put(KEY_PRICE, "0")
                            }
                            contentValue.put(KEY_PLAN_ID, mData.id.toString())
                            contentValue.put(KEY_PRIORITY_SEQ, mData.priority_sequence)
                            contentValue.put(KEY_COMBINATION_KEY_VALUE, keyId)
                            contentValue.put(KEY_COMBINATION_KEY, keyValue)
                            contentValue.put(KEY_COUNTRY_ID, "")
                            contentValue.put(KEY_REGION_ID, "")
                            contentValue.put(KEY_AREA_ID, "")
                            contentValue.put(KEY_ROUTE_ID, "")
                            contentValue.put(KEY_SALES_ORD_ID, "")
                            contentValue.put(KEY_CHANNEL_ID, "")
                            contentValue.put(KEY_CUST_CATEGORY_ID, "")
                            contentValue.put(KEY_CUSTOMER_ID, "")
                            contentValue.put(KEY_ITEM_MAJOR_CATEGORY, "")
                            contentValue.put(KEY_ITEM_GROUP_ID, "")
                            db.insert(TABLE_PDP_PRICE_DETAIL, null, contentValue)
                        }
                    }
                } else if (keyId == "411" || keyId == "410" || keyId == "49") {
                    if (mData.pdpRoute.isNotEmpty() && mData.pdpItem.isNotEmpty()) {
                        for (mROute in mData.pdpRoute) {
                            for (mItem in mData.pdpItem) {
                                val contentValue = ContentValues()
                                contentValue.put(KEY_ITEM_ID, mItem.item_id.toString())
                                contentValue.put(KEY_UOM_ID, mItem.item_uom_id.toString())
                                if (mItem.price != null) {
                                    contentValue.put(KEY_PRICE, mItem.price.toString())
                                } else {
                                    contentValue.put(KEY_PRICE, "0")
                                }
                                contentValue.put(KEY_PLAN_ID, mData.id.toString())
                                contentValue.put(KEY_PRIORITY_SEQ, mData.priority_sequence)
                                contentValue.put(KEY_COMBINATION_KEY_VALUE, keyId)
                                contentValue.put(KEY_COMBINATION_KEY, keyValue)
                                contentValue.put(KEY_COUNTRY_ID, "")
                                contentValue.put(KEY_REGION_ID, "")
                                contentValue.put(KEY_AREA_ID, "")
                                contentValue.put(KEY_ROUTE_ID, mROute.route_id)
                                contentValue.put(KEY_SALES_ORD_ID, "")
                                contentValue.put(KEY_CHANNEL_ID, "")
                                contentValue.put(KEY_CUST_CATEGORY_ID, "")
                                contentValue.put(KEY_CUSTOMER_ID, "")
                                contentValue.put(KEY_ITEM_MAJOR_CATEGORY, "")
                                contentValue.put(KEY_ITEM_GROUP_ID, "")
                                db.insert(TABLE_PDP_PRICE_DETAIL, null, contentValue)
                            }
                        }
                    }
                } else if (keyId == "511" || keyId == "510" || keyId == "59") {
                    if (mData.pdpSalesOrg.isNotEmpty() && mData.pdpItem.isNotEmpty()) {
                        for (mSales in mData.pdpSalesOrg) {
                            for (mItem in mData.pdpItem) {
                                val contentValue = ContentValues()
                                contentValue.put(KEY_ITEM_ID, mItem.item_id.toString())
                                contentValue.put(KEY_UOM_ID, mItem.item_uom_id.toString())
                                if (mItem.price != null) {
                                    contentValue.put(KEY_PRICE, mItem.price.toString())
                                } else {
                                    contentValue.put(KEY_PRICE, "0")
                                }
                                contentValue.put(KEY_PLAN_ID, mData.id.toString())
                                contentValue.put(KEY_PRIORITY_SEQ, mData.priority_sequence)
                                contentValue.put(KEY_COMBINATION_KEY_VALUE, keyId)
                                contentValue.put(KEY_COMBINATION_KEY, keyValue)
                                contentValue.put(KEY_COUNTRY_ID, "")
                                contentValue.put(KEY_REGION_ID, "")
                                contentValue.put(KEY_AREA_ID, "")
                                contentValue.put(KEY_ROUTE_ID, "")
                                contentValue.put(KEY_SALES_ORD_ID, mSales.sales_org_id)
                                contentValue.put(KEY_CHANNEL_ID, "")
                                contentValue.put(KEY_CUST_CATEGORY_ID, "")
                                contentValue.put(KEY_CUSTOMER_ID, "")
                                contentValue.put(KEY_ITEM_MAJOR_CATEGORY, "")
                                contentValue.put(KEY_ITEM_GROUP_ID, "")
                                db.insert(TABLE_PDP_PRICE_DETAIL, null, contentValue)
                            }
