    fun insertCustomerPriceMasafi(
        arrData: List<CustomerPriceData.CustomerItemPrice>,
        mTYpe: String,customerCode: String,customerId: String
    ) {
        val db = this.writableDatabase

        for (mItem in arrData) {
            val contentValue = ContentValues()
            contentValue.put(KEY_ITEM_ID, mItem.itemId.toString())
            contentValue.put(KEY_UOM_ID, mItem.item_uom_id)

            contentValue.put(
                KEY_PROMOTION_ID,
                ""
            )

            contentValue.put(
                KEY_NAME,
                customerCode
            )
            contentValue.put(
                KEY_CUSTOMER_ID,
                customerId
            )

            contentValue.put(KEY_PRICE, mItem.itemDiscount!!.item_price)
            contentValue.put(KEY_TYPE, mTYpe)
            db.insert(TABLE_MASAFI_PRICE, null, contentValue)

        }
    }

    fun insertPriceMasafi(arrData: List<PriceMFData.PriceFData>, mTYpe: String) {
        val db = this.writableDatabase

        for (mItem in arrData) {
            val contentValue = ContentValues()
            contentValue.put(KEY_ITEM_ID, mItem.item_id)
            contentValue.put(KEY_UOM_ID, mItem.item_uom_id.toString())

            contentValue.put(
                KEY_PROMOTION_ID,
                mItem.price_disco_promo_plan_id
            )

            if (mTYpe == "Channel") {
                contentValue.put(
                    KEY_NAME,
                    mItem.channel.name
                )
                contentValue.put(
                    KEY_CUSTOMER_ID,
                    mItem.channel_id
                )
                if (mItem.price != null) {
                    contentValue.put(KEY_PRICE, mItem.price.toString())
                } else {
                    contentValue.put(KEY_PRICE, "0")
                }
            } else if (mTYpe == "Sub Channel") {
                contentValue.put(
                    KEY_NAME,
                    mItem.subchannel.name
                )
                contentValue.put(
                    KEY_CUSTOMER_ID,
                    mItem.sub_channel_id
                )
                if (mItem.price != null) {
                    contentValue.put(KEY_PRICE, mItem.price.toString())
                } else {
                    contentValue.put(KEY_PRICE, "0")
                }
            } else {
                if (mItem.customer_info.size > 0) {
                    contentValue.put(
                        KEY_NAME,
                        mItem.customer_info[0].customer_code
                    )
                    contentValue.put(
                        KEY_CUSTOMER_ID,
                        mItem.customer_info[0].user_id
                    )
                } else {
                    contentValue.put(
                        KEY_NAME,
                        ""
                    )
                    contentValue.put(
                        KEY_CUSTOMER_ID,
                        ""
                    )
                }

                if (mItem.customer_price != null) {
                    contentValue.put(KEY_PRICE, mItem.customer_price.toString())
                } else {
                    contentValue.put(KEY_PRICE, "0")
                }

            }

            contentValue.put(KEY_TYPE, mTYpe)
            db.insert(TABLE_MASAFI_PRICE, null, contentValue)

        }
    }

    fun getLastLocusVisitSequnece(): String {
        var mList: String = "0"

        val db = this.readableDatabase

        val cursor = db.rawQuery(
            "SELECT is_sequence FROM visited_locus ORDER BY is_sequence DESC LIMIT 1",
            null
        )

//        var cursor = db.rawQuery(
//            ("SELECT * FROM " +
//                    TABLE_VISITED_LOCUS + " WHERE " +
//                    KEY_REASON_TYPE + "=?"), arrayOf<String>("Visit Reason")
//        )

        try {
            if (cursor.moveToFirst()) {
                do {
                    mList = cursor.getString(cursor.getColumnIndex(KEY_IS_SEQUENCE))
                } while (cursor.moveToNext())
            }
        } finally {
            try {
                db.close()
            } catch (ignore: Exception) {
            }
        }

        return mList
    }

