    fun insertPDPPrice(arrData: List<PDPData.PriceData>) {
        val db = this.writableDatabase

        for (mData in arrData) {

            if (!checkPDPPromoItemExist(mData.id.toString())) {

                var keyValue = mData.combination_key_value
                var keyId = ""
                var mSplit = keyValue.split("/")
                for (mString in mSplit) {
                    if (mString == "Country") {
                        keyId = keyId + "1"
                    } else if (mString == "Region") {
                        keyId = keyId + "2"
                    } else if (mString == "Area") {
                        keyId = keyId + "3"
                    } else if (mString == "Route") {
                        keyId = keyId + "4"
                    } else if (mString == "Sales Organisation") {
                        keyId = keyId + "5"
                    } else if (mString == "Channel") {
                        keyId = keyId + "6"
                    } else if (mString == "Customer Category") {
                        keyId = keyId + "7"
                    } else if (mString == "Customer") {
                        keyId = keyId + "8"
                    } else if (mString == "Major Category") {
                        keyId = keyId + "9"
                    } else if (mString == "Item Group") {
                        keyId = keyId + "10"
                    } else if (mString == "Material") {
                        keyId = keyId + "11"
                    }
                }

                Log.e("ketid", keyId)
                if (keyId == "811") {
                    for (mROute in mData.pdpCustomer) {
                        for (mItem in mData.pdpItem) {

                            val contentValue = ContentValues()
                            contentValue.put(KEY_ITEM_ID, mItem.item_id)
                            contentValue.put(KEY_UOM_ID, mItem.item_uom_id.toString())
                            if (mItem.price != null) {
                                contentValue.put(KEY_PRICE, mItem.price.toString())
                            } else {
                                contentValue.put(KEY_PRICE, "0")
                            }
                            contentValue.put(
                                KEY_PLAN_ID,
                                mData.id
                            )
                            contentValue.put(
                                KEY_PLAN_NAME,
                                mData.name
                            )
                            contentValue.put(KEY_COMBINATION_KEY_VALUE, mData.combination_key_value)
                            contentValue.put(KEY_COMBINATION_KEY, "")
                            contentValue.put(
                                KEY_CUSTOMER_ID,
                                mROute.customer_info.user_id
                            )


                            contentValue.put(KEY_PLAN_RESALABLE, "0")
                            db.insert(TABLE_PDP_PRICE_TABLE, null, contentValue)

                        }
                    }
                } else if (keyId == "611") {
                    for (mROute in mData.pdpChannel) {
                        for (mItem in mData.pdpItem) {

                            val contentValue = ContentValues()
                            contentValue.put(KEY_ITEM_ID, mItem.item_id)
                            contentValue.put(KEY_UOM_ID, mItem.item_uom_id.toString())
                            if (mItem.price != null) {
                                contentValue.put(KEY_PRICE, mItem.price.toString())
                            } else {
                                contentValue.put(KEY_PRICE, "0")
                            }
                            contentValue.put(
                                KEY_PLAN_ID,
                                mData.id
                            )
                            contentValue.put(
                                KEY_PLAN_NAME,
                                mData.name
                            )
                            contentValue.put(KEY_COMBINATION_KEY_VALUE, mData.combination_key_value)
                            contentValue.put(KEY_COMBINATION_KEY, "")
                            contentValue.put(
                                KEY_CHANNEL_ID,
                                mROute.channel_id
                            )


                            contentValue.put(KEY_PLAN_RESALABLE, "0")
                            db.insert(TABLE_PDP_CHANNEL_PRICE_TABLE, null, contentValue)

                        }
                    }
                }
            }


        }

    }

