    //Insert PDP Disocunt
    fun insertPDPDiscount(arrData: List<PDPData.PriceData>) {
        val db = this.writableDatabase

        for (mData in arrData) {
            if (!checkPDPDiscountItemExist(mData.id.toString())) {

                var keyValue = mData.combination_key_value
                var keyId = ""
                var mSplit = keyValue.split("/")
                for (mString in mSplit) {
                    if (mString == "Country") {
                        keyId = keyId + "1"
                    } else if (mString == "Region") {
                        keyId = keyId + "2"
                    } else if (mString == "Area") {
                        keyId = keyId + "3"
                    } else if (mString == "Route") {
                        keyId = keyId + "4"
                    } else if (mString == "Sales Organisation") {
                        keyId = keyId + "5"
                    } else if (mString == "Channel") {
                        keyId = keyId + "6"
                    } else if (mString == "Customer Category") {
                        keyId = keyId + "7"
                    } else if (mString == "Customer") {
                        keyId = keyId + "8"
                    } else if (mString == "Major Category") {
                        keyId = keyId + "9"
                    } else if (mString == "Item Group") {
                        keyId = keyId + "10"
                    } else if (mString == "Material") {
                        keyId = keyId + "11"
                    } else if (mString == "Sub Channel") {
                        keyId = keyId + "12"
                    } else if (mString == "Parent Customer") {
