    //Update Customer Visit
    fun updateCustomerShopStatus(
        customerId: String,
        status: String
    ): Int {
        val contentValues = ContentValues()
        contentValues.put(KEY_SHOP_STATUS, status)
        val db = this.writableDatabase
        val i = db.update(
            TABLE_CUSTOMER,
            contentValues,
            "$KEY_CUSTOMER_ID = ?",
            arrayOf<String>(customerId)
        )
        return i
    }

    //Insert Visited Customer
    fun insertVisitedCustomer(mData: VisitedList, mStatus: String) {
        val db = this.writableDatabase

        val contentValue = ContentValues()
        contentValue.put(KEY_CUSTOMER_ID, mData.customerId)
        contentValue.put(KEY_CUSTOMER_CODE, mData.customerCode)
        contentValue.put(KEY_STATUS, mData.status)
        contentValue.put(KEY_START_TIME, mData.startTime)
        contentValue.put(KEY_END_TIME, mData.endTime)
        contentValue.put(KEY_LATITUDE, mData.latitude)
        contentValue.put(KEY_LONGITUDE, mData.longitude)
        contentValue.put(KEY_REASON, mData.reason)
        contentValue.put(KEY_CLOSE_COMMENT, mData.comment)
        contentValue.put(KEY_JOURNEY_ID, mData.planId)
        contentValue.put(KEY_OFF_VISITED_ID, mData.visitedOffId)
        contentValue.put(KEY_IS_SEQUENCE, mData.isSequence)
        contentValue.put(KEY_COMPLETED_TASK, mData.completedTask)

        if (mStatus == "close") {
            contentValue.put(DATA_MARK_FOR_POST, "M")
        } else {
            contentValue.put(DATA_MARK_FOR_POST, "N")
        }

        db.insert(TABLE_VISITED_CUSTOMER, null, contentValue)
    }

    //Update Customer Visit
    fun updateCustomerVisit(
        mData: DailyFeildRequestModel.Customer
    ): Int {
        val contentValue = ContentValues()
        contentValue.put(KEY_CUSTOMER_ID, mData.customerId)
        contentValue.put(KEY_IS_DAILY_FEILD_CREATEED, "Y")
        contentValue.put(KEY_IS_DAILY_ACTIVITY_POSTED, "N")
        contentValue.put(KEY_SHELF_DISPLAY, mData.shelfDisplay)
        contentValue.put(KEY_OFF_SHELF_DISPLAY, mData.offShelfDisplay)
        contentValue.put(KEY_OPPERTUNITE, mData.opportunity)
        contentValue.put(KEY_OUT_OFF_STOCK, mData.offShelfDisplay)
        contentValue.put(KEY_REMARK, mData.remarks)
        val db = this.writableDatabase
        val i = db.update(
            TABLE_DAILY_FEILD,
            contentValue,
            "$KEY_CUSTOMER_ID = ?",
            arrayOf<String>(mData.customerId.toString())
        )
        return i
    }

    fun updateCustomerVisit(routeId: String, status: String): Int {
        val contentValue = ContentValues()
        if (status.equals("1")) {
            contentValue.put(KEY_IS_DAILY_FEILD_CREATEED, "Y")
        } else {
            contentValue.put(KEY_IS_DAILY_FEILD_CREATEED, "N")
        }

        val db = this.writableDatabase
        val i = db.update(
            TABLE_DAILY_FEILD,
            contentValue,
            "$KEY_ROUTE_ID = ?",
            arrayOf<String>(routeId)
        )
        return i
    }

