        db.insert(TABLE_DAILY_FEILD, null, contentValue)
    }


    fun getDailyFeild(mId: String, routeId: String): DailyFeildRequestModel.Customer? {
        var data: DailyFeildRequestModel.Customer? = DailyFeildRequestModel.Customer()
        val db = this.readableDatabase
        try {
            var cursor = db.rawQuery(
                ("SELECT * FROM " +
                        TABLE_DAILY_FEILD + " WHERE " +
                        KEY_CUSTOMER_ID + "= ? AND  $KEY_ROUTE_ID =?"),
                arrayOf<String>(mId, routeId)
            )
            Log.e("dailycount", cursor.getCount().toString())

            if (cursor.moveToFirst()) {
                do {
                    data = DailyFeildRequestModel.Customer()

                    data!!.shelfDisplay =
                        cursor.getString(cursor.getColumnIndex(KEY_SHELF_DISPLAY))
                    data!!.offShelfDisplay =
                        cursor.getString(cursor.getColumnIndex(KEY_OFF_SHELF_DISPLAY))
                    data!!.opportunity =
                        cursor.getString(cursor.getColumnIndex(KEY_OPPERTUNITE))
                    data!!.outOfStock =
                        cursor.getString(cursor.getColumnIndex(KEY_OUT_OFF_STOCK))
                    data!!.remarks = cursor.getString(cursor.getColumnIndex(KEY_REMARK))
                    data!!.customerId =
                        cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_ID)).toInt()
                } while (cursor.moveToNext())
            }

        } finally {
            try {
                db.close()
            } catch (ignore: Exception) {
            }
        }
        return data!!
    }

    fun getDailyFeildisCreated(mId: String, routeId: String): String {
        var data: String = ""
        val db = this.readableDatabase
        try {
            var cursor = db.rawQuery(
                ("SELECT * FROM " +
                        TABLE_DAILY_FEILD + " WHERE " +
                        KEY_CUSTOMER_ID + "= ? AND  $KEY_ROUTE_ID =?"),
                arrayOf<String>(mId, routeId)
            )

            if (cursor.moveToFirst()) {
                do {
                    data =
                        cursor.getString(cursor.getColumnIndex(KEY_IS_DAILY_FEILD_CREATEED))
                } while (cursor.moveToNext())
            }

        } finally {
            try {
                db.close()
            } catch (ignore: Exception) {
            }
        }
        return data!!
    }

    fun getDailyFeildisPosted(routeId: String): String {
        var data: String = ""
        val db = this.readableDatabase
        try {
            var cursor = db.rawQuery(
                ("SELECT * FROM " +
                        TABLE_DAILY_FEILD + " WHERE " +
                        "$KEY_ROUTE_ID =?"), arrayOf<String>(routeId)
            )

            if (cursor.moveToFirst()) {
                do {
                    data = cursor.getString(
                        cursor.getColumnIndex(
                            KEY_IS_DAILY_ACTIVITY_POSTED
                        )
                    )

                } while (cursor.moveToNext())
            }

        } finally {
            try {
                db.close()
            } catch (ignore: Exception) {
            }
        }
        return data!!
    }

    fun getCustomerShopStatus(mId: String): String {
        var firstname: String = ""

        val db = this.readableDatabase
        try {
            var cursor = db.rawQuery(
                ("SELECT * FROM " +
                        TABLE_CUSTOMER + " WHERE " +
                        KEY_CUSTOMER_ID + "=?"), arrayOf<String>(mId)
            )
            cursor.moveToFirst()
            val count = cursor.getCount()// KEY_FIRST_NAME + " TEXT," + KEY_LAST_NAME
            if (count > 0) {
                firstname = cursor.getString(cursor.getColumnIndex(KEY_SHOP_STATUS))
            }

            cursor.close()
        } catch (e: Exception) {
            e.printStackTrace()
        }

        return firstname
    }

