    //INSERT Load HEADER ONLY SINGLE
    fun insertLoad(mData: DataDetail) {
        val db = this.writableDatabase

        db.beginTransaction()

        var mLoadList = mData.loadList

        try {
            for (mLoad in mLoadList!!) {
                if (!checkLoadExist(mLoad.loadNumber!!)) {
                    val contentValue = ContentValues()
                    contentValue.put(KEY_LOAD_ID, mLoad.id)
                    contentValue.put(KEY_LOAD_NO, mLoad.loadNumber!!)
                    contentValue.put(KEY_LOAD_DATE, mLoad.loadDate)
                    contentValue.put(KEY_LOAD_STATUS, "0")
                    contentValue.put(DATA_MARK_FOR_POST, "N")

                    if (mLoad.loadType == "1") {
                        contentValue.put(KEY_LOAD_TYPE, "Delivery Load")
                    } else {
                        contentValue.put(KEY_LOAD_TYPE, "Van Load")
                    }

                    db.insert(TABLE_LOAD_HEADER, null, contentValue)


                    for (mDetail in mLoad.salesmanLoadDetails!!) {
                        val contentValueItem = ContentValues()
                        contentValueItem.put(KEY_LOAD_NO, mLoad.loadNumber!!)
                        contentValueItem.put(KEY_ITEM_ID, mDetail.itemId)
                        contentValueItem.put(KEY_ITEM_NAME, getItemName(mDetail.itemId))

                        val mLowerId = getItemLowerUnit(mDetail.itemId)

                        if (mLowerId != mDetail.itemUom) {
                            contentValueItem.put(KEY_UOM_ID, mLowerId)
                            contentValueItem.put(
                                KEY_UOM_NAME,
                                getUOMName(mLowerId)
                            )
                            contentValueItem.put(KEY_DISPLAY_UNIT, mDetail.itemUom)
                            contentValueItem.put(
                                KEY_DISPLAY_UNIT_NAME,
                                getUOMName(mDetail.itemUom)
                            )
                        } else {
                            contentValueItem.put(KEY_UOM_ID, mDetail.itemUom)
                            contentValueItem.put(
                                KEY_UOM_NAME,
                                getUOMName(mDetail.itemUom)
                            )
                            contentValueItem.put(KEY_DISPLAY_UNIT, mDetail.itemUom)
                            contentValueItem.put(
                                KEY_DISPLAY_UNIT_NAME,
                                getUOMName(mDetail.itemUom)
                            )
                        }

                        contentValueItem.put(KEY_BATCH, "")
                        contentValueItem.put(KEY_QTY, mDetail.loadQty)
                        contentValueItem.put(KEY_PRIMARY_QTY, mDetail.primary_qty)
                        if (mDetail.requestedQty != null) {
                            contentValueItem.put(KEY_REQ_QTY, mDetail.requestedQty)
                        } else {
                            contentValueItem.put(KEY_REQ_QTY, "0")
                        }

                        if (mDetail.requestedUOMId != null) {
                            contentValueItem.put(
                                KEY_REQ_UOM_NAME,
                                getUOMName(mDetail.requestedUOMId)
                            )
                        } else {
                            contentValueItem.put(KEY_REQ_UOM_NAME, getUOMName(mDetail.itemUom))
                        }

                        if (mDetail.warehouseApproveQty != null) {
                            contentValueItem.put(KEY_WH_QTY, mDetail.warehouseApproveQty)
                        } else {
                            contentValueItem.put(KEY_WH_QTY, "0")
                        }

                        if (mDetail.superviserApproveQty != null) {
                            contentValueItem.put(KEY_SP_QTY, mDetail.superviserApproveQty)
                        } else {
                            contentValueItem.put(KEY_SP_QTY, "0")
                        }
                        if (mDetail.varianceQty != null) {
                            contentValueItem.put(KEY_VARIANCE_QTY, mDetail.varianceQty)
                        } else {
                            contentValueItem.put(KEY_VARIANCE_QTY, "0")
                        }

                        val resultItem = db.insertWithOnConflict(
                            TABLE_LOAD_ITEM,
                            null,
                            contentValueItem,
                            SQLiteDatabase.CONFLICT_REPLACE
                        )
                        if (resultItem == -1L) {
                            Log.e("DB_ERROR", "Insert failed for Load Item: ${mDetail.itemId}")
                        }
                    }
                }
            }

            db.setTransactionSuccessful();
        } finally {
            db.endTransaction();
        }
    }

