    fun insertVarianceUnload(
        mUnloadNo: String,
        mUnloadType: String,
        mMUType: String,
        mTripId: String?,
        mItemList: List<SalesmanLoadDetail>
    ) {

        val db = this.writableDatabase

        if (!checkUnloadExist(mUnloadNo)) {
            val contentValue = ContentValues()
            contentValue.put(KEY_UNIQUE_ID, mUnloadNo)
            contentValue.put(KEY_UNLOAD_TYPE, mUnloadType)
            contentValue.put(KEY_UNLOAD_DATE, Utils.getCurrentDate())
            contentValue.put(KEY_TRIP_ID, mTripId!!)
            contentValue.put(DATA_MARK_FOR_POST, "N")

            db.insert(TABLE_UNLOAD_HEADER, null, contentValue)
        }

        for (mItem in mItemList) {

            if (mItem.actualQty.isNotEmpty()) {
                if (mItem.actualQty.toDouble() > 0) {
                    val contentValue = ContentValues()
                    contentValue.put(KEY_UNLOAD_TYPE, mMUType)
                    contentValue.put(KEY_ITEM_ID, mItem.itemId)
                    contentValue.put(KEY_ITEM_CODE, mItem.itemCode)
                    contentValue.put(KEY_UOM_ID, mItem.itemUom)
                    contentValue.put(KEY_UNLOAD_QTY, mItem.actualQty)
                    contentValue.put(KEY_BATCH, "")
                    contentValue.put(KEY_REASON, "")
                    contentValue.put(KEY_UNIQUE_ID, mUnloadNo)
                    contentValue.put(KEY_IS_RE_ITEM, "0")

                    db.insert(TABLE_UNLOAD_ITEM, null, contentValue)

                    //RIDDHI

                    for (mLoadBatch in mItem.batchdetailsList!!) {
                        val contentValueItemBactch = ContentValues()
                        contentValueItemBactch.put(KEY_ITEM_ID, mItem.itemId.toString())
                        contentValueItemBactch.put(
                            KEY_BATCH_ID,
                            mLoadBatch.batchId.toString()
                        )
                        contentValueItemBactch.put(
                            KEY_BATCH_NO,
                            mLoadBatch.batchNumber
                        )
                        contentValueItemBactch.put(KEY_BATCH_EXPIRY, mLoadBatch.expiryDate)

                        if (mLoadBatch.qty != null) {
                            contentValueItemBactch.put(KEY_BATCH_QTY, mLoadBatch.qty)
                        } else {
                            contentValueItemBactch.put(KEY_BATCH_QTY, "0")
                        }
                        db.insert(TABLE_UNLOAD_ITEM_BATCH, null, contentValueItemBactch)

                    }
                }
            }

        }

    }


    fun insertCarryUnload(
        mUnloadNo: String,
        mUnloadType: String,
        mMUType: String,
        mTripId: String?,
        mItemList: List<SalesmanLoadDetail>
    ) {

        val db = this.writableDatabase

        if (!checkUnloadExist(mUnloadNo)) {
            val contentValue = ContentValues()
            contentValue.put(KEY_UNIQUE_ID, mUnloadNo)
            contentValue.put(KEY_UNLOAD_TYPE, mUnloadType)
            contentValue.put(KEY_UNLOAD_DATE, Utils.getCurrentDate())
            contentValue.put(KEY_TRIP_ID, mTripId!!)
            contentValue.put(DATA_MARK_FOR_POST, "N")

            db.insert(TABLE_UNLOAD_HEADER, null, contentValue)
        }

        for (mItem in mItemList) {

            if (mItem.actualQty.isNotEmpty()) {
                if (mItem.actualQty.toDouble() > 0) {
                    val contentValue = ContentValues()
                    contentValue.put(KEY_ITEM_ID, mItem.itemId)
                    contentValue.put(KEY_UNIQUE_ID, mUnloadNo)
                    contentValue.put(KEY_UNLOAD_TYPE, "1")
                    contentValue.put(KEY_ITEM_CODE, mItem.itemCode)
                    contentValue.put(KEY_UOM_ID, mItem.itemUom)
                    contentValue.put(KEY_UNLOAD_QTY, mItem.actualQty)
                    contentValue.put(KEY_BATCH, "")
                    contentValue.put(KEY_REASON, "")
                    contentValue.put(KEY_IS_RE_ITEM, "0")

                    db.insert(TABLE_UNLOAD_ITEM, null, contentValue)
                }
            }

            if (mItem.enterQty.isNotEmpty()) {
                if (mItem.enterQty.toDouble() > 0) {
                    val contentValue = ContentValues()
                    contentValue.put(KEY_UNLOAD_TYPE, "4")
                    contentValue.put(KEY_ITEM_ID, mItem.itemId)
                    contentValue.put(KEY_ITEM_CODE, mItem.itemCode)
                    contentValue.put(KEY_UOM_ID, mItem.itemUom)
                    contentValue.put(KEY_UNLOAD_QTY, mItem.enterQty)
                    contentValue.put(KEY_BATCH, "")
                    contentValue.put(KEY_REASON, "")
                    contentValue.put(KEY_UNIQUE_ID, mUnloadNo)
                    contentValue.put(KEY_IS_RE_ITEM, "0")

                    db.insert(TABLE_UNLOAD_ITEM, null, contentValue)

                    for (mLoadBatch in mItem.batchdetailsList!!) {
                        val contentValueItemBactch = ContentValues()
                        contentValueItemBactch.put(KEY_ITEM_ID, mItem.itemId.toString())
                        contentValueItemBactch.put(
                            KEY_BATCH_ID,
                            mLoadBatch.batchId.toString()
                        )
                        contentValueItemBactch.put(
                            KEY_BATCH_NO,
                            mLoadBatch.batchNumber
                        )
                        contentValueItemBactch.put(KEY_BATCH_EXPIRY, mLoadBatch.expiryDate)

                        if (mLoadBatch.qty != null) {
                            contentValueItemBactch.put(KEY_BATCH_QTY, mLoadBatch.qty)
                        } else {
                            contentValueItemBactch.put(KEY_BATCH_QTY, "0")
                        }
                        db.insert(TABLE_UNLOAD_ITEM_BATCH, null, contentValueItemBactch)

                    }
                }
            }

        }

    }

