    //GET Post UnLoad Request Count
    fun getPostUnLoadRequestCount(): Int {
        var invCount = 0
        val db = this.readableDatabase
        try {
            val cursor = db.rawQuery(
                ("SELECT * FROM " +
                        TABLE_UNLOAD_HEADER + " WHERE " +
                        DATA_MARK_FOR_POST + "=? AND " + KEY_UNLOAD_TYPE + "=?"),
                arrayOf<String>("M", "1")
            )
            cursor.moveToFirst()
            invCount = cursor.count
            cursor.close()
        } catch (e: Exception) {
            e.printStackTrace()
        }
        return invCount
    }

