    //Update Unlaod Order
    fun updateComplaintTransaction(complainNo: String?, type: String, message: String): Int {
        val db = this.writableDatabase
        val contentValue = ContentValues()
        if (type.equals("2", ignoreCase = true)) {
            contentValue.put(TR_IS_POSTED, "Fail")
            contentValue.put(TR_MESSAGE, message)
        } else {
            contentValue.put(TR_IS_POSTED, "Yes")
        }
        val i = db.update(
            TABLE_TRANSACTION, contentValue,
            "$TR_ORDER_ID = ?", arrayOf<String>(complainNo!!)
        )
        return i
    }

    //Update Unlaod Order
    fun updateUnloadTransaction(collectionNo: String?, type: String, message: String): Int {
