            TABLE_TRANSACTION, contentValue,
            "$TR_ORDER_ID = ?", arrayOf<String>(collectionNo!!)
        )
        return i
    }

    fun insertInvoice(
        mOrder: Invoice, mItemList: List<ItemData.Data>, mLPO: String
    ) {

        val db = this.writableDatabase

        val contentValue = ContentValues()
        contentValue.put(KEY_ORDER_TYPE, mOrder.orderType)
        contentValue.put(KEY_INVOICE_NO, mOrder.invoiceNo)
        contentValue.put(KEY_INVOICE_TYPE, mOrder.invoiceType)
        contentValue.put(KEY_INVOICE_DATE, mOrder.invoiceDate)
        contentValue.put(KEY_DELIVERY_ID, mOrder.deliveryId)
        contentValue.put(KEY_ORDER_ID, mOrder.orderId)
        contentValue.put(KEY_DUE_DATE, mOrder.dueDate)
        contentValue.put(KEY_CUSTOMER_CODE, mOrder.customerId)
        contentValue.put(KEY_LATITUDE, mOrder.latitude)
        contentValue.put(KEY_LONGITUDE, mOrder.longitude)
        contentValue.put(KEY_TASK_TIME, mOrder.punchTime)

        var totalGrossAmount = 0F
        var totalGrossDiscount = 0F
        var totalExciseAmount = 0F
        var totalDiscount = 0F
        var totalNet = 0F
        var totalVat1 = 0F
        var totalAmount = 0F

        if (mItemList.size > 0) {
            for (mItemData in mItemList) {

                for (mUOM in mItemData.itemSelectUOM) {

                    val contentValueUOM = ContentValues()
                    contentValueUOM.put(KEY_CUSTOMER_CODE, mOrder.customerId)
                    contentValueUOM.put(KEY_INVOICE_NO, mOrder.invoiceNo)
                    contentValueUOM.put(KEY_ITEM_ID, mUOM.itemId)
                    contentValueUOM.put(KEY_DELV_ITEM_ID, mItemData.itemShellife)
                    contentValueUOM.put(KEY_ITEM_CODE, mUOM.itemCode)
                    contentValueUOM.put(KEY_UOM_ID, mUOM.uomId)
                    contentValueUOM.put(KEY_UOM_NAME, mUOM.uomType)
                    contentValueUOM.put(KEY_QTY, mUOM.uomQty)
                    var mLowerQty = mUOM.uomQty.toDouble() * mUOM.uomUPC.toDouble()
                    contentValueUOM.put(KEY_LOWER_QTY, mLowerQty)

                    contentValueUOM.put(KEY_GROSS, mUOM.grossPrice)
                    contentValueUOM.put(KEY_DISCOUNT, mUOM.discountAmt)

                    contentValueUOM.put(KEY_NET, mUOM.netAmt)
                    contentValueUOM.put(KEY_VAT, mUOM.vatAmt)
                    contentValueUOM.put(KEY_EXCISE, mUOM.item_excise)
                    contentValueUOM.put(KEY_TOTAL, mUOM.totalAmt)
                    if (mOrder.isCouponSale == "1") {
                        contentValueUOM.put(KEY_PROMOTION_ID, "")
                        contentValueUOM.put(KEY_DISCOUNT_ID, "")
                    } else {
                        contentValueUOM.put(KEY_PROMOTION_ID, mUOM.promotion_Id)
                        contentValueUOM.put(KEY_DISCOUNT_ID, mUOM.discount_Id)
                    }

                    contentValueUOM.put(KEY_UOM_PRICE, mUOM.uomPrice)
                    contentValueUOM.put(KEY_FROM_SERIAL, "")
                    contentValueUOM.put(KEY_TO_SERIAL, "")


                    // contentValueUOM.put(KEY_BATCH_NO, mUOM.batchs[0].batchNumber)
                    if (mUOM.discountPer != null) {
                        if (mUOM.discountPer == "100%") {
                            contentValueUOM.put(KEY_IS_FREE, "1")
                        } else {
                            if (mUOM.totalAmt.toFloat() > 0) {
                                contentValueUOM.put(KEY_IS_FREE, "0")
                            } else {
                                contentValueUOM.put(KEY_IS_FREE, "1")
                            }
                        }
                    } else {
                        if (mUOM.totalAmt.toFloat() > 0) {
                            contentValueUOM.put(KEY_IS_FREE, "0")
                        } else {
                            contentValueUOM.put(KEY_IS_FREE, "1")
                        }

                    }

                    if (mItemData.itemWeight == "1") {
                        contentValueUOM.put(KEY_IS_RE_ITEM, "1")
                    } else {
                        contentValueUOM.put(KEY_IS_RE_ITEM, "0")
                    }

                    if (mUOM.uomQty.toDouble() > 0) {
                        db.insert(TABLE_INVOICE_ITEM, null, contentValueUOM)
                    }

                    if (mUOM.batchs.size > 1) {
                        for (mBatch in mUOM.batchs) {
                            val contentValueUOM = ContentValues()
                            contentValueUOM.put(KEY_CUSTOMER_CODE, mOrder.customerId)
                            contentValueUOM.put(KEY_INVOICE_NO, mOrder.invoiceNo)
                            contentValueUOM.put(KEY_ITEM_ID, mUOM.itemId)
                            contentValueUOM.put(KEY_DELV_ITEM_ID, mItemData.itemShellife)
                            contentValueUOM.put(KEY_ITEM_CODE, mUOM.itemCode)

                            var mLowerId = getItemLowerUnit(mUOM.itemId)
                            var mUOMName = getUOMName(mLowerId)

                            contentValueUOM.put(KEY_UOM_ID, mLowerId)
                            contentValueUOM.put(KEY_UOM_NAME, mUOMName)
                            contentValueUOM.put(KEY_QTY, mBatch.qty)
                            var mLowerQty = mBatch.qty.toDouble()
                            contentValueUOM.put(KEY_LOWER_QTY, mLowerQty)
                            contentValueUOM.put(KEY_PROMOTION_ID, mUOM.promotion_Id)
                            contentValueUOM.put(KEY_UOM_PRICE, mBatch.price)
                            contentValueUOM.put(KEY_BATCH_NO, mBatch.batchNumber)

                            var mUOMPrice = mBatch.price.toDouble()
                            var mGross = mBatch.qty.toDouble() * mUOMPrice
                            var mVat = Utils.getVatAmt(mGross, 5.0)
                            var mTotal = mGross + mVat

                            contentValueUOM.put(KEY_GROSS, mGross.toString())
                            contentValueUOM.put(KEY_DISCOUNT, mUOM.discountAmt)
                            contentValueUOM.put(KEY_DISCOUNT_ID, mUOM.discount_Id)

                            contentValueUOM.put(KEY_NET, mGross.toString())
                            contentValueUOM.put(KEY_VAT, mVat.toString())
                            contentValueUOM.put(KEY_EXCISE, mUOM.item_excise)
                            contentValueUOM.put(KEY_TOTAL, mTotal.toString())

                            if (mUOM.discountPer != null) {
                                if (mUOM.discountPer == "100%") {
                                    contentValueUOM.put(KEY_IS_FREE, "1")
                                } else {
                                    if (mTotal.toFloat() > 0) {
                                        contentValueUOM.put(KEY_IS_FREE, "0")
                                    } else {
                                        contentValueUOM.put(KEY_IS_FREE, "1")
                                    }
                                }
                            } else {
                                if (mTotal > 0) {
                                    contentValueUOM.put(KEY_IS_FREE, "0")
                                } else {
                                    contentValueUOM.put(KEY_IS_FREE, "1")
                                }
                            }

                            if (mItemData.itemWeight == "1") {
                                contentValueUOM.put(KEY_IS_RE_ITEM, "1")
                            } else {
                                contentValueUOM.put(KEY_IS_RE_ITEM, "0")
                            }

                            if (mUOM.uomQty.toDouble() > 0) {
                                db.insert(TABLE_INVOICE_BATCH_ITEM, null, contentValueUOM)
                            }
                        }
                    } else {
                        val contentValueUOM = ContentValues()
                        contentValueUOM.put(KEY_CUSTOMER_CODE, mOrder.customerId)
                        contentValueUOM.put(KEY_INVOICE_NO, mOrder.invoiceNo)
                        contentValueUOM.put(KEY_ITEM_ID, mUOM.itemId)
                        contentValueUOM.put(KEY_DELV_ITEM_ID, mItemData.itemShellife)
                        contentValueUOM.put(KEY_ITEM_CODE, mUOM.itemCode)
                        contentValueUOM.put(KEY_UOM_ID, mUOM.uomId)
                        contentValueUOM.put(KEY_UOM_NAME, mUOM.uomType)
                        contentValueUOM.put(KEY_QTY, mUOM.uomQty)
                        var mLowerQty = mUOM.uomQty.toDouble() * mUOM.uomUPC.toDouble()
                        contentValueUOM.put(KEY_LOWER_QTY, mLowerQty)

                        var mUOMPrice = mUOM.uomPrice.toDouble()
                        var mGross = Utils.twoDigit((mUOM.uomQty.toDouble() * mUOMPrice).toFloat())
                        var mNetAm = 0f
                        var mVat = 0f
                        var mTotal = 0f
                        if (mUOM.totalAmt.toDouble() > 0.0) {
                            mNetAm =
                                Utils.twoDigit((mGross - mUOM.discountAmt.toDouble()).toFloat())
                            mVat = Utils.twoDigit(Utils.getVatAmt(mNetAm.toDouble(), 5.0).toFloat())
                            mTotal = mNetAm + mVat
                        } else {
                            mUOMPrice = 0.0
                            mGross = 0f
                            mNetAm = 0f
                            mVat = 0f
                            mTotal = mNetAm + mVat
                        }

                        contentValueUOM.put(KEY_GROSS, mGross)
                        contentValueUOM.put(KEY_DISCOUNT, mUOM.discountAmt)
                        contentValueUOM.put(KEY_DISCOUNT_ID, mUOM.discount_Id)
                        contentValueUOM.put(KEY_NET, mNetAm)
                        contentValueUOM.put(KEY_VAT, mVat)
                        contentValueUOM.put(KEY_EXCISE, mUOM.item_excise)
                        contentValueUOM.put(KEY_TOTAL, mTotal)
                        contentValueUOM.put(KEY_PROMOTION_ID, mUOM.promotion_Id)
                        contentValueUOM.put(KEY_UOM_PRICE, mUOM.uomPrice)
                        //  contentValueUOM.put(KEY_BATCH_NO, mUOM.batchs[0].batchNumber)
                        if (mUOM.discountPer != null) {
                            if (mUOM.discountPer == "100%") {
                                contentValueUOM.put(KEY_IS_FREE, "1")
                            } else {
                                if (mUOM.totalAmt.toDouble() > 0) {
                                    contentValueUOM.put(KEY_IS_FREE, "0")
                                } else {
                                    contentValueUOM.put(KEY_IS_FREE, "1")
                                }
                            }
                        } else {
                            if (mUOM.totalAmt.toDouble() > 0) {
                                contentValueUOM.put(KEY_IS_FREE, "0")
                            } else {
                                contentValueUOM.put(KEY_IS_FREE, "1")
                            }
                        }

                        if (mItemData.itemWeight == "1") {
                            contentValueUOM.put(KEY_IS_RE_ITEM, "1")
                        } else {
                            contentValueUOM.put(KEY_IS_RE_ITEM, "0")
                        }

                        if (mUOM.uomQty.toDouble() > 0) {
                            db.insert(TABLE_INVOICE_BATCH_ITEM, null, contentValueUOM)
                        }

                        totalGrossAmount =
                            Utils.twoDigit(totalGrossAmount.plus(Utils.twoDigit(mGross)))
                        totalDiscount =
                            Utils.twoDigit(totalDiscount.plus(Utils.twoDigit(mUOM.discountAmt.toFloat())))
                        totalVat1 =
                            Utils.twoDigit(totalVat1.plus(Utils.twoDigit(mVat)))
                        totalNet =
                            Utils.twoDigit(totalNet.plus(Utils.twoDigit(mNetAm)))
                        totalAmount =
                            Utils.twoDigit(totalAmount.plus(Utils.twoDigit(mTotal)))
                        totalExciseAmount =
                            Utils.twoDigit(totalExciseAmount.plus(Utils.twoDigit(mUOM.item_excise.toFloat())))

                    }

                }
            }
        } else {
            totalGrossAmount =
                Utils.twoDigit(totalGrossAmount.plus(Utils.twoDigit(mOrder.gross!!.toFloat())))
            totalDiscount =
                Utils.twoDigit(totalDiscount.plus(Utils.twoDigit(mOrder.discount!!.toFloat())))
            totalNet =
                Utils.twoDigit(totalNet.plus(Utils.twoDigit(mOrder.net!!.toFloat())))
            totalVat1 =
                Utils.twoDigit(totalVat1.plus(Utils.twoDigit(mOrder.vat!!.toFloat())))

            totalAmount =
                Utils.twoDigit(totalAmount.plus(Utils.twoDigit(mOrder.total!!.toFloat())))
        }



        if (mOrder.mRewards!!.toDouble() > 0) {
            contentValue.put(KEY_GROSS, "" + totalGrossAmount)
            contentValue.put(KEY_DISCOUNT, "" + totalDiscount)

            totalNet = Utils.twoDigit((totalNet - mOrder.mRewards!!.toFloat()))
            var mNTotal = Utils.twoDigit((totalNet))
            var vatAmt =
                Utils.twoDigit(Utils.getVatAmt(mNTotal.toDouble(), 5.0).toFloat())

            var totalAmt = Utils.twoDigit((mNTotal + vatAmt))

            contentValue.put(KEY_NET, "" + mNTotal)
            contentValue.put(KEY_VAT, "" + vatAmt)
            contentValue.put(KEY_EXCISE, "" + totalExciseAmount)
            contentValue.put(KEY_DELIVERY_CHARGE, "" + mOrder.mDelvieryCharge)
            contentValue.put(KEY_POINTS_AMOUNT, "" + mOrder.mRewards)
            var mCharge = Utils.twoDigit(mOrder.mDelvieryCharge!!.toFloat())
            var mFinalAmount = mCharge + totalAmt
            contentValue.put(KEY_ORDER_AMOUNT, "" + mFinalAmount)
            contentValue.put(KEY_ROUNDTO, "" + mFinalAmount)
            contentValue.put(KEY_PAID_AMOUNT, "" + mFinalAmount)

        } else {
            contentValue.put(KEY_GROSS, "" + totalGrossAmount)
            contentValue.put(KEY_DISCOUNT, "" + totalDiscount)
            contentValue.put(KEY_NET, "" + totalNet)
            contentValue.put(KEY_VAT, "" + totalVat1)
            contentValue.put(KEY_EXCISE, "" + totalExciseAmount)
            contentValue.put(KEY_DELIVERY_CHARGE, "" + mOrder.mDelvieryCharge)
            contentValue.put(KEY_POINTS_AMOUNT, "" + mOrder.mRewards)
            var mCharge = Utils.twoDigit(mOrder.mDelvieryCharge!!.toFloat())
            var mFinalAmount = mCharge + totalAmount
            contentValue.put(KEY_ORDER_AMOUNT, "" + mFinalAmount)
            contentValue.put(KEY_ROUNDTO, "" + mFinalAmount)
            contentValue.put(KEY_PAID_AMOUNT, "" + mFinalAmount)
        }
        contentValue.put(KEY_PAYMENT_TERM_ID, mOrder.payemntId)
        contentValue.put(KEY_COMMENT, mOrder.comment)
        contentValue.put(LOB_ID, mOrder.lobId)
        contentValue.put(KEY_LPONO, mLPO)
        contentValue.put(KEY_IS_EXCHANGE, mOrder.isExchange)
        contentValue.put(KEY_EXCHANGE_NO, mOrder.exchangeNo)
        contentValue.put(KEY_IS_DELETED, "0")
        contentValue.put(KEY_IS_TOPUP, mOrder.isTopup)
        contentValue.put(KEY_IS_COUPON, mOrder.isCoupon)
        contentValue.put(KEY_IS_COUPON_SALES, mOrder.isCouponSale)
        contentValue.put(KEY_P_TYPE, "")
        contentValue.put(KEY_COUPON_ID, mOrder.couponId)


        if (mOrder.isAccept != null) {
            if (mOrder.isAccept == "1") {
                contentValue.put(KEY_IS_ACCEPT, mOrder.isAccept)
                contentValue.put(KEY_STAMP, mOrder.isStamp)
                contentValue.put(KEY_INVOICE_CANCEL, mOrder.isInvoiceCancel)
                contentValue.put(DATA_MARK_FOR_POST, "N")
            } else {
                contentValue.put(KEY_IS_ACCEPT, "0")
                contentValue.put(KEY_STAMP, mOrder.isStamp)
                contentValue.put(KEY_INVOICE_CANCEL, mOrder.isInvoiceCancel)
                contentValue.put(DATA_MARK_FOR_POST, "N")
            }
        } else {
            contentValue.put(KEY_IS_ACCEPT, "0")
            contentValue.put(KEY_STAMP, mOrder.isStamp)
            contentValue.put(KEY_INVOICE_CANCEL, mOrder.isInvoiceCancel)
            contentValue.put(DATA_MARK_FOR_POST, "N")
        }

        db.insert(TABLE_INVOICE_HEADER, null, contentValue)
    }

    fun insertSalesInvoice(
        mOrder: Invoice, mItemList: List<ItemData.Data>, mLPO: String,
        mBatchItemList: ArrayList<BatchdetailsList>?
    ) {

        val db = this.writableDatabase

        val contentValue = ContentValues()
        contentValue.put(KEY_ORDER_TYPE, mOrder.orderType)
        contentValue.put(KEY_INVOICE_NO, mOrder.invoiceNo)
        contentValue.put(KEY_INVOICE_TYPE, mOrder.invoiceType)
        contentValue.put(KEY_INVOICE_DATE, mOrder.invoiceDate)
        contentValue.put(KEY_DELIVERY_ID, mOrder.deliveryId)
        contentValue.put(KEY_ORDER_ID, mOrder.orderId)
        contentValue.put(KEY_DUE_DATE, mOrder.dueDate)
        contentValue.put(KEY_CUSTOMER_CODE, mOrder.customerId)
        contentValue.put(KEY_GROSS, mOrder.gross)
        contentValue.put(KEY_DISCOUNT, mOrder.discount)
        contentValue.put(KEY_NET, mOrder.net)
        contentValue.put(KEY_VAT, mOrder.vat)
        contentValue.put(KEY_EXCISE, mOrder.excAmt)
        contentValue.put(KEY_ORDER_AMOUNT, mOrder.total)
        contentValue.put(KEY_PAYMENT_TERM_ID, mOrder.payemntId)
        contentValue.put(KEY_COMMENT, mOrder.comment)
        contentValue.put(LOB_ID, mOrder.lobId)
        contentValue.put(KEY_LPONO, mLPO)
        contentValue.put(KEY_IS_EXCHANGE, mOrder.isExchange)
        contentValue.put(KEY_EXCHANGE_NO, mOrder.exchangeNo)
        contentValue.put(KEY_ROUNDTO, mOrder.roundTo)
        contentValue.put(KEY_PAID_AMOUNT, mOrder.paidAmount)

        if (mOrder.isAccept != null) {

            if (mOrder.isAccept == "1") {
                contentValue.put(KEY_IS_ACCEPT, mOrder.isAccept)
                contentValue.put(DATA_MARK_FOR_POST, "N")
            } else {
                contentValue.put(KEY_IS_ACCEPT, "0")
                contentValue.put(DATA_MARK_FOR_POST, "M")
            }
        } else {
            contentValue.put(KEY_IS_ACCEPT, "0")
            contentValue.put(DATA_MARK_FOR_POST, "M")
        }

        db.insert(TABLE_INVOICE_HEADER, null, contentValue)

        for (mItemData in mItemList) {
            for (mUOM in mItemData.itemSelectUOM) {
                //Item
                val contentValueUOM = ContentValues()
                contentValueUOM.put(KEY_CUSTOMER_CODE, mOrder.customerId)
                contentValueUOM.put(KEY_INVOICE_NO, mOrder.invoiceNo)
                contentValueUOM.put(KEY_ITEM_ID, mUOM.itemId)
                contentValueUOM.put(KEY_ITEM_CODE, mUOM.itemCode)
                contentValueUOM.put(KEY_UOM_ID, mUOM.uomId)
                contentValueUOM.put(KEY_UOM_NAME, mUOM.uomType)
                contentValueUOM.put(KEY_QTY, mUOM.uomQty)
                var mLowerQty = mUOM.uomQty.toDouble() * mUOM.uomUPC.toDouble()
                contentValueUOM.put(KEY_LOWER_QTY, mLowerQty)
                contentValueUOM.put(KEY_GROSS, mUOM.grossPrice)
                contentValueUOM.put(KEY_DISCOUNT, mUOM.discountAmt)
                contentValueUOM.put(KEY_DISCOUNT_ID, mUOM.discount_Id)
                contentValueUOM.put(KEY_NET, mUOM.netAmt)
                contentValueUOM.put(KEY_VAT, mUOM.vatAmt)
                contentValueUOM.put(KEY_EXCISE, mUOM.item_excise)
                contentValueUOM.put(KEY_TOTAL, mUOM.totalAmt)
                contentValueUOM.put(KEY_PROMOTION_ID, mUOM.promotion_Id)
                contentValueUOM.put(KEY_UOM_PRICE, mUOM.uomPrice)
                if (mUOM.discountPer != null) {
                    if (mUOM.discountPer == "100%") {
                        contentValueUOM.put(KEY_IS_FREE, "1")
                    } else {
                        contentValueUOM.put(KEY_IS_FREE, "0")
                    }
                } else {
                    contentValueUOM.put(KEY_IS_FREE, "0")
                }

                if (mItemData.itemWeight == "1") {
                    contentValueUOM.put(KEY_IS_RE_ITEM, "1")
                } else {
                    contentValueUOM.put(KEY_IS_RE_ITEM, "0")
                }

                if (mUOM.uomQty.toDouble() > 0) {
                    db.insert(TABLE_INVOICE_ITEM, null, contentValueUOM)
                }


                //Batch
                for (mLoadBatch in mBatchItemList!!) {
                    val contentValueItemBactch = ContentValues()
                    contentValueItemBactch.put(KEY_ITEM_ID, mUOM.itemId)
                    contentValueItemBactch.put(KEY_BATCH_ID, mLoadBatch.batchId.toString())
                    contentValueItemBactch.put(KEY_INVOICE_NO, mOrder.invoiceNo)
                    contentValueItemBactch.put(KEY_BATCH_NO, mLoadBatch.batchNumber.toString())
                    contentValueItemBactch.put(KEY_BATCH_EXPIRY, mLoadBatch.expiryDate)

                    if (mLoadBatch.qty != null) {
                        contentValueItemBactch.put(KEY_QTY, mLoadBatch.qty)
                        contentValueItemBactch.put(KEY_BATCH_QTY, mLoadBatch.qty)
                    } else {
                        contentValueItemBactch.put(KEY_BATCH_QTY, "0")
                    }


                    db.insert(TABLE_INVOICE_BATCH_ITEM, null, contentValueItemBactch)

                }

            }
        }
    }


