    fun insertLoadVariance(mOrder: Order, mItemList: List<SalesmanLoadDetail>) {

        val db = this.writableDatabase

        val contentValue = ContentValues()
        contentValue.put(KEY_ORDER_TYPE, mOrder.orderType)
        contentValue.put(KEY_ORDER_NO, mOrder.orderNo)
        contentValue.put(KEY_ORDER_DATE, mOrder.orderDate)
        contentValue.put(KEY_DELVIERY_DATE, mOrder.deliveryDate)
        contentValue.put(KEY_DUE_DATE, mOrder.dueDate)
        contentValue.put(KEY_CUSTOMER_CODE, mOrder.customerId)
        contentValue.put(KEY_GROSS, mOrder.gross)
        contentValue.put(KEY_DISCOUNT, mOrder.discount)
        contentValue.put(KEY_NET, mOrder.net)
        contentValue.put(KEY_VAT, mOrder.vat)
        contentValue.put(KEY_ORDER_AMOUNT, mOrder.total)
        contentValue.put(KEY_PAYMENT_TERM_ID, mOrder.payemntId)
        contentValue.put(KEY_COMMENT, mOrder.comment)
        contentValue.put(KEY_IS_ACCEPT, "0")
        contentValue.put(DATA_MARK_FOR_POST, "M")
        db.insert(TABLE_LOAD_VARIANCE_HEADER, null, contentValue)

        for (mUOM in mItemList) {

            var mUOmDetail = getItemUOMDetail(mUOM.itemId, mUOM.itemUom)

            val contentValueUOM = ContentValues()
            contentValueUOM.put(KEY_ORDER_NO, mOrder.orderNo)
            contentValueUOM.put(KEY_ITEM_ID, mUOM.itemId)
            contentValueUOM.put(KEY_ITEM_CODE, mUOM.itemCode)
            contentValueUOM.put(KEY_UOM_ID, mUOM.itemUom)
            contentValueUOM.put(KEY_UOM_NAME, mUOM.uomName)
            contentValueUOM.put(KEY_QTY, mUOM.actualQty)

            var discountAmt = 0
            var grossPrice = mUOM.actualQty
                .toDouble() * mUOmDetail!!.uomPrice.toDouble()
            var netAmt = grossPrice - discountAmt
            var itemVat =
                getItemVat(mUOM.itemId)
            var vatAmt = Utils.getVatAmt(grossPrice, itemVat.toDouble())
            var totalAmt = netAmt + vatAmt

            contentValueUOM.put(KEY_GROSS, grossPrice.toString())
            contentValueUOM.put(KEY_DISCOUNT, discountAmt.toString())
            contentValueUOM.put(KEY_DISCOUNT_ID, "")
            contentValueUOM.put(KEY_NET, netAmt.toString())
            contentValueUOM.put(KEY_VAT, vatAmt.toString())
            contentValueUOM.put(KEY_TOTAL, totalAmt.toString())
            contentValueUOM.put(KEY_PROMOTION_ID, "")
            contentValueUOM.put(KEY_UOM_PRICE, mUOmDetail!!.uomPrice)
            contentValueUOM.put(KEY_IS_FREE, "0")

            db.insert(TABLE_LOAD_VARIANCE, null, contentValueUOM)

        }
    }


