        if (isAccept == "0") {
            contentValue.put(DATA_MARK_FOR_POST, "M")
        } else {
            contentValue.put(DATA_MARK_FOR_POST, "N")
        }
        db.insert(TABLE_ORDER_HEADER, null, contentValue)

        for (mItemData in mItemList) {

            val mLowerUOM =
                getLowerUOM(
                    mItemData.uomId!!,
                    mItemData.itemId!!
                )

            var mUomprice = 0.0
            if (mLowerUOM!!.uomPrice != null) {
                mUomprice = mLowerUOM!!.uomPrice.toDouble()
            }
            var grossPrice = mItemData.qty!!.toInt() * mUomprice
            var discount = 0.0
            var netA = grossPrice - discount
            var vatA = Utils.getVatAmt(grossPrice, mItemData!!.vatPercent!!.toDouble())
            var totalA = netA + vatA

            val contentValueUOM = ContentValues()
            contentValueUOM.put(KEY_ORDER_NO, mOrder.orderNo)
            contentValueUOM.put(KEY_ITEM_ID, mItemData.itemId)
            contentValueUOM.put(KEY_ITEM_CODE, mItemData.itemCode)
            contentValueUOM.put(KEY_UOM_ID, mItemData.uomId)
            contentValueUOM.put(KEY_UOM_NAME, mLowerUOM.uom.name)
            contentValueUOM.put(KEY_QTY, mItemData.qty)
            contentValueUOM.put(KEY_GROSS, grossPrice)
            contentValueUOM.put(KEY_DISCOUNT, discount)
            contentValueUOM.put(KEY_DISCOUNT_ID, "")
            contentValueUOM.put(KEY_NET, netA)
            contentValueUOM.put(KEY_VAT, vatA)
            contentValueUOM.put(KEY_TOTAL, totalA)
            contentValueUOM.put(KEY_PROMOTION_ID, "")
            contentValueUOM.put(KEY_UOM_PRICE, mUomprice)
            contentValueUOM.put(KEY_IS_FREE, "0")

            db.insert(TABLE_ORDER_ITEM, null, contentValueUOM)

        }
    }

    fun insertOrder(
