    fun isLocusVisitCustomer(mItemId: String): Boolean {
        var isExist = false
        val db = this.readableDatabase

        try {
            val cursor = db.rawQuery(
                "SELECT * FROM $TABLE_VISITED_LOCUS WHERE $KEY_CUSTOMER_ID = '$mItemId'",
                null
            )

            if (cursor.count > 0) {
                isExist = true
            }
            cursor.close()
        } catch (e: Exception) {
            e.printStackTrace()
        }

        return isExist
    }

