    fun insertDelivery(mDelivery: List<DeliveryHeader>) {

        val db = this.writableDatabase

        for (mData in mDelivery) {

            if (!checkDelvieryExist(mData.deliveryNumber)) {

                val contentValue = ContentValues()
                contentValue.put(KEY_UUID, mData.uuID)
                contentValue.put(KEY_DELIVERY_ID, mData.id)
                contentValue.put(KEY_DELIVERY_NO, mData.deliveryNumber)
                contentValue.put(KEY_ORDER_ID, mData.orderId)
                contentValue.put(KEY_DELVIERY_DATE, mData.deliveryDate)
                contentValue.put(KEY_DELVIERY_TIME, mData.deliveryTime)
                contentValue.put(KEY_CUSTOMER_ID, mData.customerId)
                contentValue.put(KEY_GROSS, mData.totalGross)
                contentValue.put(KEY_DISCOUNT, mData.totalDiscountAmount)
                contentValue.put(KEY_NET, mData.totalNet)
                contentValue.put(KEY_VAT, mData.totalVat)
                contentValue.put(KEY_ORDER_AMOUNT, mData.grandTotal)
                contentValue.put(KEY_PAYMENT_TERM_ID, mData.paymentTermId)
                if (mData.delivery_charge != null) {
                    contentValue.put(KEY_DELIVERY_CHARGE, mData.delivery_charge)
                } else {
