    fun insertReturnData(mDelivery: List<CreditHeader>) {

        val db = this.writableDatabase

        for (mData in mDelivery) {

            if (!checkRetrunExist(mData.creditNumber)) {

                val contentValue = ContentValues()
                contentValue.put(KEY_UUID, mData.uuID)
                contentValue.put(KEY_R_ID, mData.id.toString())
                contentValue.put(KEY_ORDER_NO, mData.creditNumber)
                contentValue.put(KEY_ORDER_TYPE, mData.orderType)
                contentValue.put(KEY_INVOICE_ID, mData.invoice_id)
                contentValue.put(KEY_ORDER_DATE, mData.creditDate)
                contentValue.put(
                    KEY_CUSTOMER_CODE,
                    getCustomerCode(mData.customerId.toString())
                )
                contentValue.put(KEY_GROSS, mData.totalGross)
                contentValue.put(KEY_DISCOUNT, mData.totalDiscountAmount)
                contentValue.put(KEY_NET, mData.totalNet)
                contentValue.put(KEY_VAT, mData.totalVat)
                contentValue.put(KEY_ORDER_AMOUNT, mData.grandTotal)
