    fun insertLoadRequestOrder(mOrder: Order, mItemList: List<ItemData.Data>) {

        val db = this.writableDatabase

        val contentValue = ContentValues()
        contentValue.put(KEY_ORDER_TYPE, mOrder.orderType)
        contentValue.put(KEY_ORDER_NO, mOrder.orderNo)
        contentValue.put(KEY_ORDER_DATE, mOrder.orderDate)
        contentValue.put(KEY_DELVIERY_DATE, mOrder.deliveryDate)
        contentValue.put(KEY_DUE_DATE, mOrder.dueDate)
        contentValue.put(KEY_CUSTOMER_CODE, mOrder.customerId)
        contentValue.put(KEY_GROSS, mOrder.gross)
        contentValue.put(KEY_DISCOUNT, mOrder.discount)
        contentValue.put(KEY_NET, mOrder.net)
        contentValue.put(KEY_VAT, mOrder.vat)
        contentValue.put(KEY_ORDER_AMOUNT, mOrder.total)
        contentValue.put(KEY_PAYMENT_TERM_ID, mOrder.payemntId)
        contentValue.put(KEY_COMMENT, mOrder.comment)
        contentValue.put(DATA_MARK_FOR_POST, "M")

        db.insert(TABLE_LOAD_REQUEST_HEADER, null, contentValue)


        for (mItemData in mItemList) {

            for (mUOM in mItemData.itemSelectUOM) {

                val contentValueUOM = ContentValues()
                contentValueUOM.put(KEY_ORDER_NO, mOrder.orderNo)
                contentValueUOM.put(KEY_ITEM_ID, mUOM.itemId)
                contentValueUOM.put(KEY_ITEM_CODE, mUOM.itemCode)
                contentValueUOM.put(KEY_UOM_ID, mUOM.uomId)
                contentValueUOM.put(KEY_UOM_NAME, mUOM.uomType)
                contentValueUOM.put(KEY_QTY, mUOM.uomQty)
                contentValueUOM.put(KEY_GROSS, mUOM.grossPrice)
                contentValueUOM.put(KEY_DISCOUNT, mUOM.discountAmt)
                contentValueUOM.put(KEY_DISCOUNT_ID, mUOM.discount_Id)
                contentValueUOM.put(KEY_NET, mUOM.netAmt)
                contentValueUOM.put(KEY_VAT, mUOM.vatAmt)
                contentValueUOM.put(KEY_TOTAL, mUOM.totalAmt)
                contentValueUOM.put(KEY_PROMOTION_ID, mUOM.promotion_Id)
                contentValueUOM.put(KEY_UOM_PRICE, mUOM.uomPrice)
                contentValueUOM.put(KEY_IS_FREE, "0")

                db.insert(TABLE_LOAD_REQUEST_ITEM, null, contentValueUOM)

            }
        }
    }

    fun updateOverDueCollection(
        coll_No: String,
        paymentType: String,
        collType: String,
        chequeDate: String,
        chequeNumber: String,
        bank: String,
        mData: OutstandingData.CollectionData
    ) {

        val db = this.writableDatabase

        val contentValue = ContentValues()
        contentValue.put(KEY_COLLECTION_TYPE, collType)
        contentValue.put(KEY_PAYMENT_TYPE, paymentType)
        contentValue.put(KEY_INVOICE_NO, mData.invoice_number)
        contentValue.put(KEY_ORDER_ID, coll_No)
        var clear = mData.amountPay.toDouble() + mData.amountEnter.toDouble()
        contentValue.put(KEY_AMOUNT_CLEARED, "" + clear)
        if (collType == "2") {
            contentValue.put(KEY_CHEQUE_AMOUNT, mData.amountEnter)
            contentValue.put(KEY_CASH_AMOUNT, "0")
            contentValue.put(KEY_CASH_AMOUNTPRE, "0")
            contentValue.put(KEY_CHEQUE_AMOUNTPRE, "" + clear)
        } else {
            contentValue.put(KEY_CHEQUE_AMOUNT, "0")
            contentValue.put(KEY_CASH_AMOUNT, mData.amountEnter)
            contentValue.put(KEY_CASH_AMOUNTPRE, "" + clear)
        }
        contentValue.put(KEY_AMOUNT_PAY, mData.amountEnter)
        contentValue.put(KEY_IS_INVOICE_COMPLETE, "")
        contentValue.put(DATA_MARK_FOR_POST, "M")
        contentValue.put(KEY_OUTSTANDING, mData.invoiceComplete)

        db.update(
            TABLE_COLLECTION,
            contentValue,
            "$KEY_INVOICE_NO = ?",
            arrayOf<String>(mData.invoice_number)
        )

    }

    fun updateMultiCollection(
        allocatAmt: String,
        shelfAmt: String,
        disAmt: String,
        rebateAmt: String,
        rebateVatAmt: String,
        transactionId: String,
        lobCode: String,
        coll_No: String,
        paymentType: String,
        collType: String,
        chequeDate: String,
        chequeNumber: String,
        bank: String,
        arrData: List<OutstandingData.CollectionData>,
        customerCode: String,
        comment: String,
        str_onAccount: String,
        str_image: String,
        str_image2: String,
        bank_charge: String,
        tax_amount: String
    ) {

        val db = this.writableDatabase

        for (mData in arrData) {

            val contentValue = ContentValues()
            contentValue.put(KEY_COLLECTION_TYPE, collType)
            contentValue.put(KEY_PAYMENT_TYPE, paymentType)
            contentValue.put(KEY_INVOICE_NO, mData.invoice_number)
            contentValue.put(KEY_ORDER_ID, coll_No)

            if (collType == "2") {
                var mPendin =
                    Utils.twoDigit((mData.pendingAmount.toFloat() - mData.amountEnter.toFloat()))

                if (chequeDate == Utils.getCurrentDate()) {
                    contentValue.put(KEY_PENDING_AMOUNT, mPendin)
                } else if (chequeDate < Utils.getCurrentDate()) {
                    contentValue.put(KEY_PENDING_AMOUNT, mPendin)
                }

                contentValue.put(KEY_CHEQUE_AMOUNT, mData.amountEnter)
                contentValue.put(KEY_CASH_AMOUNT, "0")
                contentValue.put(KEY_CASH_AMOUNTPRE, "0")
                contentValue.put(KEY_CHEQUE_DATE, chequeDate)
                contentValue.put(KEY_CHEQUE_NUMBER, chequeNumber)
                contentValue.put(KEY_CHEQUE_BANK_NAME, bank)
            } else {
                var mPendin =
                    Utils.twoDigit((mData.pendingAmount.toFloat() - mData.amountEnter.toFloat()))
                contentValue.put(KEY_PENDING_AMOUNT, mPendin)
                var clear = mData.amountPay.toDouble() + mData.amountEnter.toDouble()
                contentValue.put(KEY_AMOUNT_CLEARED, "" + clear)
                contentValue.put(KEY_CHEQUE_AMOUNT, "0")
                contentValue.put(KEY_CASH_AMOUNT, mData.amountEnter)
                contentValue.put(KEY_CASH_AMOUNTPRE, "" + clear)
            }
            contentValue.put(KEY_AMOUNT_PAY, mData.amountEnter)
            contentValue.put(KEY_IS_INVOICE_COMPLETE, "")
            contentValue.put(DATA_MARK_FOR_POST, "M")
            contentValue.put(KEY_OUTSTANDING, mData.invoiceComplete)

            db.update(
                TABLE_COLLECTION,
                contentValue,
                "$KEY_INVOICE_NO = ?",
                arrayOf<String>(mData.invoice_number)
            )

            val contentValueHDD = ContentValues()
            contentValueHDD.put(KEY_INVOICE_ID, mData.invoice_id)
            contentValueHDD.put(KEY_INVOICE_NO, mData.invoice_number)
            contentValueHDD.put(KEY_CUSTOMER_CODE, customerCode)
            contentValueHDD.put(KEY_ORDER_ID, coll_No)
            contentValueHDD.put(KEY_TYPE, mData.itype)
            contentValueHDD.put(KEY_ORDER_AMOUNT, mData.amountEnter)
            db.insert(TABLE_COLLECTION_DETAIL, null, contentValueHDD)

        }

        val contentValueHD = ContentValues()
        contentValueHD.put(KEY_COLLECTION_TYPE, collType)
        contentValueHD.put(KEY_PAYMENT_TYPE, paymentType)
        contentValueHD.put(KEY_CUSTOMER_CODE, customerCode)
        contentValueHD.put(KEY_ORDER_ID, coll_No)
        var mPaid =
            allocatAmt.toFloat() - shelfAmt.toFloat() - disAmt.toFloat() - rebateAmt.toFloat()
        contentValueHD.put(KEY_ORDER_AMOUNT, mPaid)
        contentValueHD.put(KEY_ORDER_TYPE, "0")
        contentValueHD.put(KEY_ALLOCATED_AMT, allocatAmt)
        contentValueHD.put(KEY_SHELF_AMT, shelfAmt)
        contentValueHD.put(KEY_DISC_AMT, disAmt)
        contentValueHD.put(KEY_REBATE_AMT, rebateAmt)
        contentValueHD.put(LOB_ID, lobCode)
        contentValueHD.put(KEY_REBATE_VAT_AMT, rebateVatAmt)
        contentValueHD.put(KEY_PAYMENT_REFRENCE, rebateVatAmt)
        contentValueHD.put(KEY_TR_ID, transactionId)
        contentValueHD.put(KEY_IS_REBATE_VAT, "0")
        contentValueHD.put(KEY_CHEQUE_DATE, chequeDate)
        contentValueHD.put(KEY_CHEQUE_NUMBER, chequeNumber)
        contentValueHD.put(KEY_CHEQUE_BANK_NAME, bank)
        contentValueHD.put(KEY_INVOICE_NO, "")
        contentValueHD.put(KEY_COMMENT, comment)
        contentValueHD.put(KEY_ON_ACCOUNT, str_onAccount)
        contentValueHD.put(KEY_IMAGES, str_image)
        contentValueHD.put(KEY_IMAGE_2, str_image2)
        contentValueHD.put(KEY_BANK_CHARGE, bank_charge)
        contentValueHD.put(KEY_TAX_AMOUNT, tax_amount)
        contentValueHD.put(DATA_MARK_FOR_POST, "M")
        db.insert(TABLE_COLLECTION_HEADER, null, contentValueHD)

    }

