    fun addCollection(
        invNo: String,
        coll_No: String,
        cust_Code: String,
        dueDate: String,
        invoiceDate: String,
        invAmt: String,
        pendingAmt: String,
        lobId: String,
        groupId: String,
        cCode: String,
        name: String,
        paid: String,
        cashType: String,
        type: String,
        transactionType: String,
        mBonus: String,
        isTopup: String,
        source: String,
        paymentRef: String,
        paymentMode: String,
        mCOllType: String,
        mPartial: String,
        mCardType: String,
        mCardCharge: String
    ) {
        val db = this.writableDatabase

        if (transactionType == "Invoice") {
            if (cashType == "1") {
                val contentValueHD = ContentValues()
                contentValueHD.put(KEY_COLLECTION_TYPE, mCOllType)
                contentValueHD.put(KEY_CUSTOMER_CODE, cust_Code)
                contentValueHD.put(KEY_PAYMENT_TYPE, "3")
                contentValueHD.put(KEY_ORDER_TYPE, cashType)
                contentValueHD.put(KEY_ORDER_ID, coll_No)
                contentValueHD.put(KEY_INVOICE_NO, invNo)
                contentValueHD.put(KEY_SHELF_AMT, "0")
                contentValueHD.put(KEY_DISC_AMT, "0")
                contentValueHD.put(KEY_CHEQUE_DATE, "")
                contentValueHD.put(KEY_CHEQUE_NUMBER, "")
                contentValueHD.put(KEY_CHEQUE_BANK_NAME, "")
                contentValueHD.put(KEY_REBATE_AMT, "0")
                contentValueHD.put(KEY_REBATE_VAT_AMT, "0")
                contentValueHD.put(KEY_IS_REBATE_VAT, "0")
                contentValueHD.put(KEY_COMMENT, source)
                contentValueHD.put(LOB_ID, lobId)
                contentValueHD.put(KEY_ORDER_SO_REF, paymentRef)
                contentValueHD.put(KEY_PAYMENT_REFRENCE, paymentRef)
                contentValueHD.put(KEY_CARD_TYPE, mCardType)
                contentValueHD.put(KEY_CARD_CHARGE, mCardCharge)
                contentValueHD.put(KEY_IS_PARTIAL, mPartial)
                if (type == "Invoice") {
                    contentValueHD.put(KEY_IS_REBATE_VAT, paid)
                    contentValueHD.put(KEY_ALLOCATED_AMT, paid)
                    contentValueHD.put(DATA_MARK_FOR_POST, "N")
                } else {
                    contentValueHD.put(KEY_IS_REBATE_VAT, invAmt)
                    contentValueHD.put(KEY_ALLOCATED_AMT, invAmt)
                    contentValueHD.put(DATA_MARK_FOR_POST, "N")
                }
                contentValueHD.put(KEY_ON_ACCOUNT, "0")
                contentValueHD.put(KEY_IMAGES, "")
                contentValueHD.put(KEY_IMAGE_2, "")
                contentValueHD.put(KEY_BANK_CHARGE, "")
                contentValueHD.put(KEY_TAX_AMOUNT, "")
                contentValueHD.put(KEY_BONUS_AMT, mBonus)
                contentValueHD.put(KEY_IS_TOPUP, isTopup)
                if (isTopup == "1") {
                    contentValueHD.put(KEY_ORDER_AMOUNT, paid)
                    contentValueHD.put(DATA_MARK_FOR_POST, "M")
                } else {
                    if (paymentMode == "Prepaid") {

                        contentValueHD.put(KEY_COLLECTION_TYPE, "6")
                        contentValueHD.put(KEY_ORDER_AMOUNT, paid)
                        contentValueHD.put(DATA_MARK_FOR_POST, "M")

                        val contentValueDET = ContentValues()
                        contentValueDET.put(KEY_INVOICE_NO, invNo)
                        contentValueDET.put(KEY_COLLECTION_TYPE, "6")
                        contentValueDET.put(KEY_ORDER_ID, coll_No)
                        contentValueDET.put(KEY_TYPE, "Invoice")
                        contentValueDET.put(KEY_CUSTOMER_CODE, cust_Code)
                        contentValueDET.put(KEY_ORDER_AMOUNT, paid)
                        contentValueDET.put(KEY_INVOICE_ID, getInvoiceId(invNo))
                        db.insert(TABLE_COLLECTION_DETAIL, null, contentValueDET)

                    }
                }

                db.insert(TABLE_COLLECTION_HEADER, null, contentValueHD)

                if (isTopup == "1") {
                    val contentValueDET = ContentValues()
                    contentValueDET.put(KEY_INVOICE_NO, invNo)
                    contentValueDET.put(KEY_COLLECTION_TYPE, mCOllType)
                    contentValueDET.put(KEY_ORDER_ID, coll_No)
                    contentValueDET.put(KEY_TYPE, "Invoice")
                    contentValueDET.put(KEY_CUSTOMER_CODE, cust_Code)
                    contentValueDET.put(KEY_ORDER_AMOUNT, paid)
                    contentValueDET.put(KEY_INVOICE_ID, getInvoiceId(invNo))
                    db.insert(TABLE_COLLECTION_DETAIL, null, contentValueDET)
                }

            }
        }
        val contentValue = ContentValues()
        contentValue.put(KEY_COLLECTION_TYPE, "1")
        contentValue.put(KEY_CUSTOMER_CODE, cust_Code)
        contentValue.put(KEY_INVOICE_NO, invNo)
        contentValue.put(KEY_INVOICE_ID, "0")
        contentValue.put(KEY_ORDER_ID, coll_No)
        contentValue.put(KEY_INVOICE_AMOUNT, invAmt)
        contentValue.put(KEY_INVOICE_DATE, invoiceDate)
        contentValue.put(KEY_PENDING_AMOUNT, pendingAmt)
        contentValue.put(KEY_DUE_DATE, dueDate)
        contentValue.put(KEY_PAYMENT_TYPE, "0")
        contentValue.put(KEY_INVOICE_DAYS, "0")
        contentValue.put(KEY_CHEQUE_AMOUNT, "0")
        contentValue.put(KEY_CHEQUE_AMOUNTPRE, "0")
        contentValue.put(KEY_CHEQUE_AMOUNT_INDIVIDUAL, "0")
        contentValue.put(KEY_CHEQUE_NUMBER, "0000")
        contentValue.put(KEY_CHEQUE_DATE, "0000")
        contentValue.put(KEY_CHEQUE_BANK_CODE, "0000")
        contentValue.put(KEY_CHEQUE_BANK_NAME, "0000")
        contentValue.put(KEY_INDICATOR, MyApplication.ADD_INDICATOR)
        contentValue.put(KEY_IS_INVOICE_COMPLETE, MyApplication.INVOICE_INCOMPLETE)
        contentValue.put(KEY_OUTSTANDING, "0")
        contentValue.put(LOB_ID, lobId)
        contentValue.put(KEY_CUS_GROUP_ID, groupId)
        contentValue.put(KEY_CUSTOMER_ID, cCode)
        contentValue.put(KEY_FIRST_NAME, name)
        contentValue.put(KEY_TYPE, type)
        contentValue.put(KEY_OVERDUE_DAYS, Utils.getDayDifference(dueDate))
        contentValue.put(KEY_PDC_AMOUNT, "0")
        contentValue.put(KEY_NET_AMOUNT, "0")
        contentValue.put(KEY_VAT_AMOUNT, "0")
        contentValue.put(KEY_DEBIT_TYPE, "")
        contentValue.put(IS_OVERDUE, "0")
        if (cashType == "1") {
            if (type == "Invoice") {
                contentValue.put(KEY_AMOUNT_CLEARED, paid)
                contentValue.put(KEY_CASH_AMOUNT, "0")
                contentValue.put(KEY_CASH_AMOUNTPRE, "0")
                contentValue.put(KEY_AMOUNT_PAY, "0")
                contentValue.put(DATA_MARK_FOR_POST, "N")
            } else {
                contentValue.put(KEY_AMOUNT_CLEARED, invAmt)
                contentValue.put(KEY_CASH_AMOUNT, invAmt)
                contentValue.put(KEY_CASH_AMOUNTPRE, invAmt)
                contentValue.put(KEY_AMOUNT_PAY, invAmt)
                contentValue.put(DATA_MARK_FOR_POST, "M")
            }
        } else {
            contentValue.put(KEY_AMOUNT_CLEARED, paid)
            contentValue.put(KEY_CASH_AMOUNT, "0")
            contentValue.put(KEY_CASH_AMOUNTPRE, "0")
            contentValue.put(KEY_AMOUNT_PAY, "0")
            contentValue.put(DATA_MARK_FOR_POST, "N")
        }
        db.insert(TABLE_COLLECTION, null, contentValue)
    }

    fun insertOutStandingInvoice(
        arrData: List<OutstandingData.CollectionData>,
        mLobId: String
    ) {

        val db = this.writableDatabase

        for (mCollection in arrData) {

            val contentValue = ContentValues()
            contentValue.put(KEY_COLLECTION_TYPE, MyApplication.COLLECTION_INVOICE)
            contentValue.put(KEY_CUSTOMER_CODE, mCollection.customer_id)
            contentValue.put(KEY_INVOICE_NO, mCollection.invoice_number)
            contentValue.put(KEY_ORDER_ID, "")
            contentValue.put(KEY_INVOICE_ID, mCollection.invoice_id)
            contentValue.put(KEY_INVOICE_AMOUNT, mCollection.grandTotal)
