            contentValue.put(KEY_INVOICE_DAYS, "0")
            contentValue.put(KEY_PAYMENT_TYPE, "0")
            var amtCleare =
                mCollection.grandTotal.toDouble() - mCollection.pendingAmount.toDouble()
            contentValue.put(KEY_AMOUNT_CLEARED, Utils.twoDigit(amtCleare.toFloat()))

