    fun insertCustomerInventory(arrData: List<InventoryData.AssignData>) {

        val db = this.writableDatabase

        for (mData in arrData) {

            if (mData.assign_inventory != null) {
                for (mInvData in mData.assign_inventory.inventoryDetail) {
                    if (!checkInventoryExist(
                            mInvData.assign_inventory_id,
                            mData.customer_id,
                            mInvData.item_id
                        )
                    ) {
                        val contentValue = ContentValues()
                        contentValue.put(KEY_INVENTORY_ID, mInvData.assign_inventory_id)
                        contentValue.put(KEY_CUSTOMER_ID, mData.customer_id)
                        contentValue.put(KEY_ITEM_ID, mInvData.item_id)
                        contentValue.put(KEY_UOM_ID, mInvData.item_uom_id)
                        contentValue.put(KEY_CAPACITY, mInvData.capacity)
                        contentValue.put(KEY_ITEM_BRAND_ID, getItemBrandId(mInvData.item_id))
                        contentValue.put(
                            KEY_ITEM_CATEGORY_ID,
                            getItemCategoryId(mInvData.item_id)
                        )

                        db.insert(TABLE_CUSTOMER_INVENTORY, null, contentValue)
                    } else {
                        val contentValue = ContentValues()
                        contentValue.put(KEY_UOM_ID, mInvData.item_uom_id)
                        contentValue.put(KEY_CAPACITY, mInvData.capacity)

                        db.update(
                            TABLE_CUSTOMER_INVENTORY,
                            contentValue,
                            "$KEY_CUSTOMER_ID =? AND $KEY_INVENTORY_ID =? AND $KEY_ITEM_ID =?",
                            arrayOf<String>(
                                mData.customer_id,
                                mInvData.assign_inventory_id, mInvData.item_id
                            )
                        )
                    }
                }
            }
        }
    }

