    fun insertToolSurvey(arrData: List<ToolSurveyData.DistData>) {

        val db = this.writableDatabase

        for (mData in arrData) {
            for (mCustomer in mData.distributionCustomer) {
                if (mCustomer.distribution != null) {
                    for (mSurvey in mCustomer.distribution!!.survey) {

                        if (!checkToolSurveyExist(mSurvey.id, mCustomer.distribution!!.id)) {
                            val contentValue = ContentValues()
                            contentValue.put(KEY_SURVEY_ID, mSurvey.id)
                            contentValue.put(KEY_DISPLAY_TOOL_ID, mCustomer.distribution!!.id)
                            contentValue.put(KEY_SURVEY_TYPE, mSurvey.survey_type_id)
                            contentValue.put(KEY_SURVEY_NAME, mSurvey.name)

                            db.insert(TABLE_DISPLAY_TOOL_SURVEY, null, contentValue)

                            for (mQuestion in mSurvey.questions) {
                                if (!checkQuestionExist(mQuestion.id)) {
                                    val contentValue = ContentValues()
                                    contentValue.put(KEY_SURVEY_ID, mSurvey.id)
                                    contentValue.put(KEY_QUESTION_ID, mQuestion.id)
                                    contentValue.put(KEY_QUESTION_NAME, mQuestion.question)
                                    contentValue.put(KEY_QUESTION_TYPE, mQuestion.question_type)

                                    db.insert(TABLE_SURVEY_QUESTION, null, contentValue)

                                    for (mValue in mQuestion.questionValue) {
                                        val contentValue = ContentValues()
                                        contentValue.put(KEY_SURVEY_ID, mValue.survey_id)
                                        contentValue.put(
                                            KEY_QUESTION_ID,
                                            mValue.survey_question_id
                                        )
                                        contentValue.put(
                                            KEY_QUESTION_VALUE,
                                            mValue.question_value
                                        )

                                        db.insert(TABLE_QUESTION_VALUE, null, contentValue)
                                    }
                                }

                            }
                        }
                    }
                }
            }
        }
    }

