    fun insertCouponItem(arrData: List<CouponData.Coupon>) {

        val db = this.writableDatabase
        for (mData in arrData) {

            var isSale = false
            for (mCus in mData.customerCoupon) {
                if (mCus.customer_id != null) {
                    isSale = true
                    val contentValue2 = ContentValues()
                    contentValue2.put(KEY_FROM_SERIAL, mCus.serial_number)
                    contentValue2.put(KEY_CUSTOMER_ID, mCus.customer_id)
                    contentValue2.put(KEY_COUPON_ID, mData.id)

                    if (mCus.reedem_date != null) {
                        contentValue2.put(KEY_IS_ACCEPT, "1")
                    } else {
                        contentValue2.put(KEY_IS_ACCEPT, "0")
                    }

                    if (mCus.price != null) {
                        contentValue2.put(KEY_UOM_PRICE, mCus.price)
                    } else {
                        contentValue2.put(KEY_UOM_PRICE, "0")
                    }

                    db.insert(TABLE_COUPON_CUSTOMER, null, contentValue2)
                }
            }

            if (!isSale) {
                val contentValue1 = ContentValues()
                contentValue1.put(KEY_FROM_SERIAL, mData.serialFrom)
                contentValue1.put(KEY_TO_SERIAL, mData.serialTo)
                contentValue1.put(KEY_QTY, mData.total_qty)
                contentValue1.put(KEY_ACTUAL_QTY, mData.total_qty)
                contentValue1.put(KEY_ITEM_ID, mData.item_id)
                contentValue1.put(KEY_COUPON_ID, mData.id)

                db.insert(TABLE_COUPON_STOCK, null, contentValue1)

            }
        }
    }


