    fun insertCustomerPlanogram(arrData: List<PlanogramData.PlanoData>) {

        val db = this.writableDatabase

        for (mData in arrData) {

            for (mPlanogram in mData.planogram) {

                var tooldId = ""
                var toolName = ""

                if (mPlanogram.distribution != null) {
                    for (mPlanoDist in mPlanogram.distribution!!) {

                        tooldId = mPlanoDist.id
                        toolName = mPlanoDist.name

                        if (!checkPlanogramExist(mPlanogram.id, mData.cusotmer_id, tooldId)) {

                            for (mPlanoImage in mPlanoDist.image) {
                                val contentValue1 = ContentValues()
                                contentValue1.put(KEY_PLANOGRAM_ID, mPlanogram.id)
                                contentValue1.put(KEY_CUSTOMER_ID, mData.cusotmer_id)
                                contentValue1.put(KEY_DISPLAY_TOOL_ID, tooldId)
                                contentValue1.put(KEY_IMAGES, mPlanoImage.image_string)

                                db.insert(TABLE_PLANOGRAM_IMAGE, null, contentValue1)
                            }

                            val contentValue = ContentValues()
                            contentValue.put(KEY_PLANOGRAM_ID, mPlanogram.id)
                            contentValue.put(KEY_CUSTOMER_ID, mData.cusotmer_id)
                            contentValue.put(KEY_PLANOGRAM_NAME, mPlanogram.name)
                            contentValue.put(KEY_DISPLAY_TOOL_ID, tooldId)
                            contentValue.put(KEY_DISPLAY_TOOL_NAME, toolName)

                            db.insert(TABLE_PLANOGRAM, null, contentValue)
                        }
                    }
                }
            }
        }
    }

    fun insertCustomerDistribution(arrData: List<DistributionData.DistData>) {

        val db = this.writableDatabase

        for (mData in arrData) {

            if (mData.distribution != null) {
                for (mDisData in mData.distribution) {

                    if (mDisData != null) {
                        if (!checkDistributionExist(mDisData.id, mData.cusotmer_id)) {

                            val contentValue = ContentValues()
                            contentValue.put(KEY_DISPLAY_TOOL_ID, mDisData.id)
                            contentValue.put(KEY_CUSTOMER_ID, mData.cusotmer_id)
                            contentValue.put(KEY_DISPLAY_TOOL_NAME, mDisData.name)

                            db.insert(TABLE_DISPLAY_TOOL, null, contentValue)

                            if (mDisData.modelStock.isNotEmpty()) {
                                for (mModel in mDisData.modelStock) {
                                    if (mModel.customer_id == mData.cusotmer_id) {
                                        for (mModelData in mModel.modelStockDetail) {
                                            val contentValue1 = ContentValues()

                                            contentValue1.put(KEY_DISPLAY_TOOL_ID, mDisData.id)
                                            contentValue1.put(
                                                KEY_CUSTOMER_ID,
                                                mData.cusotmer_id
                                            )
                                            contentValue1.put(KEY_ITEM_ID, mModelData.item_id)
                                            contentValue1.put(
                                                KEY_UOM_ID,
                                                mModelData.item_uom_id
                                            )
                                            contentValue1.put(KEY_QTY, mModelData.capacity)
                                            contentValue1.put(
                                                KEY_ITEM_BRAND_ID,
                                                getItemBrandId(mModelData.item_id)
                                            )
                                            contentValue1.put(
                                                KEY_ITEM_CATEGORY_ID,
                                                getItemCategoryId(mModelData.item_id)
                                            )

                                            db.insert(
                                                TABLE_DISPLAY_TOOL_ITEM,
                                                null,
                                                contentValue1
                                            )
                                        }
                                    }
                                }
                            }
                        } else {
                            if (mDisData.modelStock.isNotEmpty()) {
                                for (mModel in mDisData.modelStock) {
                                    if (mModel.customer_id == mData.cusotmer_id) {
                                        for (mModelData in mModel.modelStockDetail) {

                                            if (!checkDistributionItemExist(
                                                    mDisData.id,
                                                    mData.cusotmer_id,
                                                    mModelData.item_id
                                                )
                                            ) {
                                                val contentValue1 = ContentValues()
                                                contentValue1.put(
                                                    KEY_DISPLAY_TOOL_ID,
                                                    mDisData.id
                                                )
                                                contentValue1.put(
                                                    KEY_CUSTOMER_ID,
                                                    mData.cusotmer_id
                                                )
                                                contentValue1.put(
                                                    KEY_ITEM_ID,
                                                    mModelData.item_id
                                                )
                                                contentValue1.put(
                                                    KEY_UOM_ID,
                                                    mModelData.item_uom_id
                                                )
                                                contentValue1.put(KEY_QTY, mModelData.capacity)
                                                contentValue1.put(
                                                    KEY_ITEM_BRAND_ID,
                                                    getItemBrandId(mModelData.item_id)
                                                )
                                                contentValue1.put(
                                                    KEY_ITEM_CATEGORY_ID,
                                                    getItemCategoryId(mModelData.item_id)
                                                )

                                                db.insert(
                                                    TABLE_DISPLAY_TOOL_ITEM,
                                                    null,
                                                    contentValue1
                                                )
                                            } else {
                                                val contentValue1 = ContentValues()
                                                contentValue1.put(
                                                    KEY_UOM_ID,
                                                    mModelData.item_uom_id
                                                )
                                                contentValue1.put(KEY_QTY, mModelData.capacity)

                                                db.update(
                                                    TABLE_DISPLAY_TOOL_ITEM,
                                                    contentValue1,
                                                    "$KEY_CUSTOMER_ID =? AND $KEY_DISPLAY_TOOL_ID =? AND $KEY_ITEM_ID =?",
                                                    arrayOf<String>(
                                                        mData.cusotmer_id,
                                                        mDisData.id, mModelData.item_id
                                                    )
                                                )
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    private fun checkInventoryExist(idd: String, custId: String, itemId: String): Boolean {
        val db = this.writableDatabase
        var userExist = false
        val c = db.query(
            TABLE_CUSTOMER_INVENTORY,
            null,
            "$KEY_INVENTORY_ID = ? AND $KEY_CUSTOMER_ID = ? AND $KEY_ITEM_ID = ?",
            arrayOf<String>(idd, custId, itemId),
            null,
            null,
            null
        )
            ?: return userExist
        while (c.moveToNext()) {
            userExist = true
        }
        c.close()
        return userExist
    }

    private fun checkDistributionExist(idd: String, custId: String): Boolean {
        val db = this.writableDatabase
        var userExist = false
        val c = db.query(
            TABLE_DISPLAY_TOOL,
            null,
            "$KEY_DISPLAY_TOOL_ID = ? AND $KEY_CUSTOMER_ID = ?",
            arrayOf<String>(idd, custId),
            null,
            null,
            null
        )
            ?: return userExist
        while (c.moveToNext()) {
            userExist = true
        }
        c.close()
        return userExist
    }

    private fun checkDistributionItemExist(
        idd: String,
        custId: String,
        itemId: String
    ): Boolean {
        val db = this.writableDatabase
        var userExist = false
        val c = db.query(
            TABLE_DISPLAY_TOOL_ITEM,
            null,
            "$KEY_DISPLAY_TOOL_ID = ? AND $KEY_CUSTOMER_ID = ? AND $KEY_ITEM_ID = ?",
            arrayOf<String>(idd, custId, itemId),
            null,
            null,
            null
        )
            ?: return userExist
        while (c.moveToNext()) {
            userExist = true
        }
        c.close()
        return userExist
    }

