    //INSERT InventoryPost
    fun insertInventoryPost(
        mUniqueId: String,
        arrData: ArrayList<CustomerInventory>,
        mBrand: String,
        mCategory: String,
        mHeadBrand: String,
        mHeadCategory: String
    ) {
        val db = this.writableDatabase

        var inventoryId = ""
        var customerId = ""

        for (mData in arrData) {

            inventoryId = mData.inventoryId!!
            customerId = mData.customerId!!

            if (mData.totalFillQty!!.isNotEmpty()) {

                val contentValue = ContentValues()
                contentValue.put(KEY_INVENTORY_ID, mData.inventoryId)
                contentValue.put(KEY_CUSTOMER_ID, mData.customerId)
                contentValue.put(KEY_ITEM_ID, mData.itemId)
                contentValue.put(KEY_UNIQUE_ID, mUniqueId)
                contentValue.put(KEY_UOM_ID, mData.uomId)
                contentValue.put(KEY_QTY, mData.totalFillQty)
                contentValue.put(KEY_REFILL_QTY, mData.refillQty)
                contentValue.put(KEY_FILL_QTY, mData.fillQty)
                contentValue.put(KEY_REORDER_QTY, mData.reorderQty)
                contentValue.put(KEY_CAPACITY, mData.capacity)
                contentValue.put(KEY_OUT_OF_STOCK, mData.outOfStock)
                db.insert(TABLE_INVENTORY_POST_ITEM, null, contentValue)

                if (mData.arrExpiry!!.size > 0) {

                    for (mItem in mData.arrExpiry!!) {
                        val contentValue = ContentValues()
                        contentValue.put(KEY_INVENTORY_ID, mData.inventoryId)
                        contentValue.put(KEY_CUSTOMER_ID, mData.customerId)
                        contentValue.put(KEY_ITEM_ID, mData.itemId)
                        contentValue.put(KEY_UNIQUE_ID, mUniqueId)
                        contentValue.put(KEY_UOM_ID, mItem["UOMId"])
                        contentValue.put(KEY_QTY, mItem["Qty"])
                        contentValue.put(KEY_EXPIRY_DATE, mItem["Expiry"])
                        db.insert(TABLE_INVENTORY_POST_ITEM_EXPIRY, null, contentValue)
                    }
                }

                if (mData.arrDer!!.size > 0) {

                    for (mItem in mData.arrDer!!) {
                        val contentValue = ContentValues()
                        contentValue.put(KEY_INVENTORY_ID, mData.inventoryId)
                        contentValue.put(KEY_CUSTOMER_ID, mData.customerId)
                        contentValue.put(KEY_ITEM_ID, mData.itemId)
                        contentValue.put(KEY_UNIQUE_ID, mUniqueId)
                        contentValue.put(KEY_UOM_ID, mData.uomId)
                        contentValue.put(KEY_DAMAGED_QTY, mItem["Damage"])
                        contentValue.put(KEY_EXPIRY_QTY, mItem["Expiry"])
                        contentValue.put(KEY_SALEABLE_QTY, mItem["Saleble"])
                        db.insert(TABLE_INVENTORY_DER_POST_ITEM, null, contentValue)
                    }
                }
            }
        }

        val contentValue = ContentValues()
        contentValue.put(KEY_INVENTORY_ID, inventoryId)
        contentValue.put(KEY_CUSTOMER_ID, customerId)
        contentValue.put(KEY_UNIQUE_ID, mUniqueId)
        contentValue.put(DATA_MARK_FOR_POST, "M")
        contentValue.put(KEY_ITEM_BRAND_ID, mBrand)
