    //INSERT InventoryPost
    fun insertDisplayPost(
        mUniqueId: String,
        arrData: ArrayList<DistributionItem>,
        mBrand: String,
        mCategory: String,
        mHeadBrand: String,
        mHeadCategory: String
    ) {
        val db = this.writableDatabase

        var isData: Boolean = false

        for (mData in arrData) {

            var isCHildData = false
            if (mData.actualFacing!!.isNotEmpty()) {
                val contentValue = ContentValues()
                contentValue.put(KEY_DISPLAY_TOOL_ID, mData.distributionId)
                contentValue.put(KEY_CUSTOMER_ID, mData.customerId)
                contentValue.put(KEY_ITEM_ID, mData.itemId)
                contentValue.put(KEY_UNIQUE_ID, mUniqueId)
                contentValue.put(KEY_UOM_ID, mData.uomId)
                contentValue.put(KEY_TOTAL_FACING, mData.totalFacing)
                contentValue.put(KEY_ACTUAL_FACING, mData.actualFacing)
                contentValue.put(KEY_SCORE, mData.score)
                db.insert(TABLE_SOS_POST_ITEM, null, contentValue)
            }

            if (mData.arrExp!!.size > 0) {
                for (mExp in mData.arrExp!!) {
                    val contentValue = ContentValues()
                    contentValue.put(KEY_DISPLAY_TOOL_ID, mData.distributionId)
                    contentValue.put(KEY_CUSTOMER_ID, mData.customerId)
                    contentValue.put(KEY_ITEM_ID, mData.itemId)
                    contentValue.put(KEY_UNIQUE_ID, mUniqueId)
                    contentValue.put(KEY_UOM_ID, mExp["UOMId"])
                    contentValue.put(KEY_QTY, mExp["Qty"])
                    contentValue.put(KEY_EXPIRY_DATE, mExp["Expiry"])
                    db.insert(TABLE_EXPIRY_POST_ITEM, null, contentValue)
                }
            }

            if (mData.arrDer!!.size > 0) {
                isCHildData = true
                for (mExp in mData.arrDer!!) {
                    val contentValue = ContentValues()
                    contentValue.put(KEY_DISPLAY_TOOL_ID, mData.distributionId)
                    contentValue.put(KEY_CUSTOMER_ID, mData.customerId)
                    contentValue.put(KEY_ITEM_ID, mData.itemId)
                    contentValue.put(KEY_UNIQUE_ID, mUniqueId)
                    contentValue.put(KEY_UOM_ID, mData.uomId)
                    contentValue.put(KEY_DAMAGED_QTY, mExp["Damage"])
                    contentValue.put(KEY_EXPIRY_QTY, mExp["Expiry"])
                    contentValue.put(KEY_SALEABLE_QTY, mExp["Saleble"])
                    db.insert(TABLE_DER_POST_ITEM, null, contentValue)
                }
            }

            if (mData.toFill!!.isNotEmpty()) {
                isData = true
                val contentValue = ContentValues()
                contentValue.put(KEY_DISPLAY_TOOL_ID, mData.distributionId)
                contentValue.put(KEY_CUSTOMER_ID, mData.customerId)
                contentValue.put(KEY_ITEM_ID, mData.itemId)
                contentValue.put(KEY_UNIQUE_ID, mUniqueId)
                contentValue.put(KEY_UOM_ID, mData.uomId)
                contentValue.put(KEY_QTY, mData.toFill)
                contentValue.put(KEY_OUT_OF_STOCK, mData.outOfStock)
                contentValue.put(KEY_CAPACITY, mData.capacity)
                contentValue.put(KEY_SALEABLE_QTY, mData.saleable)
                db.insert(TABLE_STOCK_POST_ITEM, null, contentValue)
            } else {

                if (isCHildData) {
                    isData = true
                    val contentValue = ContentValues()
                    contentValue.put(KEY_DISPLAY_TOOL_ID, mData.distributionId)
                    contentValue.put(KEY_CUSTOMER_ID, mData.customerId)
                    contentValue.put(KEY_ITEM_ID, mData.itemId)
                    contentValue.put(KEY_UNIQUE_ID, mUniqueId)
                    contentValue.put(KEY_UOM_ID, mData.uomId)
                    contentValue.put(KEY_QTY, "0")
                    contentValue.put(KEY_OUT_OF_STOCK, mData.outOfStock)
                    contentValue.put(KEY_CAPACITY, mData.capacity)
                    contentValue.put(KEY_SALEABLE_QTY, "0")
                    db.insert(TABLE_STOCK_POST_ITEM, null, contentValue)
                }
            }

        }

        if (isData) {
            val contentValue = ContentValues()
            contentValue.put(KEY_DISPLAY_TOOL_ID, arrData[0].distributionId)
            contentValue.put(KEY_CUSTOMER_ID, arrData[0].customerId)
            contentValue.put(KEY_UNIQUE_ID, mUniqueId)
            contentValue.put(KEY_ITEM_BRAND_ID, mBrand)
            contentValue.put(KEY_ITEM_CATEGORY_ID, mCategory)
            contentValue.put(KEY_ITEM_MAIN_BRAND_ID, mHeadBrand)
            contentValue.put(KEY_ITEM_MAIN_CATEGORY_ID, mHeadCategory)
            contentValue.put(DATA_MARK_FOR_POST, "M")
            db.insert(TABLE_STOCK_POST_HEADER, null, contentValue)
        }

    }

