    fun getPromotionalItemDetail(stAmt: String): PromotionalItem {
        val mSalesman = PromotionalItem()
        val db = this.readableDatabase
        try {
            val selectQuery = ("SELECT * FROM " + TABLE_PROMOTION + " WHERE " +
                    KEY_AMOUNT + " >= " + stAmt + " ORDER BY " + KEY_AMOUNT + " DESC LIMIT 1")
            val cursor = db.rawQuery(selectQuery, null)
            if (cursor.count > 0) {
                if (cursor.moveToFirst()) {
                    do {
                        mSalesman.promotionId = cursor.getString(
                            cursor.getColumnIndex(
                                KEY_PROMOTION_ACOUNT_ID
                            )
                        )
                        mSalesman.itemName =
                            cursor.getString(cursor.getColumnIndex(KEY_ITEM_NAME))
                        mSalesman.amount = cursor.getString(cursor.getColumnIndex(KEY_AMOUNT))

                    } while (cursor.moveToNext())
                }
            }
            cursor.close()
        } catch (e: Exception) {
            e.printStackTrace()
        }
        return mSalesman
    }

