    //Get Distribution Items
    fun getAllDistributionItemList(
        mCustomerCode: String,
        toolId: String
    ): ArrayList<DistributionItem> {
        val arrData: ArrayList<DistributionItem> = ArrayList()
        val db = this.readableDatabase
        try {
            val cursor = db.rawQuery(
                ("SELECT * FROM " +
                        TABLE_DISPLAY_TOOL_ITEM + " WHERE " +
                        KEY_CUSTOMER_ID + "=? AND " + KEY_DISPLAY_TOOL_ID + "=?"),
                arrayOf<String>(mCustomerCode, toolId)
            )
            // looping through all rows and adding to list
            try {
                if (cursor.moveToFirst()) {
                    do {
                        val mData = DistributionItem()

                        var mItem =
                            getItemDetailFromId(
                                cursor.getString(
                                    cursor.getColumnIndex(
                                        KEY_ITEM_ID
                                    )
                                )
                            )

                        mData.distributionId =
                            cursor.getString(cursor.getColumnIndex(KEY_DISPLAY_TOOL_ID))
                        mData.customerId =
                            cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_ID))
                        mData.itemId = cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID))
                        mData.itemName =
                            getItemName(cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID)))
                        mData.itembarcode = mItem!!.barcode
                        mData.itemCode =
                            getItemCode(cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID)))
                        mData.uomId = cursor.getString(cursor.getColumnIndex(KEY_UOM_ID))
                        mData.uomName =
                            getUOMName(cursor.getString(cursor.getColumnIndex(KEY_UOM_ID)))

                        if (cursor.getString(cursor.getColumnIndex(KEY_QTY)) == "") {
                            mData.capacity = getCustomerToolCapacity(
                                cursor.getString(cursor.getColumnIndex(KEY_DISPLAY_TOOL_ID)),
                                cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_ID)),
                                cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID))
                            )
                        } else {
                            var capacity = cursor.getString(cursor.getColumnIndex(KEY_QTY))
                            if (capacity.toDouble() > 0) {
                                mData.capacity =
                                    cursor.getString(cursor.getColumnIndex(KEY_QTY))
                            } else {
                                mData.capacity = getCustomerToolCapacity(
                                    cursor.getString(cursor.getColumnIndex(KEY_DISPLAY_TOOL_ID)),
                                    cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_ID)),
                                    cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID))
                                )
                            }
                        }

                        mData.outOfStock = getCustomerToolOutOfStock(
                            cursor.getString(cursor.getColumnIndex(KEY_DISPLAY_TOOL_ID)),
                            cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_ID)),
                            cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID))
                        )
                        mData.totalFacing =
                            getCustomerToolSOSTotalFacing(
                                cursor.getString(cursor.getColumnIndex(KEY_DISPLAY_TOOL_ID)),
                                cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_ID)),
                                cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID))
                            )
                        mData.actualFacing =
                            getCustomerToolSOSActualFacing(
                                cursor.getString(cursor.getColumnIndex(KEY_DISPLAY_TOOL_ID)),
                                cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_ID)),
                                cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID))
                            )
                        mData.score =
                            getCustomerToolSOSScore(
                                cursor.getString(cursor.getColumnIndex(KEY_DISPLAY_TOOL_ID)),
                                cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_ID)),
                                cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID))
                            )
                        mData.brand = mItem!!.brandId.toString()
                        mData.categoryId = mItem!!.majorCategory.toString()
                        mData.group = mItem!!.groupId.toString()

                        mData.toFill = getCustomerToolStockFill(
                            cursor.getString(cursor.getColumnIndex(KEY_DISPLAY_TOOL_ID)),
                            cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_ID)),
                            cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID))
                        )
                        mData.saleable = getCustomerToolStockSalable(
                            cursor.getString(cursor.getColumnIndex(KEY_DISPLAY_TOOL_ID)),
                            cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_ID)),
                            cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID))
                        )

                        var arrDERData = getCustomerToolDERDetail(
                            cursor.getString(cursor.getColumnIndex(KEY_DISPLAY_TOOL_ID)),
                            cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_ID)),
                            cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID))
                        )

                        mData.arrDer = arrDERData

                        var arrExpData = getCustomerToolExpDetail(
                            cursor.getString(cursor.getColumnIndex(KEY_DISPLAY_TOOL_ID)),
                            cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_ID)),
                            cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID))
                        )
                        mData.arrExp = arrExpData
                        arrData.add(mData)
                    } while (cursor.moveToNext())
                }
            } finally {
                try {
                    db.close()
                } catch (ignore: Exception) {
                }
            }
        } finally {
            try {
                db.close()
            } catch (ignore: Exception) {
            }
        }
        return arrData
    }

