    //Get customer Inventory
    fun getAllCustomerInventory(
        mCustomerCode: String,
        mBrand: String,
        mCategeory: String
    ): ArrayList<CustomerInventory> {
        val arrData: ArrayList<CustomerInventory> = ArrayList()
        val db = this.readableDatabase
        try {
            val cursor = db.rawQuery(
                ("SELECT * FROM " +
                        TABLE_CUSTOMER_INVENTORY + " WHERE " +
                        KEY_CUSTOMER_ID + "=?"), arrayOf<String>(mCustomerCode)
            )
            // looping through all rows and adding to list
            try {
                if (cursor.moveToFirst()) {
                    do {
                        val mData = CustomerInventory()

                        var mItem =
                            getItemDetailFromId(
                                cursor.getString(
                                    cursor.getColumnIndex(
                                        KEY_ITEM_ID
                                    )
                                )
                            )
                        mData.inventoryId =
                            cursor.getString(cursor.getColumnIndex(KEY_INVENTORY_ID))
                        mData.customerId =
                            cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_ID))
                        mData.itemId = cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID))
                        mData.itemCode = mItem!!.itemCode
                        mData.itemName = mItem!!.itemName
                        mData.uomId = cursor.getString(cursor.getColumnIndex(KEY_UOM_ID))
                        mData.uomName =
                            getUOMName(cursor.getString(cursor.getColumnIndex(KEY_UOM_ID)))

                        if (cursor.getString(cursor.getColumnIndex(KEY_CAPACITY)) == "") {
                            mData.capacity =
                                getCustomerPostInventoryCapacityDetail(
                                    cursor.getString(cursor.getColumnIndex(KEY_INVENTORY_ID)),
                                    cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_ID)),
                                    cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID))
                                )
                        } else {
                            var capacity = cursor.getString(cursor.getColumnIndex(KEY_CAPACITY))
                            if (capacity.toDouble() > 0) {
                                mData.capacity =
                                    cursor.getString(cursor.getColumnIndex(KEY_CAPACITY))
                            } else {
                                mData.capacity =
                                    getCustomerPostInventoryCapacityDetail(
                                        cursor.getString(cursor.getColumnIndex(KEY_INVENTORY_ID)),
                                        cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_ID)),
                                        cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID))
                                    )
                            }
                        }

                        mData.itemCategory = mItem!!.majorCategory.toString()
                        mData.itemBrand = mItem!!.brandId.toString()
                        mData.itemGroup = mItem!!.groupId.toString()

                        mData.totalFillQty = getCustomerPostInventoryQtyDetail(
                            cursor.getString(cursor.getColumnIndex(KEY_INVENTORY_ID)),
                            cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_ID)),
                            cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID))
                        )
                        mData.refillQty = getCustomerPostInventoryRefillDetail(
                            cursor.getString(cursor.getColumnIndex(KEY_INVENTORY_ID)),
                            cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_ID)),
                            cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID))
                        )
                        mData.fillQty = getCustomerPostInventoryFillDetail(
                            cursor.getString(cursor.getColumnIndex(KEY_INVENTORY_ID)),
                            cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_ID)),
                            cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID))
                        )
                        mData.outOfStock = getCustomerPostInventoryOutOfStockDetail(
                            cursor.getString(cursor.getColumnIndex(KEY_INVENTORY_ID)),
                            cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_ID)),
                            cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID))
                        )

                        mData.reorderQty = getCustomerPostInventoryReOrderDetail(
                            cursor.getString(cursor.getColumnIndex(KEY_INVENTORY_ID)),
                            cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_ID)),
                            cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID))
                        )
                        var arrExpData = getCustomerInventoryDetail(
                            cursor.getString(cursor.getColumnIndex(KEY_INVENTORY_ID)),
                            cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_ID)),
                            cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID))
                        )
                        mData.arrExpiry = arrExpData
                        mData.mUOMList =
                            getItemUOMList(cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID)))

                        if (mData.itemBrand == mBrand && mData.itemCategory == mCategeory) {
                            arrData.add(mData)
                        }

                    } while (cursor.moveToNext())
                }
            } finally {
                try {
                    db.close()
                } catch (ignore: Exception) {
                }
            }
        } finally {
            try {
                db.close()
            } catch (ignore: Exception) {
            }
        }
        return arrData
    }

