//INSERT VanStock HEADER ONLY SINGLE
//RIDDHI

    fun insertVanStock(
        mLoadList: List<SalesmanLoadDetail>
    ) {
        val db = this.writableDatabase

        db.beginTransaction();

        try {
            for (mLoad in mLoadList) {

                if (mLoad.loadQty.toDouble() > 0) {
                    if (checkVanItemExist(mLoad.itemId!!)) {
                        var existQty = getVanStockItemQty(mLoad.itemId!!).toDouble()
                        var actualQty = getVanStockActualQty(mLoad.itemId!!).toDouble()
                        var itemQty = mLoad.loadQty.toDouble()
                        var totalQty = existQty + itemQty
                        var totalAcQty = actualQty + itemQty

                        val contentValue = ContentValues()
                        contentValue.put(KEY_ACTUAL_QTY, totalAcQty)
                        contentValue.put(KEY_REMAINING_QTY, totalQty)
                        contentValue.put(KEY_IS_DELETE, "0")
                        db.update(
                            TABLE_VANSTOCK,
                            contentValue,
                            "$KEY_ITEM_ID = ?",
                            arrayOf<String>(mLoad.itemId!!)
                        )
                    } else {
                        //var existQty = getVanStockItemQty(mLoad.itemId!!).toDouble()
                        //var arrExpData = getBatchVanStockItem(mLoad.itemId!!)
                        val contentValue = ContentValues()
                        contentValue.put(KEY_ITEM_ID, mLoad.itemId.toString())
                        contentValue.put(KEY_ITEM_CODE, mLoad.itemCode)
                        contentValue.put(KEY_ITEM_NAME, mLoad.itemName)
                        contentValue.put(KEY_UOM_ID, mLoad.itemUom)
                        contentValue.put(KEY_UOM_NAME, mLoad.uomName)
                        contentValue.put(KEY_ACTUAL_QTY, mLoad.loadQty)
                        contentValue.put(KEY_REMAINING_QTY, mLoad.loadQty)
                        contentValue.put(KEY_DISPLAY_UNIT, mLoad.displayUomId)
                        contentValue.put(KEY_DISPLAY_UNIT_NAME, mLoad.displayUOMName)
                        contentValue.put(KEY_BATCH, "")
                        contentValue.put(KEY_IS_DELETE, "0")
                        contentValue.put(KEY_IS_RE_ITEM, "0")
                        contentValue.put(KEY_WH_QTY, mLoad.warehouseApproveQty)
                        contentValue.put(KEY_SP_QTY, mLoad.superviserApproveQty)
                        contentValue.put(KEY_VARIANCE_QTY, mLoad.varianceQty)

                        db.insert(TABLE_VANSTOCK, null, contentValue)

                    }
                }
            }

            db.setTransactionSuccessful()
        } finally {
            db.endTransaction();
        }
    }

