    fun updateGoodReSalesItemVanStock(mUom: UomData) {
        val db = this.writableDatabase

        var existQty = getVanStockReSaleItemQty(mUom.itemId!!).toDouble()
        var actualQty = getVanStockReSaleActualItemQty(mUom.itemId!!).toDouble()

        val mLowerId = getItemLowerUnit(mUom.itemId)

        var itemQty = 0.0
        if (mUom.uomId == mLowerId) {
            itemQty = mUom.uomQty.toDouble()
        } else {
            itemQty =
                Utils.getUOMLowerQty(mUom.uomUPC, mUom.uomQty).toDouble()
        }

        var totalQty = existQty + itemQty
        var totalAcQty = actualQty + itemQty

        val contentValue = ContentValues()
        contentValue.put(KEY_ACTUAL_QTY, totalAcQty)
        contentValue.put(KEY_REMAINING_QTY, totalQty)
        contentValue.put(KEY_IS_DELETE, "0")
        db.update(
            TABLE_VANSTOCK,
            contentValue,
            "$KEY_ITEM_ID = ? AND $KEY_IS_RE_ITEM = ?",
            arrayOf<String>(mUom.itemId!!, "1")
        )

    }

    fun updateGoodReSalesReturnItemVanStock(
        mUom: UomData,
        orderItemsBatchList_Return: ArrayList<CustomerItemReturnData.DataCustomerItemReturn>?
    ) {
        val db = this.writableDatabase

        var existQty = getVanStockReSaleItemQty(mUom.itemId!!).toDouble()
        var actualQty = getVanStockReSaleActualItemQty(mUom.itemId!!).toDouble()

        val mLowerId = getItemLowerUnit(mUom.itemId)

        var itemQty = 0.0
        if (mUom.uomId == mLowerId) {
            itemQty = mUom.uomQty.toDouble()
        } else {
            itemQty =
                Utils.getUOMLowerQty(mUom.uomUPC, mUom.uomQty).toDouble()
        }

        var totalQty = existQty + itemQty
        var totalAcQty = actualQty + itemQty

        val contentValue = ContentValues()
        contentValue.put(KEY_ACTUAL_QTY, totalAcQty)
        contentValue.put(KEY_REMAINING_QTY, totalQty)
        contentValue.put(KEY_IS_DELETE, "0")
        db.update(
            TABLE_VANSTOCK,
            contentValue,
            "$KEY_ITEM_ID = ? AND $KEY_IS_RE_ITEM = ?",
            arrayOf<String>(mUom.itemId!!, "1")
        )

        for (mLoadBatch in orderItemsBatchList_Return!!) {
            val contentValueItemBactch = ContentValues()
            contentValueItemBactch.put(KEY_ITEM_ID, mUom.itemId.toString())
            contentValueItemBactch.put(KEY_BATCH_ID, "")
            contentValueItemBactch.put(
                KEY_BATCH_NO,
                mLoadBatch.lot_no.toString()
            )
            contentValueItemBactch.put(KEY_BATCH_EXPIRY, mLoadBatch.expiry_date)

            if (mLoadBatch.qty != null) {
                contentValueItemBactch.put(KEY_BATCH_QTY, mLoadBatch.qty)
            } else {
                contentValueItemBactch.put(KEY_BATCH_QTY, "0")
            }
            db.insert(TABLE_VANSTOCK_BATCH_ITEM, null, contentValueItemBactch)

        }

    }

    fun updateGoodItemVanStock(mUom: UomData) {
        val db = this.writableDatabase

        var existQty = getVanStockItemQty(mUom.itemId!!).toDouble()
        var actualQty = getVanStockActualQty(mUom.itemId!!).toDouble()

        val mLowerId = getItemLowerUnit(mUom.itemId)

        var itemQty = 0.0
        if (mUom.uomId == mLowerId) {
            itemQty = mUom.uomQty.toDouble()
        } else {
            itemQty =
                Utils.getUOMLowerQty(mUom.uomUPC, mUom.uomQty).toDouble()
        }

        var totalQty = existQty + itemQty
        var totalAcQty = actualQty + itemQty

        val contentValue = ContentValues()
        contentValue.put(KEY_ACTUAL_QTY, totalAcQty)
        contentValue.put(KEY_REMAINING_QTY, totalQty)
