    fun getVanStockItemQty(materialNo: String, uomId: String, type: String): String {
        var qty = "0"
        val db = this.readableDatabase
        try {
            val cursor = db.rawQuery(
                ("SELECT * FROM " +
                        TABLE_VANSTOCK + " WHERE " +
                        KEY_ITEM_ID + "=? AND " + KEY_IS_RE_ITEM + "=?"),
                arrayOf<String>(materialNo, "0")
            )
            cursor.moveToFirst()
            val count = cursor.count
            if (count > 0) {
                if (type == "Remaining")
                    qty = cursor.getString(cursor.getColumnIndex(KEY_REMAINING_QTY))
                else
                    qty = cursor.getString(cursor.getColumnIndex(KEY_ACTUAL_QTY))
            }
            cursor.close()
        } catch (e: Exception) {
            e.printStackTrace()
        }

        return qty
    }


