    //Get Vanstock Items
    fun getAllVanStockItemList(): ArrayList<Item> {
        val arrData: ArrayList<Item> = ArrayList()
        val db = this.readableDatabase
        try {
            val cursor = db.rawQuery(
                ("SELECT * FROM " +
                        TABLE_VANSTOCK + " WHERE " +
                        KEY_IS_DELETE + "=?"), arrayOf<String>("0")
            )
            // looping through all rows and adding to list
            try {
                if (cursor.moveToFirst()) {
                    do {
                        val item = Item()
                        item.itemId = cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID))
                        item.itemCode = cursor.getString(cursor.getColumnIndex(KEY_ITEM_CODE))
                        item.itemName = cursor.getString(cursor.getColumnIndex(KEY_ITEM_NAME))
                        item.itemUOMName = cursor.getString(cursor.getColumnIndex(KEY_UOM_NAME))
                        item.itemUOMId = cursor.getString(cursor.getColumnIndex(KEY_UOM_ID))
                        item.itemIsReSale =
                            cursor.getString(cursor.getColumnIndex(KEY_IS_RE_ITEM))
                        item.itemDisplayUnitId = cursor.getString(
                            cursor.getColumnIndex(
                                KEY_DISPLAY_UNIT
                            )
                        )
                        item.itemDisplayUnitName = cursor.getString(
                            cursor.getColumnIndex(
                                KEY_DISPLAY_UNIT_NAME
                            )
                        )
                        item.itemDisplayUPC = getItemUOMUPC(
                            cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID)),
                            cursor.getString(cursor.getColumnIndex(KEY_DISPLAY_UNIT))
                        )
                        item.itemUOMUPC = getItemUOMUPC(
                            cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID)),
                            cursor.getString(cursor.getColumnIndex(KEY_UOM_ID))
                        )
                        val mItemData =
                            getItemDetail(cursor.getString(cursor.getColumnIndex(KEY_ITEM_CODE)))
                        if (mItemData != null) {
                            item.itemCatId = mItemData!!.majorCategory.toString()
                        } else {
                            item.itemCatId = "3"
                        }


                        if (cursor.getString(cursor.getColumnIndex(KEY_REMAINING_QTY)) != null) {
                            item.itemQty = cursor.getString(
                                cursor.getColumnIndex(
                                    KEY_REMAINING_QTY
                                )
                            )
                        } else {
                            item.itemQty = "0"
                        }
                        if (cursor.getString(cursor.getColumnIndex(KEY_WH_QTY)) != null) {
                            item.itemWHQty = cursor.getString(
                                cursor.getColumnIndex(
                                    KEY_WH_QTY
                                )
                            )
                        } else {
                            item.itemWHQty = "0"
                        }

                        if (cursor.getString(cursor.getColumnIndex(KEY_SP_QTY)) != null) {
                            item.itemSPQty = cursor.getString(
                                cursor.getColumnIndex(
                                    KEY_SP_QTY
                                )
                            )
                        } else {
                            item.itemSPQty = "0"
                        }

                        if (cursor.getString(cursor.getColumnIndex(KEY_VARIANCE_QTY)) != null) {
                            item.itemVarianceQty = cursor.getString(
                                cursor.getColumnIndex(
                                    KEY_VARIANCE_QTY
                                )
                            )
                        } else {
                            item.itemVarianceQty = "0"
                        }

                        if (item.itemQty!!.toFloat() > 0)

                            arrData.add(item)
                    } while (cursor.moveToNext())
                }
            } finally {
                try {
                    db.close()
                } catch (ignore: Exception) {
                }
            }
        } finally {
            try {
                db.close()
            } catch (ignore: Exception) {
            }
        }
        return arrData
    }

