    fun getSaleItemQty(mItemId: String, isReSale: String): Double {
        var qty = 0.0

        val db = this.readableDatabase
        try {
            var cursor = db.rawQuery(
                ("SELECT * FROM " +
                        TABLE_INVOICE_ITEM + " WHERE " +
                        KEY_ITEM_ID + "=? AND " + KEY_IS_RE_ITEM + "=?"),
                arrayOf<String>(mItemId, isReSale)
            )
            if (cursor.moveToFirst()) {
                do {
                    qty += cursor.getString(cursor.getColumnIndex(KEY_LOWER_QTY)).toDouble()
                } while (cursor.moveToNext())
            }
            cursor.close()
        } catch (e: Exception) {
            e.printStackTrace()
        }

        return qty
    }

