    fun getDeliveryOrderDetail(mItemId: String): HashMap<String, String> {
        var name: HashMap<String, String> = HashMap<String, String>()

        val db = this.readableDatabase
        try {
            var cursor = db.rawQuery(
                ("SELECT * FROM " +
                        TABLE_DELIVERY_HEADER + " WHERE " +
                        KEY_DELIVERY_ID + "=?"), arrayOf<String>(mItemId)
            )
            cursor.moveToFirst()
            val count = cursor.getCount()
            if (count > 0) {
                name.put("OrderNo", cursor.getString(cursor.getColumnIndex(KEY_ORDER_NO)))
                if (cursor.getString(cursor.getColumnIndex(LOB_ID)) != null) {
                    name.put("LPO", cursor.getString(cursor.getColumnIndex(LOB_ID)))
                } else {
                    name.put("LPO", "")
                }

                name.put("DeliveryDate", cursor.getString(cursor.getColumnIndex(KEY_DELVIERY_DATE)))
                name.put("PresellerCode", cursor.getString(cursor.getColumnIndex(KEY_SALESMAN_ID)))
                name.put("OrderSource", cursor.getString(cursor.getColumnIndex(KEY_ORDER_SOURCE)))
                name.put(
                    "PaymentMethod",
                    cursor.getString(cursor.getColumnIndex(KEY_ORDER_PAY_TYPE))
                )
                name.put(
                    "PaymentRefrence",
                    cursor.getString(cursor.getColumnIndex(KEY_PAYMENTSO_REF))
                )
                name.put(
                    "CardType",
                    cursor.getString(cursor.getColumnIndex(KEY_CARD_TYPE))
                )
                name.put(
                    "CardCharge",
                    cursor.getString(cursor.getColumnIndex(KEY_CARD_CHARGE))
                )

                if (cursor.getString(cursor.getColumnIndex(KEY_IS_DESPENCER_ORDER)) != null) {
                    name.put(
                        "isDispenser",
                        cursor.getString(cursor.getColumnIndex(KEY_IS_DESPENCER_ORDER))
                    )
                } else {
                    name.put(
                        "isDispenser",
                        cursor.getString(cursor.getColumnIndex(KEY_IS_DESPENCER_ORDER))
                    )
                }

                if (cursor.getString(cursor.getColumnIndex(KEY_OFFER_TYPE)) != null) {
                    name.put(
                        "offer_type",
                        cursor.getString(cursor.getColumnIndex(KEY_OFFER_TYPE))
                    )
                } else {
                    name.put(
                        "offer_type",
                       ""
                    )
                }

                if (cursor.getString(cursor.getColumnIndex(KEY_OFFER_VALUE)) != null) {
                    name.put(
                        "offer_value",
                        cursor.getString(cursor.getColumnIndex(KEY_OFFER_VALUE))
                    )
                } else {
                    name.put(
                        "offer_value",
                        ""
                    )
                }

                if (cursor.getString(cursor.getColumnIndex(KEY_OFFER_NAME)) != null) {
                    name.put(
                        "offer_name",
                        cursor.getString(cursor.getColumnIndex(KEY_OFFER_NAME))
                    )
                } else {
                    name.put(
                        "offer_name",
                        ""
                    )
                }

                if (cursor.getString(cursor.getColumnIndex(KEY_IS_ICASH)) != null) {
                    name.put(
                        "is_icash",
                        cursor.getString(cursor.getColumnIndex(KEY_IS_ICASH))
                    )
                } else {
                    name.put(
                        "is_icash",
                        "No"
                    )
                }

                if (cursor.getString(cursor.getColumnIndex(KEY_ICASH_AMOUNT)) != null) {
                    name.put(
                        "icash_amount",
                        cursor.getString(cursor.getColumnIndex(KEY_ICASH_AMOUNT))
                    )
                } else {
                    name.put(
                        "icash_amount",
                        "0.0"
                    )
                }

                name.put(
                    "PresellerName", cursor.getString(
                        cursor.getColumnIndex(
                            KEY_SALESMAN_USERNAME
                        )
                    )
                )
            }

            cursor.close()
        } catch (e: Exception) {
            e.printStackTrace()
        }

        return name
    }

