    fun getCouponId(mItemId: String, mFrom: String, mTo: String): String {
        var name: String = ""

        val db = this.readableDatabase
        try {
            var cursor = db.rawQuery(
                ("SELECT * FROM " +
                        TABLE_COUPON_STOCK + " WHERE " +
                        KEY_ITEM_ID + "=?"),
                arrayOf<String>(mItemId)
            )
            Log.e("Count", cursor.count.toString())
            if (cursor.moveToFirst()) {
                do {
                    var mCFrom = cursor.getString(cursor.getColumnIndex(KEY_FROM_SERIAL))
                    var mCTo = cursor.getString(cursor.getColumnIndex(KEY_TO_SERIAL))

                    if ((mCFrom == mFrom) && (mCTo == mTo)) {
                        name = cursor.getString(cursor.getColumnIndex(KEY_COUPON_ID))
                    }
                } while (cursor.moveToNext())
            }
            cursor.close()
        } catch (e: Exception) {
            e.printStackTrace()
        }

        return name
    }

