        val db = this.readableDatabase

        try {
            val cursor = db.rawQuery(
                "SELECT * FROM $TABLE_VISITED_CUSTOMER WHERE $KEY_CUSTOMER_ID = '$mItemId' AND $KEY_IS_SEQUENCE = '$isSeq'",
                null
            )

            if (cursor.count > 0) {
                isExist = true
            }
            cursor.close()
        } catch (e: Exception) {
            e.printStackTrace()
        }

        return isExist
    }

