    fun getItemUOMSPPrice(
        mItemId: String,
        mCust: String,
        mUOMId: String,
        mLobId: String,
        mPrice: String
    ): String {
        var mSpPrice = "0"
        if (isPriceCUst(
                mItemId,
                mCust,
                mUOMId
            )
            > 0
        ) {
            mSpPrice = getCustomerPrice(
                mItemId,
                mCust,
                mUOMId
            )

        } else {

            var mCUstDetail = getCustomerDetailFromCustId(mCust)

            if (mLobId.isNotEmpty()) {
                var mLobDetail =
                    getCustomerLob(mLobId, mCUstDetail!!.user_id.toString())

                if (mLobDetail != null) {
                    var mRegion = mLobDetail!!.region_id.toString()
                    var mSalesOrg = mLobDetail!!.sales_organisation_id!!.toString()
                    var mChannel = mLobDetail!!.channel_id.toString()
                    var mCategory = mLobDetail!!.customer_category_id.toString()
                    var mRoute = mLobDetail!!.route_id.toString()

                    mSpPrice = getOtherPricePDP(
                        mItemId,
                        mUOMId,
                        mRegion, mSalesOrg, mChannel, mCategory, mRoute
                    )
                }
            } else {
                if (mCUstDetail != null) {
                    var mRegion = mCUstDetail!!.region_id.toString()
                    var mSalesOrg = mCUstDetail!!.sales_organisation_id!!
                    var mChannel = mCUstDetail!!.channel_id
                    var mCategory = mCUstDetail!!.customer_category_id.toString()
                    var mRoute = mCUstDetail!!.route_id.toString()

                    mSpPrice = getOtherPricePDP(
                        mItemId,
                        mUOMId,
                        mRegion, mSalesOrg, mChannel, mCategory, mRoute
                    )
                }
            }

        }

        if (mSpPrice == "0") {
            mSpPrice = getItemSp1Price(
                mItemId,
                mUOMId
            )
        }

        if (mSpPrice == "0") {
            mSpPrice = mPrice
        }

        return mSpPrice
    }

    fun getDailyFeildList(): ArrayList<DailyFeildRequestModel.Customer> {
        var datalist: ArrayList<DailyFeildRequestModel.Customer>? = ArrayList()
        val db = this.readableDatabase
        try {
            var cursor = db.rawQuery(
                ("SELECT * FROM " +
                        TABLE_DAILY_FEILD),
                null
            )
            Log.e("dailycount", cursor.getCount().toString())

            if (cursor.moveToFirst()) {
                do {
                    var data = DailyFeildRequestModel.Customer()

                    data!!.shelfDisplay =
                        cursor.getString(cursor.getColumnIndex(KEY_SHELF_DISPLAY))
                    data!!.offShelfDisplay =
                        cursor.getString(cursor.getColumnIndex(KEY_OFF_SHELF_DISPLAY))
                    data!!.opportunity =
                        cursor.getString(cursor.getColumnIndex(KEY_OPPERTUNITE))
                    data!!.outOfStock =
                        cursor.getString(cursor.getColumnIndex(KEY_IS_DAILY_FEILD_CREATEED))
                    data!!.remarks = cursor.getString(cursor.getColumnIndex(KEY_ROUTE_ID))
                    data!!.customerId =
                        cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_ID)).toInt()
                    datalist!!.add(data)
                } while (cursor.moveToNext())
            }

        } finally {
            try {
                db.close()
            } catch (ignore: Exception) {
            }
        }
        return datalist!!
    }

