    //GET Invoice Posted
    fun getInvoicePosted(invoiceNo: String): Boolean {
        var isPosted = false
        val db = this.readableDatabase
        try {
            val cursor = db.rawQuery(
                ("SELECT * FROM " +
                        TABLE_TRANSACTION + " WHERE " +
                        TR_INVOICE_ID + "=?" + " AND "
                        + TR_IS_POSTED + "=?"), arrayOf<String>(invoiceNo, "Yes")
            )
            cursor.moveToFirst()
            if (cursor.getCount() > 0) {
                isPosted = true
            }
            cursor.close()
        } catch (e: Exception) {
            e.printStackTrace()
        }
        return isPosted
    }

    //Update Collection Post
    fun updateCollectionPost(orderNo: String, status: String): Int {
        val contentValues = ContentValues()
        if (status.equals("1", ignoreCase = true)) {
            contentValues.put(DATA_MARK_FOR_POST, "Y")
        } else {
            contentValues.put(DATA_MARK_FOR_POST, "E")
        }
        val db = this.writableDatabase
        val i = db.update(
            TABLE_COLLECTION,
            contentValues, "$KEY_ORDER_ID = ? ", arrayOf<String>(orderNo)
        )

        val iR = db.update(
            TABLE_COLLECTION_HEADER,
            contentValues, "$KEY_ORDER_ID = ? ", arrayOf<String>(orderNo)
        )
        return i
    }


    //Update COLLECTION Order
    fun updateCollectionTransaction(collectionNo: String, type: String, message: String): Int {
        val db = this.writableDatabase
        val contentValue = ContentValues()
        if (type.equals("2", ignoreCase = true)) {
            contentValue.put(TR_IS_POSTED, "Fail")
            contentValue.put(TR_MESSAGE, message)
        } else {
            contentValue.put(TR_IS_POSTED, "Yes")
        }
        val i = db.update(
            TABLE_TRANSACTION, contentValue,
            "$TR_COLLECTION_ID = ?", arrayOf<String>(collectionNo)
        )
        return i
    }

    fun getCustomerCollection(mCustomerCode: String): ArrayList<OutstandingData.CollectionData> {
        var mList: ArrayList<OutstandingData.CollectionData> = ArrayList()

        val db = this.readableDatabase

        var cursor = db.rawQuery(
            ("SELECT * FROM " +
                    TABLE_COLLECTION + " WHERE " +
                    KEY_CUSTOMER_CODE + "=?"), arrayOf<String>(mCustomerCode)
        )

        try {
            if (cursor.moveToFirst()) {
                do {

                    var pendingAmnt = 0F
                    if (cursor.getString(cursor.getColumnIndex(KEY_PENDING_AMOUNT)) != null) {
                        pendingAmnt = Utils.twoDigit(
                            cursor.getString(cursor.getColumnIndex(KEY_PENDING_AMOUNT))
                                .toFloat()
                        )
                    } else {
                        pendingAmnt = Utils.twoDigit(
                            cursor.getString(cursor.getColumnIndex(KEY_INVOICE_AMOUNT))
                                .toFloat()
                        )
                    }


//                    var pendingAmnt = String.format(
//                        "%.2f",
//                        (cursor.getString(cursor.getColumnIndex(KEY_INVOICE_AMOUNT)).toDouble() -
//                                cursor.getString(cursor.getColumnIndex(KEY_AMOUNT_CLEARED))
//                                    .toDouble())
//                    )

                    val mCollection = OutstandingData.CollectionData(
                        cursor.getString(cursor.getColumnIndex(KEY_INVOICE_ID)),
                        cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_CODE)),
                        cursor.getString(cursor.getColumnIndex(KEY_INVOICE_NO)),
                        cursor.getString(cursor.getColumnIndex(KEY_INVOICE_DATE)),
                        cursor.getString(cursor.getColumnIndex(KEY_DUE_DATE)),
                        cursor.getString(cursor.getColumnIndex(KEY_INVOICE_AMOUNT)),
                        pendingAmnt.toString(),
                        cursor.getString(cursor.getColumnIndex(KEY_AMOUNT_PAY)),
                        cursor.getString(cursor.getColumnIndex(KEY_OUTSTANDING)),
                        false,
                        false,
                        pendingAmnt.toString(),
                        "0",
                        "",
                        "",
                        "",
                        cursor.getString(cursor.getColumnIndex(LOB_ID)),
                        cursor.getString(cursor.getColumnIndex(KEY_CUS_GROUP_ID)),
                        cursor.getString(cursor.getColumnIndex(KEY_FIRST_NAME)),
                        cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_ID)),
                        cursor.getString(cursor.getColumnIndex(KEY_TYPE)),
                        cursor.getString(cursor.getColumnIndex(KEY_OVERDUE_DAYS)),
                        cursor.getString(cursor.getColumnIndex(IS_OVERDUE)),
                        cursor.getString(cursor.getColumnIndex(KEY_PDC_AMOUNT)),
                        cursor.getString(cursor.getColumnIndex(KEY_NET_AMOUNT)),
                        cursor.getString(cursor.getColumnIndex(KEY_VAT_AMOUNT)),
                        cursor.getString(cursor.getColumnIndex(KEY_DEBIT_TYPE))
                    )

                    if (pendingAmnt > 0) {
                        mList.add(mCollection)
                    }
                } while (cursor.moveToNext())
            }
        } finally {
            try {
                db.close()
            } catch (ignore: Exception) {
            }
        }

        return mList
    }

