    fun getAllFinalDepositeCollection(): ArrayList<DepositeSummary> {
        var mList: ArrayList<DepositeSummary> = ArrayList()

        val db = this.readableDatabase

        var cursor = db.rawQuery(
            ("SELECT * FROM " +
                    TABLE_COLLECTION_HEADER), null
        )

        try {
            if (cursor.moveToFirst()) {
                do {

                    var mDeposite = DepositeSummary()
                    mDeposite.invoiceNo =
                        ""
                    mDeposite.ivvoiceDate = ""
                    mDeposite.customerCode =
                        getCustomerCode(
                            cursor.getString(
                                cursor.getColumnIndex(
                                    KEY_CUSTOMER_CODE
                                )
                            )
                        )
                    mDeposite.customerName = getCustomeName(
                        cursor.getString(
                            cursor.getColumnIndex(KEY_CUSTOMER_CODE)
                        )
                    )
                    mDeposite.collectionType = cursor.getString(
                        cursor.getColumnIndex(
                            KEY_COLLECTION_TYPE
                        )
                    )
                    mDeposite.chequeNo = cursor.getString(
                        cursor.getColumnIndex(
                            KEY_CHEQUE_NUMBER
                        )
                    )
                    mDeposite.chequeDate = cursor.getString(
                        cursor.getColumnIndex(
                            KEY_CHEQUE_DATE
                        )
                    )
                    mDeposite.collectionNo = cursor.getString(
                        cursor.getColumnIndex(
                            KEY_ORDER_ID
                        )
                    )

                    var Amount = "0.0"
                    if (cursor.getString(cursor.getColumnIndex(KEY_ORDER_AMOUNT)) != null) {
                        mDeposite.amountPaid = Utils.twoDigit(
                            (cursor.getString(
                                cursor.getColumnIndex(
                                    KEY_ORDER_AMOUNT
                                )
                            )).toFloat()
                        ).toString()
                        Amount = Utils.twoDigit(
                            (cursor.getString(
                                cursor.getColumnIndex(
                                    KEY_ORDER_AMOUNT
                                )
                            )).toFloat()
                        ).toString()
                    } else {
                        mDeposite.amountPaid = "0.0"
                    }


                    if (cursor.getString(cursor.getColumnIndex(KEY_INVOICE_NO)) != null) {
                        var isExchange = false
                        if (cursor.getString(cursor.getColumnIndex(KEY_INVOICE_NO)).isEmpty()) {
                            isExchange = false
                        } else {
                            isExchange = checkIsExchangeInvoice(
                                cursor.getString(
                                    cursor.getColumnIndex(KEY_INVOICE_NO)
                                )
                            )
                        }
                        if (!isExchange) {
                            if (Amount.toDouble() > 0) {
                                mList.add(mDeposite)
                            }
                        }
                    } else {
                        if (Amount.toDouble() > 0) {
                            mList.add(mDeposite)
                        }
                    }

                } while (cursor.moveToNext())
            }
        } finally {
            try {
                db.close()
            } catch (ignore: Exception) {
            }
        }

        return mList
    }

