    fun getOverDueInvoice(mDate: String): ArrayList<OverDueInvoice> {
        var mList: ArrayList<OverDueInvoice> = ArrayList()

        val db = this.readableDatabase

        var cursor = db.rawQuery(
            ("SELECT * FROM " +
                    TABLE_COLLECTION + " WHERE " +
                    KEY_DUE_DATE + "<=?"), arrayOf<String>(mDate)
        )

        try {
            if (cursor.moveToFirst()) {
                do {
                    var pendingAmnt =
                        cursor.getString(cursor.getColumnIndex(KEY_INVOICE_AMOUNT)).toDouble() -
                                cursor.getString(cursor.getColumnIndex(KEY_AMOUNT_CLEARED))
                                    .toDouble()
                    var mInoivce = OverDueInvoice()
                    mInoivce.invoiceNo = cursor.getString(cursor.getColumnIndex(KEY_INVOICE_NO))
                    mInoivce.customerId =
                        cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_CODE))
                    mInoivce.amountDue = pendingAmnt.toString()
                    mInoivce.invoiceDueDate =
                        cursor.getString(cursor.getColumnIndex(KEY_DUE_DATE))
                    mInoivce.customerName =
                        getCustomeName(cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_CODE)))

                    mList.add(mInoivce)
                } while (cursor.moveToNext())
            }
        } finally {
            try {
                db.close()
            } catch (ignore: Exception) {
            }
        }

        return mList
    }

