        mCategory: String,
        mBrand: String,
        mGroup: String
    ): ArrayList<ItemData.Data> {
        var mList: ArrayList<ItemData.Data> = ArrayList()

        val db = this.readableDatabase
        var cursor: Cursor? = null

        if (mCategory.isNotEmpty() && mBrand.isNotEmpty() && mGroup.isNotEmpty()) {
            cursor = db.query(
                TABLE_ITEM,
                arrayOf<String>(),
                (KEY_ITEM_MAJOR_CATEGORY + " IN (" + mCategory + ")" + " AND " + KEY_ITEM_GROUP + " IN (" + mGroup + ")"
                        + " AND " + KEY_ITEM_BRAND + " IN (" + mBrand + ")"),
                null,
                null,
                null,
                null
            )
        } else if (mCategory.isNotEmpty() && mBrand.isNotEmpty()) {
            cursor = db.query(
                TABLE_ITEM,
                arrayOf<String>(),
                ("$KEY_ITEM_MAJOR_CATEGORY IN ($mCategory) AND $KEY_ITEM_BRAND IN ($mBrand)"),
                null,
                null,
                null,
                null
            )
        } else if (mCategory.isNotEmpty() && mGroup.isNotEmpty()) {
            cursor = db.query(
                TABLE_ITEM,
                arrayOf<String>(),
                ("$KEY_ITEM_MAJOR_CATEGORY IN ($mCategory) AND $KEY_ITEM_GROUP IN ($mGroup)"),
                null,
                null,
                null,
                null
            )
        } else if (mBrand.isNotEmpty() && mGroup.isNotEmpty()) {
            cursor = db.query(
                TABLE_ITEM,
                arrayOf<String>(),
                ("$KEY_ITEM_BRAND IN ($mBrand) AND $KEY_ITEM_GROUP IN ($mGroup)"),
                null,
                null,
                null,
                null
            )
        } else if (mGroup.isNotEmpty()) {
            cursor = db.query(
                TABLE_ITEM,
                arrayOf<String>(),
                ("$KEY_ITEM_GROUP IN ($mGroup)"),
                null,
                null,
                null,
                null
            )
        } else if (mCategory.isNotEmpty()) {
            cursor = db.query(
                TABLE_ITEM,
                arrayOf<String>(),
                ("$KEY_ITEM_MAJOR_CATEGORY IN ($mCategory)"),
                null,
                null,
                null,
                null
            )
        } else if (mBrand.isNotEmpty()) {
            cursor = db.query(
                TABLE_ITEM,
                arrayOf<String>(),
                ("$KEY_ITEM_BRAND IN ($mBrand)"),
                null,
                null,
                null,
                null
            )
        } else {
            cursor = db.rawQuery(
                ("SELECT * FROM " +
                        TABLE_ITEM), null
            )
        }

        try {
            if (cursor!!.moveToFirst()) {
                do {
                    val mLowerUOM =
                        getLowerUOM(
                            cursor.getString(cursor.getColumnIndex(KEY_ITEM_LOWER_UNIT)),
                            cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID))
                        )

                    val mUOMList =
                        getItemUOM(cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID)))

                    val mItem = ItemData.Data(
                        cursor.getString(cursor.getColumnIndex(KEY_ITEM_MAJOR_CATEGORY))
                            .toInt(),
                        cursor.getString(cursor.getColumnIndex(KEY_ITEM_GROUP)).toInt(),
                        cursor.getString(cursor.getColumnIndex(KEY_ITEM_BRAND)).toInt(),
                        cursor.getString(cursor.getColumnIndex(KEY_ITEM_CODE)),
                        cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID)).toInt(),
                        cursor.getString(cursor.getColumnIndex(KEY_ITEM_NAME)),
                        "",
                        "",
                        "",
                        mLowerUOM!!.uomUPC,
                        mLowerUOM!!.uomId,
                        mLowerUOM!!.uomPrice,
                        cursor.getString(cursor.getColumnIndex(KEY_ITEM_TAX_APPLY)),
                        cursor.getString(cursor.getColumnIndex(KEY_ITEM_VAT_PERC)),
                        null,
                        mUOMList,
                        emptyList(),
                        emptyList(),
                        null,
                        null, null, "", "", ""
                    )

                    mList.add(mItem)
                } while (cursor.moveToNext())
            }
        } finally {
            try {
                db.close()
            } catch (ignore: Exception) {
            }
        }

        return mList
    }

