    fun getOverDueCustomer(): ArrayList<CustomerData.DataCustomer> {
        var mList: ArrayList<CustomerData.DataCustomer> = ArrayList()

        val db = this.readableDatabase

        var cursor = db.rawQuery(
            ("SELECT * FROM " +
                    TABLE_CUSTOMER + " WHERE " +
                    IS_OVERDUE + "=? OR " + IS_OVERDUE + "=?"), arrayOf<String>("1", "2")
        )

        try {
            if (cursor.moveToFirst()) {
                do {

                    var days = ""
                    var limit = ""
                    var customerType = ""

                    if (cursor.getString(cursor.getColumnIndex(KEY_ISLOB)) == "1") {

                        if (cursor.getString(cursor.getColumnIndex(KEY_CREDIT_DAYS)) != null) {
                            days = cursor.getString(cursor.getColumnIndex(KEY_CREDIT_DAYS))
                        } else {
                            days = "0"
                        }

                        if (cursor.getString(cursor.getColumnIndex(KEY_CREDIT_LIMIT)) != null) {
                            limit =
                                cursor.getString(cursor.getColumnIndex(KEY_CREDIT_LIMIT))
                        } else {
                            limit = "0"
                        }

                        if (cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_TYPE_ID)) == null) {
                            customerType = "2"
                        } else {
                            customerType =
                                cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_TYPE_ID))
                        }

                    } else {

                        if (cursor.getString(cursor.getColumnIndex(KEY_CREDIT_DAYS)) != null) {
                            days = cursor.getString(cursor.getColumnIndex(KEY_CREDIT_DAYS))
                        } else {
                            days = "0"
                        }

                        if (cursor.getString(cursor.getColumnIndex(KEY_CREDIT_LIMIT)) != null) {
                            limit = cursor.getString(cursor.getColumnIndex(KEY_CREDIT_LIMIT))
                        } else {
                            limit = "0"
                        }

                        if (cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_TYPE_ID)) == null) {
                            customerType = "2"
                        } else {
                            customerType =
                                cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_TYPE_ID))
                        }

                    }

                    val mData = CustomerData.DataCustomer(
                        cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_ID)).toInt(),
                        cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_ID)).toInt(),
                        cursor.getString(cursor.getColumnIndex(KEY_REGION_ID)).toInt(),
                        cursor.getString(cursor.getColumnIndex(KEY_ROUTE_ID)),
                        cursor.getString(cursor.getColumnIndex(KEY_PAYMENT_TERM_ID)).toInt(),
                        customerType,
                        cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_CATEGORY_ID)),
                        "",
                        cursor.getString(cursor.getColumnIndex(KEY_SALES_ORG_ID)),
                        cursor.getString(cursor.getColumnIndex(KEY_SUB_CHANNEL_ID)),
                        cursor.getString(cursor.getColumnIndex(KEY_CHANNEL_ID)),
                        cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_CODE)),
                        if (cursor.getString(cursor.getColumnIndex(KEY_ADDRESS_1)) != null) cursor.getString(
                            cursor.getColumnIndex(KEY_ADDRESS_1)
                        ) else "",
                        if (cursor.getString(cursor.getColumnIndex(KEY_ADDRESS_2)) != null) cursor.getString(
                            cursor.getColumnIndex(KEY_ADDRESS_2)
                        ) else "",

                        cursor.getString(cursor.getColumnIndex(KEY_CITY)),
                        cursor.getString(cursor.getColumnIndex(KEY_STATE)),
                        cursor.getString(cursor.getColumnIndex(KEY_ZIPCODE)),
                        cursor.getString(cursor.getColumnIndex(KEY_PHONE)),
                        limit,
                        days,
                        CustomerData.DataCustomer.UserDetail(
                            cursor.getString(
                                cursor.getColumnIndex(
                                    KEY_FIRST_NAME
                                )
                            ),
                            if (cursor.getString(cursor.getColumnIndex(KEY_LAST_NAME)) != null) cursor.getString(
                                cursor.getColumnIndex(KEY_LAST_NAME)
                            ) else "",
                            cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_ID)).toInt(),
                            cursor.getString(cursor.getColumnIndex(KEY_EMAIL))
                        ),
                        cursor.getString(cursor.getColumnIndex(CUST_SALE)),
                        cursor.getString(cursor.getColumnIndex(CUST_DELVIERY)),
                        cursor.getString(cursor.getColumnIndex(CUST_DELVIERY)),
                        cursor.getString(cursor.getColumnIndex(CUST_ORDER)),
                        cursor.getString(cursor.getColumnIndex(CUST_RETURN)),
                        cursor.getString(cursor.getColumnIndex(CUST_COLL)),
                        cursor.getString(cursor.getColumnIndex(CUST_MERCHAN)),
                        cursor.getString(cursor.getColumnIndex(KEY_LATITUDE)),
                        cursor.getString(cursor.getColumnIndex(KEY_LONGITUDE)),
                        cursor.getString(cursor.getColumnIndex(KEY_ISLOB)).toInt(),
                        cursor.getString(cursor.getColumnIndex(KEY_SALESENABLE)),
                        cursor.getString(cursor.getColumnIndex(KEY_RETURNENABLE)),
                        cursor.getString(cursor.getColumnIndex(KEY_COLLECTIONENABLE)),
                        cursor.getString(cursor.getColumnIndex(KEY_PRINTENABLE)),
                        cursor.getString(cursor.getColumnIndex(IS_OVERDUE)),
                        if (cursor.getString(cursor.getColumnIndex(KEY_PLAN_SEQ)) != null) cursor.getString(
                            cursor.getColumnIndex(KEY_PLAN_SEQ)
                        ) else "1"
                    )
                    mList.add(mData)
                } while (cursor.moveToNext())
            }
        } finally {
            try {
                db.close()
            } catch (ignore: Exception) {
            }
        }

        return mList
    }

    fun getAllCustomer(mLobList: String): ArrayList<CustomerData.DataCustomer> {
        var mList: ArrayList<CustomerData.DataCustomer> = ArrayList()

        val db = this.readableDatabase

        var cursor = db.rawQuery(
            ("SELECT * FROM " +
                    TABLE_CUSTOMER), null
        )

        try {
            if (cursor.moveToFirst()) {
                do {

                    var days = ""
                    var limit = ""
                    var customerType = ""

                    if (cursor.getString(cursor.getColumnIndex(KEY_ISLOB)) == "1") {

                        if (mLobList!!.isNotEmpty()) {
                            var lobobj = getCustomerLob(
                                mLobList!!,
                                cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_ID))
                            )

                            if (lobobj != null) {
                                days = lobobj!!.credit_days.toString()
                                limit = lobobj!!.credit_limit
                                customerType = lobobj!!.customer_type_id.toString()
                                if (customerType.toString() == "2") {
                                    days = "0"
                                    limit = "0.0"
                                }
                            } else {
                                if (cursor.getString(cursor.getColumnIndex(KEY_CREDIT_DAYS)) != null) {
                                    days =
                                        cursor.getString(cursor.getColumnIndex(KEY_CREDIT_DAYS))
                                } else {
                                    days = "0"
                                }

                                if (cursor.getString(cursor.getColumnIndex(KEY_CREDIT_LIMIT)) != null) {
                                    limit =
                                        cursor.getString(cursor.getColumnIndex(KEY_CREDIT_LIMIT))
                                } else {
                                    limit = "0"
                                }

                                if (cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_TYPE_ID)) == null) {
                                    customerType = "1"
                                } else {
                                    customerType =
                                        cursor.getString(
                                            cursor.getColumnIndex(
                                                KEY_CUSTOMER_TYPE_ID
                                            )
                                        )
                                }
                            }
                        } else {
                            if (cursor.getString(cursor.getColumnIndex(KEY_CREDIT_DAYS)) != null) {
                                days = cursor.getString(cursor.getColumnIndex(KEY_CREDIT_DAYS))
                            } else {
                                days = "0"
                            }

                            if (cursor.getString(cursor.getColumnIndex(KEY_CREDIT_LIMIT)) != null) {
                                limit =
                                    cursor.getString(cursor.getColumnIndex(KEY_CREDIT_LIMIT))
                            } else {
                                limit = "0"
                            }

                            if (cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_TYPE_ID)) == null) {
