    fun getCustomerLob(lobid: String, mCustId: String): CustomerData.DataCustomer.Customerlob? {
        var mList: CustomerData.DataCustomer.Customerlob? = null

        val db = this.readableDatabase

        var cursor = db.rawQuery(
            ("SELECT * FROM " +
                    TABLE_CUSTOMER_LOB + " WHERE " +
                    LOB_ID + "=? AND " + KEY_CUSTOMER_ID + "=?"),
            arrayOf<String>(lobid, mCustId)
        )

        try {
            if (cursor.count > 0) {
                if (cursor.moveToFirst()) {
                    do {
                        val mData = CustomerData.DataCustomer.Customerlob(
                            cursor.getString(cursor.getColumnIndex(KEY_AMOUNT)).toInt(),
                            cursor.getString(cursor.getColumnIndex(BALANCE)),
                            cursor.getString(cursor.getColumnIndex(KEY_CHANNEL_ID)).toInt(),
                            "",
                            if (cursor.getString(cursor.getColumnIndex(KEY_CREDIT_DAYS)) != null) cursor.getString(
                                cursor.getColumnIndex(KEY_CREDIT_DAYS)
                            ).toInt()
                            else 0,
                            cursor.getString(cursor.getColumnIndex(KEY_CREDIT_LIMIT)),
                            if (cursor.getString(cursor.getColumnIndex(CUSTOMER_CATEGORY_ID)) != null) cursor.getString(
                                cursor.getColumnIndex(CUSTOMER_CATEGORY_ID)
                            ).toInt()
                            else 0,
                            if (cursor.getString(cursor.getColumnIndex(CUSTOMER_GROUP_ID)) != null) cursor.getString(
                                cursor.getColumnIndex(CUSTOMER_GROUP_ID)
                            ).toInt()
                            else 0,
                            cursor.getString(cursor.getColumnIndex(CUSTOMER_INFO_ID)).toInt(),
                            cursor.getString(cursor.getColumnIndex(CUSTOMER_TYPE_ID)).toInt(),
                            "",
                            cursor.getString(cursor.getColumnIndex(KEY_CUST_ID)).toInt(),
                            cursor.getString(cursor.getColumnIndex(LOB_ID)).toInt(),
                            "", 0,
                            if (cursor.getString(cursor.getColumnIndex(KEY_PAYMENT_TERM_ID)) != null) cursor.getString(
                                cursor.getColumnIndex(KEY_PAYMENT_TERM_ID)
                            ).toInt()
                            else 0,
                            cursor.getString(cursor.getColumnIndex(KEY_REGION_ID)).toInt(),
                            cursor.getString(cursor.getColumnIndex(KEY_ROUTE_ID)).toInt(),
                            cursor.getString(cursor.getColumnIndex(KEY_SALES_ORG_ID)).toInt(),
                            "",
                            "",
                            CustomerData.DataCustomer.Lob(
                                cursor.getString(cursor.getColumnIndex(LOB_ID)),
                                cursor.getString(cursor.getColumnIndex(LOB_NAME))
                            ),
                            cursor.getString(cursor.getColumnIndex(KEY_DUE_ON)).toInt()
                        )
                        mList = mData
                    } while (cursor.moveToNext())
                }
            }
        } finally {
            try {
                db.close()
            } catch (ignore: Exception) {
            }
        }

        return mList
    }

