    fun updateCustomerGeoApproveRequest(
        customerId: String,
        status: String
    ): Int {
        val contentValues = ContentValues()
        contentValues.put(KEY_GEO_APPROVAL_STATUS, status)
        val db = this.writableDatabase
        val i = db.update(
            TABLE_CUSTOMER,
            contentValues,
            "$KEY_CUSTOMER_ID = ?",
            arrayOf<String>(customerId)
        )
        return i
    }

    fun updateCustomerGeoRequest(
        customerId: String,
        status: String,
        mID: String
    ): Int {
        val contentValues = ContentValues()
        contentValues.put(KEY_GEO_APPROVAL_STATUS, status)
        contentValues.put(KEY_GEO_ID, mID)
        val db = this.writableDatabase
        val i = db.update(
            TABLE_CUSTOMER,
            contentValues,
            "$KEY_CUSTOMER_ID = ?",
            arrayOf<String>(customerId)
        )
        return i
    }

