    fun getDelvierySequnceCustomer(): ArrayList<CustomerData.DataCustomer> {
        var mList: ArrayList<CustomerData.DataCustomer> = ArrayList()

        val db = this.readableDatabase

        var cursor = db.rawQuery(
            ("SELECT * FROM " +
                    TABLE_DELIVERY_HEADER), null
        )

        try {
            if (cursor.moveToFirst()) {
                do {
                    val mData = getCustomerDetailFromCustId(
                        cursor.getString(
                            cursor.getColumnIndex(KEY_CUSTOMER_ID)
                        )
                    )
                    if (mData != null) {
                        if (!mList.contains(mData!!)) {

                            if (mData!!.planSeq == "0") {
                                var mLastSeq = getCustomerLastSeq()
                                var mNewSeq = (mLastSeq.toInt() + 1).toString()
                                mData!!.planSeq = mNewSeq
                                updateCustomerSeq(
                                    cursor.getString(
                                        cursor.getColumnIndex(KEY_CUSTOMER_ID)
                                    ), mNewSeq
                                )
                                mList.add(mData!!)
                            } else {
                                mList.add(mData!!)
                            }

                        }
                    }

                } while (cursor.moveToNext())
            }
        } finally {
            try {
                db.close()
            } catch (ignore: Exception) {
            }
        }

        return mList
    }


