    private fun getPromoOrderItem(mPromoId: String): ArrayList<ItemData.Data> {
        var mList: ArrayList<ItemData.Data> = ArrayList()

        val db = this.readableDatabase

        var cursor = db.rawQuery(
            ("SELECT * FROM " +
                    TABLE_PROMOTION_ORDER_ITEM + " WHERE " +
                    KEY_PROMOTION_ID + "=?"), arrayOf<String>(mPromoId)
        )

        try {
            if (cursor.moveToFirst()) {
                do {

                    if (cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID)) != null) {
                        val mItem =
                            getItemDetailFromId(cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID)))

                        if (mItem != null) {
                            var mSelectUOMList: ArrayList<UomData> = ArrayList()
                            mSelectUOMList!!.add(
                                UomData(
                                    mItem!!.id.toString(),
                                    mItem!!.itemCode,
                                    mItem!!.itemName,
                                    "8",
                                    "CTN",
                                    "1",
                                    cursor.getString(cursor.getColumnIndex(KEY_QTY)),
                                    "0",
                                    "0",
                                    "",
                                    discountAmt = "0",
                                    netAmt = "0",
                                    vatAmt = "0",
                                    totalAmt = "0",
                                    promotion_Id = "",
                                    discount_Id = "",
                                    reason = ""
                                )
                            )

                            mItem.itemSelectUOM = mSelectUOMList

                            mList.add(mItem!!)
                        }

                    }

                } while (cursor.moveToNext())
            }
        } finally {
            try {
                db.close()
            } catch (ignore: Exception) {
            }
        }

        return mList
    }

