    fun getCustomerActivity(mCode: String, mCustomer: String): ArrayList<ActivityProfile> {

        var mList: ArrayList<ActivityProfile> = ArrayList()

        val db = this.readableDatabase

        var cursor = db.rawQuery(
            ("SELECT * FROM " +
                    TABLE_MERCHANDISING_ACTIVITY + " WHERE " +
                    KEY_CUSTOMER_ID + "=? AND " + KEY_STATUS + "=? ORDER BY " + KEY_PRIORITY + " ASC"),
            arrayOf<String>(mCode, "1")
        )

        try {
            if (cursor.moveToFirst()) {
                do {
                    var mData = ActivityProfile()
                    mData.name = cursor.getString(cursor.getColumnIndex(KEY_MENU_NAME))
                    mData.priority = cursor.getString(cursor.getColumnIndex(KEY_PRIORITY))

                    if (mData.name == "Shelf Display") {
                        if (checkIsShelfDisplay(mCustomer)) {
                            mData.isCompleted = "1"
                        } else {
                            mData.isCompleted = "0"
                        }
                    } else if (mData.name == "Sotck In Store") {
                        if (checkIsStockInStore(mCustomer)) {
                            mData.isCompleted = "1"
                        } else {
                            mData.isCompleted = "0"
                        }
                    } else if (mData.name == "Complain Feedback") {
                        if (checkIsComplainFeedback(mCustomer)) {
                            mData.isCompleted = "1"
                        } else {
                            mData.isCompleted = "0"
                        }
                    } else if (mData.name == "Planogram") {
                        if (checkIsPlanogram(mCustomer)) {
                            mData.isCompleted = "1"
                        } else {
                            mData.isCompleted = "0"
                        }
                    } else if (mData.name == "Campaign Picture") {
                        if (checkIsCampaign(mCustomer)) {
                            mData.isCompleted = "1"
                        } else {
                            mData.isCompleted = "0"
                        }
                    } else if (mData.name == "Consumer Survey") {
                        if (checkIsConsumerSurvey(mCustomer)) {
                            mData.isCompleted = "1"
                        } else {
                            mData.isCompleted = "0"
                        }
                    } else if (mData.name == "Asset Tracking") {
                        if (checkIsAssetTracking(mCustomer)) {
                            mData.isCompleted = "1"
                        } else {
                            mData.isCompleted = "0"
                        }
                    }
                    mList.add(mData)
                } while (cursor.moveToNext())

            }
        } finally {
            try {
                db.close()
            } catch (ignore: Exception) {
            }
        }

        return mList
    }

    fun updateCustomerSeq(custId: String, type: String) {
        val db = this.writableDatabase
        val contentValues = ContentValues()
        contentValues.put(KEY_PLAN_SEQ, type)
        db.update(
            TABLE_CUSTOMER, contentValues,
            "$KEY_CUSTOMER_ID =?", arrayOf<String>(custId)
        )
    }

    //Update Customer Transaction
    fun updateCustomerTransaction(custId: String, type: String) {
        val db = this.writableDatabase
        val contentValues = ContentValues()
        if (type == "sale") {
            contentValues.put(CUST_SALE, "1")
        } else if (type == "order") {
            contentValues.put(CUST_ORDER, "1")
        } else if (type == "collection") {
            contentValues.put(CUST_COLL, "1")
        } else if (type == "return") {
            contentValues.put(CUST_RETURN, "1")
        } else if (type == "merchandising") {
            contentValues.put(CUST_MERCHAN, "1")
        }
        db.update(
            TABLE_CUSTOMER, contentValues,
            "$KEY_CUSTOMER_ID =?", arrayOf<String>(custId)
        )
    }

