    fun checkCollectionPiadCount(invoiceNo: String): Boolean {
        val db = this.readableDatabase
        var mIsMore = false;
        val cursor = db.rawQuery(
            ("SELECT * FROM " +
                    TABLE_COLLECTION + " WHERE " +
                    KEY_INVOICE_NO + "=?"),
            arrayOf<String>(invoiceNo)
        )

        try {
            if (cursor.moveToFirst()) {
                do {
                    var mAmount = cursor.getString(cursor.getColumnIndex(KEY_PENDING_AMOUNT))
                    if (mAmount.toDouble() > 0.40) {
                        mIsMore = true
                    }
                } while (cursor.moveToNext())
            }
        } finally {
            try {
                db.close()
            } catch (ignore: Exception) {
            }
        }

        return mIsMore
    }

