    //get Delivery Detail
    fun getDeliveryDetail(deliveryNo: String): ArrayList<ItemData.Data> {
        val list = ArrayList<ItemData.Data>()

        val db = this.readableDatabase
        try {
            var cursor = db.rawQuery(
                ("SELECT * FROM " +
                        TABLE_DELIVERY_ITEM + " WHERE " +
                        KEY_DELIVERY_NO + "=?"), arrayOf<String>(deliveryNo)
            )
            try {
                // looping through all rows and adding to list
                if (cursor.moveToFirst()) {
                    do {

                        val mLowerUOM =
                            getLowerUOM(
                                getItemLowerUnit(
                                    cursor.getString(
                                        cursor.getColumnIndex(
                                            KEY_ITEM_ID
                                        )
                                    )
                                ),
                                cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID))
                            )

                        val mUOMList =
                            getItemUOM(cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID)))

                        var mgrossPrice = 0.0
                        if (cursor.getString(cursor.getColumnIndex(KEY_IS_FREE)) == "1") {
                            mgrossPrice = 0.0
                        } else {
                            mgrossPrice =
                                cursor.getString(cursor.getColumnIndex(KEY_QTY)).toDouble() *
                                        cursor.getString(cursor.getColumnIndex(KEY_UOM_PRICE))
                                            .toDouble()
                        }


                        var vanUom =
                            getVanStockItemUOM(
                                cursor.getString(
                                    cursor.getColumnIndex(
                                        KEY_ITEM_ID
                                    )
                                )
                            )

                        var mDiscPer = ""
                        if (cursor.getString(cursor.getColumnIndex(KEY_DISCOUNT)) != null) {
                            if (cursor.getString(cursor.getColumnIndex(KEY_DISCOUNT))
                                    .toDouble() > 0
                            ) {
                                var mDisc =
                                    cursor.getString(cursor.getColumnIndex(KEY_DISCOUNT)).toDouble()
                                mDiscPer = String.format(
                                    "%.2f",
                                    (mDisc.toDouble() / mgrossPrice.toDouble() * 100)
                                )
                            }
                        }

                        var itemSelectUOM: ArrayList<UomData> = ArrayList()
                        itemSelectUOM!!.add(
                            UomData(
                                cursor.getString(
                                    cursor.getColumnIndex(KEY_ITEM_ID)
                                ),
                                cursor.getString(
                                    cursor.getColumnIndex(KEY_ITEM_CODE)
                                ),
                                getItemName(
                                    cursor.getString(
                                        cursor.getColumnIndex(
                                            KEY_ITEM_ID
                                        )
                                    )
                                ),
                                cursor.getString(cursor.getColumnIndex(KEY_UOM_ID)),
                                cursor.getString(cursor.getColumnIndex(KEY_UOM_NAME)),
                                getItemUOMUPC(
                                    cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID)),
                                    cursor.getString(cursor.getColumnIndex(KEY_UOM_ID))
                                ),
                                cursor.getString(cursor.getColumnIndex(KEY_QTY)),
                                cursor.getString(cursor.getColumnIndex(KEY_UOM_PRICE)),
                                "" + mgrossPrice,
                                mDiscPer,
                                cursor.getString(cursor.getColumnIndex(KEY_DISCOUNT)),
                                cursor.getString(cursor.getColumnIndex(KEY_NET)),
                                cursor.getString(cursor.getColumnIndex(KEY_VAT)),
                                cursor.getString(cursor.getColumnIndex(KEY_TOTAL)),
                                cursor.getString(cursor.getColumnIndex(KEY_PROMOTION_ID)),
                                discount_Id = "",
                                reason = "",
                                item_excise = "0"
                            )
                        )

                        val mItemData =
                            getItemDetail(cursor.getString(cursor.getColumnIndex(KEY_ITEM_CODE)))

                        val mItem = ItemData.Data(
                            mItemData!!.majorCategory,
                            mItemData!!.groupId,
                            mItemData!!.brandId,
                            cursor.getString(cursor.getColumnIndex(KEY_ITEM_CODE)),
                            cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID)).toInt(),
                            mItemData.itemName,
                            mItemData.barcode,
                            "0",
                            cursor.getString(cursor.getColumnIndex(KEY_DELV_ITEM_ID)),
                            mLowerUOM!!.uomUPC,
                            mLowerUOM!!.uomId,
                            mLowerUOM!!.uomPrice,
                            mItemData!!.isTaxApply,
                            mItemData!!.vatPercentage,
                            null,
                            mUOMList,
                            itemSelectUOM!!,
                            emptyList(),
                            null,
                            null, null,
                            vanUom,
                            cursor.getString(cursor.getColumnIndex(KEY_IS_FREE)),
                            cursor.getString(cursor.getColumnIndex(KEY_UOM_ID)),
                            mItemData!!.lobId
                        )
                        mItem!!.isStockAvailable = "1"


                        //you could add additional columns here..
                        list.add(mItem)

                    } while (cursor.moveToNext())
                }
            } finally {
                try {
                    cursor.close()
                } catch (ignore: Exception) {
                }
            }
        } finally {
            try {
                db.close()
            } catch (ignore: Exception) {
            }
        }
        return list
    }

    //get Free Goods available
    fun isItemAvailable(itemId: String, saleQty: String): Boolean {
        var isContain = false
        val db = this.getReadableDatabase()
        try {
            val cursor = db.rawQuery(
                ("SELECT * FROM " +
                        TABLE_VANSTOCK + " WHERE " +
                        KEY_ITEM_ID + "=?"), arrayOf<String>(itemId)
            )
            if (cursor.getCount() > 0) {
                if (cursor.moveToFirst()) {
                    var qBty =
                        Utils.getFormateQty(cursor.getString(cursor.getColumnIndex(KEY_REMAINING_QTY)))
                            .toDouble()

                    if (qBty >= saleQty.toDouble()) {
                        isContain = true
                    }
                }
            }
            cursor.close()
        } catch (e: Exception) {
            e.printStackTrace()
        }
        return isContain
    }

