    fun getTCCustomerPendingInvoice(mCustomerCode: String): Int {
        var pendingAmnt = 0

        val db = this.readableDatabase

        var cursor = db.rawQuery(
            ("SELECT * FROM " +
                    TABLE_COLLECTION + " WHERE " +
                    KEY_CUSTOMER_CODE + "=?"), arrayOf<String>(mCustomerCode)
        )

        try {
            if (cursor.moveToFirst()) {
                do {
                    var type = cursor.getString(cursor.getColumnIndex(KEY_TYPE))

                    if (type == "Invoice") {

                        if (cursor.getString(cursor.getColumnIndex(KEY_PENDING_AMOUNT))
                                .toFloat() > 0
                        ) {
                            var pendAmt = Utils.twoDigit(
                                (cursor.getString(cursor.getColumnIndex(KEY_INVOICE_AMOUNT))
                                    .toFloat() -
                                        cursor.getString(cursor.getColumnIndex(KEY_AMOUNT_CLEARED))
                                            .toFloat())
                            )

                            if (pendAmt > 0.0) {
                                pendingAmnt += 1
                            }
                        }
                    }
                } while (cursor.moveToNext())
            }
        } finally {
            try {
                db.close()
            } catch (ignore: Exception) {
            }
        }

        return pendingAmnt
    }

