    //Update stamp status
    fun updateStampStatus(invoiceNo: String, stampStatus: String): Int {
        val contentValues = ContentValues()
        contentValues.put(KEY_STAMP, stampStatus)
        val db = this.writableDatabase
        val i = db.update(
            TABLE_INVOICE_HEADER,
            contentValues,
            "$KEY_INVOICE_NO = ? ",
            arrayOf<String>(invoiceNo)
        )
        return i
    }

    fun updatCancelInvoiceStatus(invoiceNo: String, invoiceCancelStatus: String): Int {
        val contentValues = ContentValues()
        contentValues.put(KEY_INVOICE_CANCEL, invoiceCancelStatus)
        contentValues.put(KEY_STAMP, "0")
        val db = this.writableDatabase
        val i = db.update(
            TABLE_INVOICE_HEADER,
            contentValues,
            "$KEY_INVOICE_NO = ? ",
            arrayOf<String>(invoiceNo)
        )
        return i
    }

