    //get All Transaction from Customer
    fun getAllTransactionsForCustomer(
        customerCode: String,
        lobCode: String
    ): ArrayList<Transaction> {
        val list = ArrayList<Transaction>()
        // Select All Query

        val selectQuery = ("SELECT * FROM " + TABLE_TRANSACTION +
                " WHERE " + TR_CUSTOMER_NUM + "=?")
        val db = this.readableDatabase
        try {
            val cursor = db.rawQuery(selectQuery, arrayOf<String>(customerCode))
            try {
                // looping through all rows and adding to list
                if (cursor.moveToFirst()) {
                    do {
                        val transaction = Transaction()
                        //only one column
                        transaction.tr_type = cursor.getString(cursor.getColumnIndex(TR_TYPE))
                        transaction.tr_date_time =
                            cursor.getString(cursor.getColumnIndex(TR_DATE))
                        transaction.tr_salesman_id =
                            cursor.getString(cursor.getColumnIndex(TR_SALESMAN_ID))
                        transaction.tr_customer_name =
                            cursor.getString(cursor.getColumnIndex(TR_CUSTOMER_NAME))
                        transaction.tr_customer_num =
                            cursor.getString(cursor.getColumnIndex(TR_CUSTOMER_NUM))
                        transaction.tr_collection_id =
                            cursor.getString(cursor.getColumnIndex(TR_COLLECTION_ID))
                        transaction.tr_order_id =
                            cursor.getString(cursor.getColumnIndex(TR_ORDER_ID))
                        transaction.tr_invoice_id =
                            cursor.getString(cursor.getColumnIndex(TR_INVOICE_ID))
                        transaction.tr_pyament_id =
                            cursor.getString(cursor.getColumnIndex(TR_PYAMENT_ID))
                        transaction.tr_is_posted =
                            cursor.getString(cursor.getColumnIndex(TR_IS_POSTED))
                        transaction.tr_printData =
                            cursor.getString(cursor.getColumnIndex(KEY_DATA))

                        if (cursor.getString(cursor.getColumnIndex(TR_TYPE)) == AppConstants.TRANSACTION_TYPES.TT_SALES_CREATED) {
                            var isTopupInve =
                                isTopupInvoice(cursor.getString(cursor.getColumnIndex(TR_INVOICE_ID)))
                            if (!isTopupInve) {
                                //you could add additional columns here..
                                list.add(transaction)
                            }
                        } else {
                            //you could add additional columns here..
                            list.add(transaction)
                        }

                    } while (cursor.moveToNext())
                }
            } finally {
                try {
                    cursor.close()
                } catch (ignore: Exception) {
                }
            }
        } finally {
            try {
                db.close()
            } catch (ignore: Exception) {
            }
        }
        return list
    }

    fun getAllLoadItem(mLoadNo: String): ArrayList<SalesmanLoadDetail> {
        var mList: ArrayList<SalesmanLoadDetail> = ArrayList()

        val db = this.readableDatabase

        var cursor = db.rawQuery(
            ("SELECT * FROM " +
                    TABLE_LOAD_ITEM + " WHERE " +
                    KEY_LOAD_NO + "=?"), arrayOf<String>(mLoadNo)
        )

        try {
            if (cursor.moveToFirst()) {
                do {

                    var mprimaryQty = Utils.getUOMPrimaryQty(
                        getItemUOMUPC(
                            cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID)),
                            cursor.getString(cursor.getColumnIndex(KEY_DISPLAY_UNIT))
                        ), cursor.getString(cursor.getColumnIndex(KEY_QTY))
                    )

                    var qty = Utils.getUOMQty(
                        getItemUOMUPC(
                            cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID)),
                            cursor.getString(cursor.getColumnIndex(KEY_DISPLAY_UNIT))
                        ), cursor.getString(cursor.getColumnIndex(KEY_QTY))
                    )


                    val mData = SalesmanLoadDetail(
                        null,
                        cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID)),
                        cursor.getString(cursor.getColumnIndex(KEY_UOM_ID)),
                        cursor.getString(cursor.getColumnIndex(KEY_QTY)),
                        cursor.getString(cursor.getColumnIndex(KEY_ITEM_NAME)),
                        cursor.getString(cursor.getColumnIndex(KEY_UOM_NAME)),
                        "",
                        getItemCode(cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID))),
                        cursor.getString(cursor.getColumnIndex(KEY_QTY)),
                        "",
                        qty,
                        cursor.getString(cursor.getColumnIndex(KEY_REQ_QTY)),
                        cursor.getString(cursor.getColumnIndex(KEY_DISPLAY_UNIT)),
                        cursor.getString(cursor.getColumnIndex(KEY_DISPLAY_UNIT_NAME)),
                        cursor.getString(cursor.getColumnIndex(KEY_REQ_UOM_NAME)),
                        cursor.getString(cursor.getColumnIndex(KEY_WH_QTY)),
                        cursor.getString(cursor.getColumnIndex(KEY_SP_QTY)),
                        cursor.getString(cursor.getColumnIndex(KEY_VARIANCE_QTY)),
                        mprimaryQty,
                        getAllLoadItemBatchItem(
                            mLoadNo,
                            cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID))
                        ),
                        getAllLoadItemBatchItem(
                            mLoadNo,
                            cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID))
                        ),
                        emptyList(),
                        ""
                    )
                    mList.add(mData)
                } while (cursor.moveToNext())
            }
        } finally {
            try {
                db.close()
            } catch (ignore: Exception) {
            }
        }

        return mList
    }

