        }

        return name
    }

    fun isVanStockItemAvailable(mItemId: String, mQty: String): String {
        var isAvailable: String = "0"

        val db = this.readableDatabase
        try {
            var cursor = db.rawQuery(
                ("SELECT * FROM " +
                        TABLE_VANSTOCK + " WHERE " +
                        KEY_ITEM_ID + "=? AND " + KEY_IS_RE_ITEM + "=?"),
                arrayOf<String>(mItemId, "0")
            )
            cursor.moveToFirst()
            val count = cursor.getCount()
            if (count > 0) {
                var aQty = cursor.getString(cursor.getColumnIndex(KEY_REMAINING_QTY))
                if (mQty.toFloat() > aQty.toFloat()) {
                    isAvailable = "0"
                } else {
                    isAvailable = "1"
                }
            }

            cursor.close()
        } catch (e: Exception) {
            e.printStackTrace()
        }

        return isAvailable
    }

