    //Get All Transaction Data
    fun getAllTransactions(): ArrayList<Transaction> {
        val list = ArrayList<Transaction>()
        // Select All Query
        val selectQuery = "SELECT * FROM $TABLE_TRANSACTION"
        val db = this.readableDatabase
        try {
            val cursor = db.rawQuery(selectQuery, null)
            try {
                // looping through all rows and adding to list
                if (cursor.moveToFirst()) {
                    do {
                        val transaction = Transaction()
                        //only one column
                        transaction.tr_type = cursor.getString(cursor.getColumnIndex(TR_TYPE))
                        transaction.tr_date_time =
                            cursor.getString(cursor.getColumnIndex(TR_DATE))
                        transaction.tr_salesman_id =
                            cursor.getString(cursor.getColumnIndex(TR_SALESMAN_ID))
                        transaction.tr_customer_name =
                            cursor.getString(cursor.getColumnIndex(TR_CUSTOMER_NAME))
                        transaction.tr_customer_num =
                            cursor.getString(cursor.getColumnIndex(TR_CUSTOMER_NUM))
                        transaction.tr_collection_id =
                            cursor.getString(cursor.getColumnIndex(TR_COLLECTION_ID))
                        transaction.tr_order_id =
                            cursor.getString(cursor.getColumnIndex(TR_ORDER_ID))
                        transaction.tr_invoice_id =
                            cursor.getString(cursor.getColumnIndex(TR_INVOICE_ID))
                        transaction.tr_pyament_id =
                            cursor.getString(cursor.getColumnIndex(TR_PYAMENT_ID))
                        transaction.tr_is_posted =
                            cursor.getString(cursor.getColumnIndex(TR_IS_POSTED))
                        transaction.tr_printData =
                            cursor.getString(cursor.getColumnIndex(KEY_DATA))
                        transaction.tr_message =
                            cursor.getString(cursor.getColumnIndex(TR_MESSAGE))
                        transaction.tr_isCheck = "false"
                        //you could add additional columns here..
                        list.add(transaction)
                    } while (cursor.moveToNext())
                }
            } finally {
                try {
                    cursor.close()
                } catch (ignore: Exception) {
                }
            }
        } finally {
            try {
                db.close()
            } catch (ignore: Exception) {
            }
        }
        return list
    }

