    fun getAllCancelDelveiry(): JsonArray {
        var marray = JsonArray()
        val db = this.readableDatabase
        try {
            val cursor = db.rawQuery(
                ("SELECT * FROM " +
                        TABLE_DELIVERY_HEADER + " WHERE " +
                        KEY_IS_DELETED + "=?"),
                arrayOf<String>("1")
            )
            try {
                if (cursor.moveToFirst()) {
                    do {

                        var mjOBj = JsonObject()
                        mjOBj.addProperty(
                            "delivery_id", cursor.getString(
                                cursor.getColumnIndex(
                                    KEY_DELIVERY_ID
                                )
                            )
                        )
                        mjOBj.addProperty(
                            "delivery_number", cursor.getString(
                                cursor.getColumnIndex(
                                    KEY_DELIVERY_NO
                                )
                            )
                        )

                        mjOBj.addProperty(
                            "cancel_comment", cursor.getString(
                                cursor.getColumnIndex(
                                    KEY_ORDER_COMMENT
                                )
                            )
                        )

                        mjOBj.addProperty("image", "")
                        marray.add(mjOBj)
                    } while (cursor.moveToNext())
                }
            } finally {
                try {
                    db.close()
                } catch (ignore: Exception) {
                }
            }
        } catch (e: Exception) {
            e.printStackTrace()
        }
        return marray
    }

