    //GET Unload Detail
    fun getPostUnloadExpiryDetail(): Order {
        var mOrder = Order()
        var mGross = 0.0
        var mDiscount = 0.0
        var mNet = 0.0
        var mVat = 0.0
        var mTotal = 0.0
        var tripid = ""
        var reason = ""
        val db = this.readableDatabase
        try {
            val cursor = db.rawQuery(
                ("SELECT * FROM " +
                        TABLE_UNLOAD_VAN_EXPIRY + " WHERE " +
                        DATA_MARK_FOR_POST + "=?"), arrayOf<String>("M")
            )
            try {

                if (cursor.moveToFirst()) {
                    do {
                        tripid = cursor.getString(cursor.getColumnIndex(KEY_TRIP_ID))
                        reason = cursor.getString(cursor.getColumnIndex(KEY_REASON))

                        var mUom =
                            getItemUOMDetail(
                                cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID)),
                                cursor.getString(cursor.getColumnIndex(KEY_UOM_ID))
                            )

                        var discountAmt = 0
                        var grossPrice = cursor.getString(cursor.getColumnIndex(KEY_UNLOAD_QTY))
                            .toDouble() * mUom!!.uomPrice.toDouble()
                        var netAmt = grossPrice - discountAmt
                        var itemVat =
                            getItemVat(cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID)))
                        var vatAmt = Utils.getVatAmt(grossPrice, itemVat.toDouble())
                        var totalAmt = netAmt + vatAmt

                        mGross += grossPrice
                        mNet += netAmt
                        mVat += vatAmt
                        mTotal += totalAmt

                    } while (cursor.moveToNext())

                }
            } finally {
                try {
                    db.close()
                } catch (ignore: Exception) {
                }
            }
        } catch (e: Exception) {
            e.printStackTrace()
        }

        mOrder.orderNo = tripid
        mOrder.gross = "" + mGross
        mOrder.discount = "" + mGross
        mOrder.net = "" + mGross
        mOrder.vat = "" + mGross
        mOrder.total = "" + mGross
        mOrder.reason = reason

        return mOrder
    }

