    //GET Post Unload Items
    fun getPostUnloadItem(mUnloadNo: String, mDate: String): JsonArray {

        val arrItem = JsonArray()
        var mItem: JsonObject
        val db = this.readableDatabase
        try {
            val cursor = db.rawQuery(
                ("SELECT * FROM " +
                        TABLE_UNLOAD_ITEM + " WHERE " +
                        KEY_UNIQUE_ID + "=?"), arrayOf<String>(mUnloadNo)
            )
            try {
                if (cursor.moveToFirst()) {
                    do {
                        mItem = JsonObject()
                        mItem.addProperty(
                            "item_id", cursor.getString(
                                cursor.getColumnIndex(
                                    KEY_ITEM_ID
                                )
                            )
                        )
                        mItem.addProperty(
                            "item_uom", cursor.getString(
                                cursor.getColumnIndex(
                                    KEY_UOM_ID
                                )
                            )
                        )

                        mItem.addProperty(
                            "unload_qty", cursor.getString(
                                cursor.getColumnIndex(
                                    KEY_UNLOAD_QTY
                                )
                            )
                        )

                        mItem.addProperty(
                            "unload_date", mDate
                        )

                        mItem.addProperty(
                            "unload_type", cursor.getString(
                                cursor.getColumnIndex(
                                    KEY_UNLOAD_TYPE
                                )
                            )
                        )

                        mItem.addProperty(
                            "reason", cursor.getString(
                                cursor.getColumnIndex(
                                    KEY_REASON
                                )
                            )
                        )

                        /*  mItem.addProperty(
                              "batch_number", cursor.getString(
                                  cursor.getColumnIndex(
                                      KEY_BATCH
                                  )
                              )
                          )*/

//                        var allLoadBatchItem = getUnloadBatchId(
//                            cursor.getString(
//                                cursor.getColumnIndex(
//                                    KEY_ITEM_ID
//                                )
//                            )
//                        )
//
//                        mItem.addProperty("batch_number", allLoadBatchItem.toString())

                        arrItem.add(mItem)
                    } while (cursor.moveToNext())
                }
            } finally {
                try {
                    db.close()
                } catch (ignore: Exception) {
                }
            }
        } catch (e: Exception) {
            e.printStackTrace()
        }
        return arrItem
    }

