    //GET Post Unload Expiry Items
    fun getPostUnloadVanExpiryItem(): JsonArray {

        val arrItem = JsonArray()
        var mItem: JsonObject
        val db = this.readableDatabase
        try {
            val cursor = db.rawQuery(
                ("SELECT * FROM " +
                        TABLE_UNLOAD_VAN_EXPIRY + " WHERE " +
                        DATA_MARK_FOR_POST + "=?"), arrayOf<String>("M")
            )
            try {
                if (cursor.moveToFirst()) {
                    do {

                        val mItem = JsonObject()
                        //only one column
                        mItem.addProperty(
                            "item_id",
                            cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID))
                        )
                        mItem.addProperty(
                            "item_uom_id",
                            cursor.getString(cursor.getColumnIndex(KEY_UOM_ID))
                        )

                        mItem.addProperty(
                            "item_condition",
                            "0"
                        )

                        mItem.addProperty(
                            "discount_id", ""
                        )
                        mItem.addProperty("is_free", false)
                        mItem.addProperty("is_item_poi", 0)
                        mItem.addProperty(
                            "promotion_id", ""
                        )
                        mItem.addProperty(
                            "item_qty",
                            cursor.getString(cursor.getColumnIndex(KEY_UNLOAD_QTY))
                        )

                        var mUom =
                            getItemUOMDetail(
                                cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID)),
                                cursor.getString(cursor.getColumnIndex(KEY_UOM_ID))
                            )

                        var discountAmt = 0
                        var grossPrice = cursor.getString(cursor.getColumnIndex(KEY_UNLOAD_QTY))
                            .toDouble() * mUom!!.uomPrice.toDouble()
                        var netAmt = grossPrice - discountAmt
                        var itemVat =
                            getItemVat(cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID)))
                        var vatAmt = Utils.getVatAmt(grossPrice, itemVat.toDouble())
                        var totalAmt = netAmt + vatAmt

                        mItem.addProperty(
                            "item_price",
                            mUom!!.uomPrice
                        )
                        mItem.addProperty(
                            "item_gross",
                            grossPrice
                        )
                        mItem.addProperty(
                            "item_discount_amount",
                            discountAmt
                        )
                        mItem.addProperty(
                            "item_net",
                            netAmt
                        )
                        mItem.addProperty(
                            "item_vat",
                            vatAmt
                        )
                        mItem.addProperty(
                            "item_grand_total",
                            totalAmt
                        )

                        mItem.addProperty(
                            "item_excise",
                            "0"
                        )

                        mItem.addProperty(
                            "reason",
                            cursor.getString(cursor.getColumnIndex(KEY_REASON))
                        )

                        mItem.addProperty(
                            "batch_number",
                            ""
                        )
                        //you could add additional columns here..
                        arrItem.add(mItem)

                    } while (cursor.moveToNext())
                }
            } finally {
                try {
                    db.close()
                } catch (ignore: Exception) {
                }
            }
        } catch (e: Exception) {
            e.printStackTrace()
        }
        return arrItem
    }

