    //GET Post Inventory Items
    fun getPostInventoryItem(mUniqueId: String): JsonArray {

        val arrItem = JsonArray()
        var mItem: JsonObject
        val db = this.readableDatabase
        try {
            val cursor = db.rawQuery(
                ("SELECT * FROM " +
                        TABLE_INVENTORY_POST_ITEM + " WHERE " +
                        KEY_UNIQUE_ID + "=?"), arrayOf<String>(mUniqueId)
            )
            try {
                if (cursor.moveToFirst()) {
                    do {
                        mItem = JsonObject()
                        mItem.addProperty(
                            "item_id", cursor.getString(
                                cursor.getColumnIndex(
                                    KEY_ITEM_ID
                                )
                            )
                        )
                        mItem.addProperty(
                            "item_uom_id", cursor.getString(
                                cursor.getColumnIndex(
                                    KEY_UOM_ID
                                )
                            )
                        )

                        mItem.addProperty(
                            "qty", cursor.getString(
                                cursor.getColumnIndex(
                                    KEY_QTY
                                )
                            )
                        )

                        mItem.addProperty(
                            "capacity", cursor.getString(
                                cursor.getColumnIndex(
                                    KEY_CAPACITY
                                )
                            )
                        )

                        mItem.addProperty(
                            "fill", cursor.getString(
                                cursor.getColumnIndex(
                                    KEY_FILL_QTY
                                )
                            )
                        )

                        mItem.addProperty(
                            "refill", cursor.getString(
                                cursor.getColumnIndex(
                                    KEY_REFILL_QTY
                                )
                            )
                        )

                        mItem.addProperty(
                            "reorder", cursor.getString(
                                cursor.getColumnIndex(
                                    KEY_REORDER_QTY
                                )
                            )
                        )

                        var mQty = cursor.getString(
                            cursor.getColumnIndex(
                                KEY_QTY
                            )
                        )

                        if (mQty.toDouble() > 0) {
                            mItem.addProperty(
                                "out_of_stock", cursor.getString(
                                    cursor.getColumnIndex(
                                        KEY_OUT_OF_STOCK
                                    )
                                )
                            )
                        } else {
                            mItem.addProperty(
                                "out_of_stock", "1"
                            )
                        }


                        var mExpiry = getPostInventoryItemExpiry(
                            mUniqueId, cursor.getString(
                                cursor.getColumnIndex(
                                    KEY_ITEM_ID
                                )
                            )
                        )
                        mItem.add(
                            "expiry", mExpiry
                        )

                        mItem.add(
                            "damage", getPostInventoryDERItem(
                                mUniqueId, cursor.getString(
                                    cursor.getColumnIndex(
                                        KEY_ITEM_ID
                                    )
                                )
                            )
                        )

                        arrItem.add(mItem)
                    } while (cursor.moveToNext())
                }
            } finally {
                try {
                    db.close()
                } catch (ignore: Exception) {
                }
            }
        } catch (e: Exception) {
            e.printStackTrace()
        }
        return arrItem
    }

