    fun getCustomerDisplayCategoryList(
        mCust: String,
        mBranId: String,
        headBrandId: String,
        isSub: String
    ): ArrayList<Category> {
        var mList: ArrayList<Category> = ArrayList()

        val db = this.readableDatabase

        try {
            var cursor = db.rawQuery(
                ("SELECT * FROM " +
                        TABLE_DISPLAY_TOOL_ITEM + " WHERE " +
                        KEY_ITEM_BRAND_ID + "=? AND " + KEY_CUSTOMER_ID + "=?"),
                arrayOf<String>(mBranId, mCust)
            )

            if (cursor.moveToFirst()) {
                do {
                    val mData = Category()

                    if (checkIsCategory(
                            cursor.getString(
                                cursor.getColumnIndex(
                                    KEY_ITEM_CATEGORY_ID
                                )
                            )
                        )
                    ) {
                        mData.categoryId =
                            cursor.getString(cursor.getColumnIndex(KEY_ITEM_CATEGORY_ID))
                        var mParentDetail = getParentCategoryDetail(
                            cursor.getString(
                                cursor.getColumnIndex(KEY_ITEM_CATEGORY_ID)
                            )
                        )
                        mData.name = mParentDetail.get("name")
                    } else {
                        var catId = getSubCategoryId(
                            cursor.getString(
                                cursor.getColumnIndex(KEY_ITEM_CATEGORY_ID)
                            )
                        )
                        mData.categoryId = catId
                        var mParentDetail = getParentCategoryDetail(catId)
                        mData.name = mParentDetail.get("name")
                    }

                    mData.isPosted = checkDistributionCustomerCategoryPosted(
                        mCust,
                        headBrandId,
                        mBranId,
                        mData.categoryId.toString()
                    )

                    if (mList.size > 0) {
                        var isContain = false
                        for (mBrnadDa in mList) {
                            if (mBrnadDa.categoryId == mData.categoryId) {
                                isContain = true
                                break
                            }
                        }

                        if (!isContain) {
                            mList.add(mData)
                        }
                    } else {
                        mList.add(mData)
                    }

                } while (cursor.moveToNext())
            }
            cursor.close()
        } catch (e: Exception) {
            e.printStackTrace()
        }

        return mList
    }


