    //Get Distribution Items
    fun getCustomerDistributionList(
        mCustomerCode: String,
        mBrand: String,
        mCategory: String
    ): ArrayList<Distribution> {
        val arrData: ArrayList<Distribution> = ArrayList()
        val db = this.readableDatabase
        try {
            val cursor = db.rawQuery(
                ("SELECT * FROM " +
                        TABLE_DISPLAY_TOOL_ITEM + " WHERE " +
                        KEY_CUSTOMER_ID + "=? AND " + KEY_ITEM_BRAND_ID + "=? AND " + KEY_ITEM_CATEGORY_ID + "=?"),
                arrayOf<String>(mCustomerCode, mBrand, mCategory)
            )
            // looping through all rows and adding to list
            try {
                if (cursor.moveToFirst()) {
                    do {
                        val mData = Distribution()
                        mData.distributionId =
                            cursor.getString(cursor.getColumnIndex(KEY_DISPLAY_TOOL_ID))
                        mData.customer =
                            cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_ID))

                        var toolName = getToolName(
                            cursor.getString(cursor.getColumnIndex(KEY_DISPLAY_TOOL_ID)),
                            cursor.getString(cursor.getColumnIndex(KEY_CUSTOMER_ID))
                        )

                        mData.isPosted = checkDistributionCustomerPosted(
                            mCustomerCode,
                            cursor.getString(cursor.getColumnIndex(KEY_DISPLAY_TOOL_ID))
                        )

                        mData.name = toolName
                        if (arrData.size > 0) {
                            var isCOntain = false
                            for (mTool in arrData) {
                                if (mTool.distributionId == mData.distributionId) {
                                    isCOntain = true
                                    break
                                }
                            }
                            if (!isCOntain) {
                                arrData.add(mData)
                            }
                        } else {
                            arrData.add(mData)
                        }
                    } while (cursor.moveToNext())
                }
            } finally {
                try {
                    db.close()
                } catch (ignore: Exception) {
                }
            }
        } finally {
            try {
                db.close()
            } catch (ignore: Exception) {
            }
        }
        return arrData
    }

