    //GET Post Distribution Items
    fun getPostDistributionItem(mUniqueId: String): JsonArray {

        val arrItem = JsonArray()
        var mItem: JsonObject
        val db = this.readableDatabase
        try {
            val cursor = db.rawQuery(
                ("SELECT * FROM " +
                        TABLE_STOCK_POST_ITEM + " WHERE " +
                        KEY_UNIQUE_ID + "=?"), arrayOf<String>(mUniqueId)
            )
            try {
                if (cursor.moveToFirst()) {
                    do {
                        mItem = JsonObject()
                        mItem.addProperty(
                            "item_id", cursor.getString(
                                cursor.getColumnIndex(
                                    KEY_ITEM_ID
                                )
                            )
                        )
                        mItem.addProperty(
                            "item_uom_id", cursor.getString(
                                cursor.getColumnIndex(
                                    KEY_UOM_ID
                                )
                            )
                        )

                        mItem.addProperty(
                            "stock", cursor.getString(
                                cursor.getColumnIndex(
                                    KEY_SALEABLE_QTY
                                )
                            )
                        )

                        mItem.addProperty(
                            "capacity", cursor.getString(
                                cursor.getColumnIndex(
                                    KEY_CAPACITY
                                )
                            )
                        )

                        var mQty = cursor.getString(
                            cursor.getColumnIndex(
                                KEY_SALEABLE_QTY
                            )
                        )

                        if (mQty.toDouble() > 0) {
                            if (cursor.getString(
                                    cursor.getColumnIndex(
                                        KEY_OUT_OF_STOCK
                                    )
                                ) != null
                            ) {
                                mItem.addProperty(
                                    "is_out_of_stock", cursor.getString(
                                        cursor.getColumnIndex(
                                            KEY_OUT_OF_STOCK
                                        )
                                    )
                                )
                            } else {
                                mItem.addProperty(
                                    "is_out_of_stock", "0"
                                )
                            }
                        } else {
                            mItem.addProperty(
                                "is_out_of_stock", "1"
                            )
                        }

                        mItem.add(
                            "expiry", getPostDistributionExpItem(
                                mUniqueId, cursor.getString(
                                    cursor.getColumnIndex(
                                        KEY_ITEM_ID
                                    )
                                )
                            )
                        )
                        mItem.add(
                            "damage", getPostDistributionDERItem(
                                mUniqueId, cursor.getString(
                                    cursor.getColumnIndex(
                                        KEY_ITEM_ID
                                    )
                                )
                            )
                        )

                        mItem.add(
                            "share_of_shelf", getPostDistributionSOSItem(
                                mUniqueId, cursor.getString(
                                    cursor.getColumnIndex(
                                        KEY_ITEM_ID
                                    )
                                )
                            )
                        )

                        arrItem.add(mItem)
