    //get Post Invoice Item
    fun getPostInvoiceItem(
        invoiceNo: String,
        mDeliveryNo: String
    ): JsonArray {

        val list = JsonArray()

        val db = this.readableDatabase
        try {
            val cursor = db.rawQuery(
                ("SELECT * FROM " +
                        TABLE_INVOICE_BATCH_ITEM + " WHERE " +
                        KEY_INVOICE_NO + "=?"), arrayOf<String>(invoiceNo)
            )
            try {
                // looping through all rows and adding to list
                if (cursor.moveToFirst()) {
                    do {
                        val mItem = JsonObject()
                        var mSId = ""
                        if (mDeliveryNo.isNotEmpty()) {
                            if (cursor.getString(cursor.getColumnIndex(KEY_DELV_ITEM_ID)) != null) {
                                mSId = cursor.getString(cursor.getColumnIndex(KEY_DELV_ITEM_ID))
                            } else {
                                mSId = ""
                            }
                            mItem.addProperty(
                                "id",
                                cursor.getString(cursor.getColumnIndex(KEY_DELV_ITEM_ID))
                            )
                        }

                        var mCategoryId =
                            getItemCategoryId(cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID)))

                        if (mCategoryId == "2") {
                            mItem.addProperty(
                                "is_pallet",
                                "1"
                            )
                        } else {
                            mItem.addProperty(
                                "is_pallet",
                                "0"
                            )
                        }

                        mItem.addProperty(
                            "item_qty",
                            cursor.getString(cursor.getColumnIndex(KEY_QTY))
                        )


                        mItem.addProperty(
                            "item_id",
                            cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID))
                        )
                        mItem.addProperty(
                            "item_uom_id",
                            cursor.getString(cursor.getColumnIndex(KEY_UOM_ID))
                        )
                        mItem.addProperty(
                            "discount_id", cursor.getString(
                                cursor.getColumnIndex(
                                    KEY_DISCOUNT_ID
                                )
                            )
                        )

                        mItem.addProperty(
                            "promotion_id", cursor.getString(
                                cursor.getColumnIndex(
                                    KEY_PROMOTION_ID
                                )
                            )
                        )

                        if (cursor.getString(cursor.getColumnIndex(KEY_IS_FREE)) == "1") {
                            if (mCategoryId == "2") {
                                mItem.addProperty("is_free", false)
                            } else {
                                mItem.addProperty("is_free", true)
                            }
                        } else {
                            mItem.addProperty("is_free", false)
                        }

                        mItem.addProperty("is_item_poi", 0)

                        if (cursor.getString(cursor.getColumnIndex(KEY_UOM_PRICE)).toDouble() > 0) {
                            mItem.addProperty("is_free", false)
                        } else {
                            mItem.addProperty("is_free", true)
                        }
                        mItem.addProperty(
                            "item_price",
                            cursor.getString(cursor.getColumnIndex(KEY_UOM_PRICE))
                        )

                        mItem.addProperty(
                            "item_discount_amount",
                            cursor.getString(cursor.getColumnIndex(KEY_DISCOUNT))
                        )

                        mItem.addProperty(
                            "item_net",
                            cursor.getString(cursor.getColumnIndex(KEY_NET))
                        )
                        mItem.addProperty(
                            "item_vat",
                            cursor.getString(cursor.getColumnIndex(KEY_VAT))
                        )
                        mItem.addProperty(
                            "item_excise",
                            cursor.getString(cursor.getColumnIndex(KEY_EXCISE))
                        )

                        mItem.addProperty(
                            "item_grand_total",
                            cursor.getString(cursor.getColumnIndex(KEY_TOTAL))
                        )
                        mItem.addProperty(
                            "item_gross",
                            cursor.getString(cursor.getColumnIndex(KEY_GROSS))
                        )

                        if (mDeliveryNo.isNotEmpty()) {
                            var isCOnatin = false

                            if (mSId.isNotEmpty()) {
                                if (list.size() > 0) {
                                    for (mData in list) {
                                        if (mData.asJsonObject.get("id") != null) {
                                            if (mData.asJsonObject.get("id").asString != null) {
                                                if (mData.asJsonObject.get("id").asString == mSId) {
                                                    isCOnatin = true
                                                }
                                            }
                                        }

                                    }
                                }
                            }

                            if (!isCOnatin) {
                                list.add(mItem)
                            }
                        } else {
                            list.add(mItem)
                        }
                    } while (cursor.moveToNext())
                }
            } finally {
                try {
                    cursor.close()
                } catch (ignore: Exception) {
                }
            }
        } finally {
            try {
                db.close()
            } catch (ignore: Exception) {
            }
        }
        return list
    }


