    //GET Post isSyncTransaction
    fun isSyncCompleteTransaction(): Boolean {
        var isAvailable = false
        val db = this.readableDatabase
        try {
            val cursor = db.rawQuery(
                "SELECT * FROM " +
                        TABLE_TRANSACTION + " WHERE " +
                        TR_IS_POSTED + "=? OR " + TR_IS_POSTED + "=?", arrayOf("No", "Fail")
            )
            if (cursor.count > 0) {
                isAvailable = true
            }
            cursor.close()
        } catch (e: java.lang.Exception) {
            e.printStackTrace()
        }
        return isAvailable
    }

