    //GET Invoice Detail
    fun getPostInvoiceUUID(): JsonObject {
        val jObj = JsonObject()
        val db = this.readableDatabase
        try {
            val cursor = db.rawQuery(
                ("SELECT * FROM " +
                        TABLE_INVOICE_HEADER + " WHERE " +
                        DATA_MARK_FOR_POST + "=? AND " + KEY_IS_DELETED + "=?"),
                arrayOf<String>("M", "1")
            )
            try {
                if (cursor.moveToFirst()) {
                    try {
                        jObj.addProperty(
                            "invoice_number", cursor.getString(
                                cursor.getColumnIndex(
                                    KEY_INVOICE_NO
                                )
                            )
                        )
                        jObj.addProperty(
                            "invoice_mesage", cursor.getString(
                                cursor.getColumnIndex(
                                    KEY_INVOICE_CANCEL_REASON
                                )
                            )
                        )
                    } catch (e: JsonIOException) {
                        e.printStackTrace()
                    }
                }
            } finally {
                try {
                    db.close()
                } catch (ignore: Exception) {
                }
            }
        } catch (e: Exception) {
            e.printStackTrace()
        }
        return jObj
    }

