        contentValues.put(KEY_INVOICE_CANCEL_REASON, orderComment)
        contentValues.put(KEY_IMAGES, image)
        val db = this.writableDatabase
        return db.update(
            TABLE_DELIVERY_HEADER,
            contentValues, "$KEY_DELIVERY_NO= ? ", arrayOf(orderNo)
        )
    }

