    //Update Load Request Post
    fun updateLoadRequestPost(orderNo: String, status: String): Int {
        val contentValues = ContentValues()
        if (status.equals("1", ignoreCase = true)) {
            contentValues.put(DATA_MARK_FOR_POST, "Y")
        } else {
            contentValues.put(DATA_MARK_FOR_POST, "E")
        }
        val db = this.writableDatabase
        return db.update(
            TABLE_LOAD_REQUEST_HEADER,
            contentValues, "$KEY_ORDER_NO = ? ", arrayOf(orderNo)
        )
    }

