    fun getAllOtherPromotion(
        mRegion: String,
        mSales: String,
        mChannel: String,
        mCUstomerCategory: String,
        mRoute: String,
        mSubChannel: String,
        mParent: String,
        mCustId: String
    ): ArrayList<PromoOfferData> {
        var mList: ArrayList<PromoOfferData> = ArrayList()

        val db = this.readableDatabase

        try {

            val cursor = db.rawQuery(
                "SELECT * FROM $TABLE_PDP_PROMOTION_DETAIL WHERE $KEY_CUSTOMER_ID = '' AND $KEY_PARENT_ID = '' AND ($KEY_REGION_ID = '$mRegion' OR $KEY_CHANNEL_ID = '$mChannel' OR $KEY_SUB_CHANNEL_ID = '$mSubChannel' OR $KEY_SALES_ORG_ID = '$mSales' OR $KEY_ROUTE_ID = '$mRoute' OR $KEY_CUST_CATEGORY_ID = '$mCUstomerCategory') GROUP BY $KEY_PLAN_ID",
                null
            )

            if (cursor.moveToFirst()) {
                do {
                    var mPromoto = PromoOfferData()
                    mPromoto.promotionId = cursor.getString(cursor.getColumnIndex(KEY_PLAN_ID))
                    mPromoto.promotionName = cursor.getString(
                        cursor.getColumnIndex(
                            KEY_PROMOTION_NAME
                        )
                    )
                    mPromoto.orderType = cursor.getString(cursor.getColumnIndex(KEY_ORDER_ITEM))
                    mPromoto.offerType = cursor.getString(cursor.getColumnIndex(KEY_OFFER_ITEM))
                    mPromoto.isCombination =
                        cursor.getString(cursor.getColumnIndex(KEY_IS_COMBINATION))
                    mPromoto.type =
                        cursor.getString(cursor.getColumnIndex(KEY_TYPE))
                    mPromoto.discType =
                        cursor.getString(cursor.getColumnIndex(KEY_DISCOUNT_TYPE))
                    mPromoto.orderPromo =
                        getPromoOrderDetail(cursor.getString(cursor.getColumnIndex(KEY_PLAN_ID)))
                    mPromoto.offerPromo =
                        getPromoOfferDetail(cursor.getString(cursor.getColumnIndex(KEY_PLAN_ID)))

                    mPromoto.isApply = ""

                    var keyValue =
                        cursor.getString(cursor.getColumnIndex(KEY_COMBINATION_KEY_VALUE))
                    var route = cursor.getString(cursor.getColumnIndex(KEY_ROUTE_ID))
                    var channel = cursor.getString(cursor.getColumnIndex(KEY_CHANNEL_ID))
                    var subCHannel = cursor.getString(cursor.getColumnIndex(KEY_SUB_CHANNEL_ID))

                    var isApply = false
                    if (keyValue == "461210" || keyValue == "461211") {
                        if (route == mRoute && channel == mChannel && subCHannel == mSubChannel) {
                            isApply = true
                        }
                    } else if (keyValue == "61210" || keyValue == "61211") {
                        if (channel == mChannel && subCHannel == mSubChannel) {
                            isApply = true
                        }
                    } else if (keyValue == "610" || keyValue == "611") {
                        if (channel == mChannel) {
                            isApply = true
                        }
                    } else if (keyValue == "1211" || keyValue == "1210") {
                        if (subCHannel == mSubChannel) {
                            isApply = true
                        }
                    }

                    if (isApply) {
                        if (!isPromoExcludeCUst(
                                mCustId,
                                cursor.getString(cursor.getColumnIndex(KEY_PLAN_ID))
                            )
                        ) {
                            mList.add(mPromoto)
                        }
                    }


                } while (cursor.moveToNext())

            }
            cursor.close()
        } catch (e: Exception) {
            e.printStackTrace()
        }

        return mList
    }


