    fun getPromoOfferItemIdData(mPromoId: String): ArrayList<Item> {
        var mList: ArrayList<Item> = ArrayList()

        val db = this.readableDatabase

        var cursor = db.rawQuery(
            ("SELECT * FROM " +
                    TABLE_PROMOTION_OFFER_ITEM + " WHERE " +
                    KEY_PROMOTION_ID + "=?"), arrayOf<String>(mPromoId)
        )

        try {
            if (cursor.moveToFirst()) {
                do {

                    val mItem =
                        getItemDetailFromId(cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID)))
                    var mOferItem = Item()
                    mOferItem.itemId = mItem!!.id.toString()
                    mOferItem.itemCode = mItem!!.itemCode
                    mOferItem.itemName = mItem!!.itemName
                    mOferItem.itemQty = ""

                    if (mList.size > 0) {
                        var mContain = false
                        for (mData in mList) {
                            if (mData.itemId!!.toString() == mItem!!.id.toString()) {
                                mContain = true
                                break
                            }
                        }

                        if (!mContain) {
                            mList.add(mOferItem)
                        }
                    } else {
                        mList.add(mOferItem)
                    }

                } while (cursor.moveToNext())
            }
        } finally {
            try {
                db.close()
            } catch (ignore: Exception) {
            }
        }

        return mList
    }

