    fun getItemStock(
        mItemId: String
    ): Double {
        var mList = 0.0

        val db = this.readableDatabase

        try {

            val cursor = db.rawQuery(
                ("SELECT * FROM " +
                        TABLE_DELIVERY_ITEM + " WHERE " +
                        KEY_ITEM_ID + "=? AND " + KEY_DELIVERY_STATUS + "=?"),
                arrayOf<String>(mItemId, "0")
            )

            if (cursor.moveToFirst()) {

                do {
                    var lowerId =
                        getItemLowerUnit(cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID)))

                    if (lowerId == cursor.getString(cursor.getColumnIndex(KEY_UOM_ID))) {
                        mList += cursor.getString(cursor.getColumnIndex(KEY_QTY)).toDouble()
                    } else {
                        var uPC = getItemUOMUPC(
                            cursor.getString(cursor.getColumnIndex(KEY_ITEM_ID)),
                            cursor.getString(cursor.getColumnIndex(KEY_UOM_ID))
                        )
                        var lowerQTy = uPC.toDouble() * cursor.getString(
                            cursor.getColumnIndex(
                                KEY_QTY
                            )
                        ).toDouble()
                        mList += lowerQTy

                    }
                } while (cursor.moveToNext())

            }
            cursor.close()
        } catch (e: Exception) {
            e.printStackTrace()
        }

        return mList
    }

