    fun checkMenuActive(idd: String): String {
        var name: String = "0"

        val db = this.readableDatabase

        try {
            var cursor = db.rawQuery(
                ("SELECT * FROM " +
                        TABLE_SALESMAN_ACTIVE_MENU + " WHERE " +
                        KEY_MENU_NAME + "=?"), arrayOf<String>(idd)
            )
            cursor.moveToFirst()
            val count = cursor.getCount()
            if (count > 0)
                name = cursor.getString(cursor.getColumnIndex(KEY_IS_ACTIVE))
            cursor.close()
        } catch (e: Exception) {
            e.printStackTrace()
        }

        return name
    }

