        )
            ?: return itemExist
        while (c.moveToNext()) {
            itemExist = true
        }
        c.close()
        return itemExist
    }

    fun checkInvoiceExist(mItemId: String): Boolean {
        val db = this.readableDatabase
        var itemExist = false
        val c = db.query(
            TABLE_INVOICE_HEADER,
            null,
            "$KEY_INVOICE_NO = ?",
            arrayOf<String>(mItemId),
            null,
            null,
            null
        )
            ?: return itemExist
        while (c.moveToNext()) {
            itemExist = true
        }
        c.close()
        return itemExist
    }

    fun checkItemMultipleUOM(mItemId: String): Boolean {
        val db = this.readableDatabase
        var itemExist = false
        val c = db.query(
            TABLE_ITEM_UOM,
            null,
            "$KEY_ITEM_ID = ?",
            arrayOf<String>(mItemId),
            null,
            null,
            null
        )
            ?: return itemExist
        while (c.moveToNext()) {
            itemExist = true
        }
        c.close()
        return itemExist
    }

